iguration.v01', invocation.inputs)\n\n\ndef execute_observability_v01(invocation):\n return compute('sentinel.observability.v01',invocation.inputs)\n\n\ndef catalogue(root, session):\n return (admit(root,'sentinel.compile.v01',execute_compile_v01),\n admit(root,'sentinel.contract.v01',execute_contract_v01),\n admit(root,'sentinel.command.v01',execute_command_v01,True,(session,)),\n admit(root,'sentinel.diagnostic.v01',execute_diagnostic_v01),\n admit(root,'sentinel.information.v01',execute_information_v01),\n admit(root,'sentinel.configuration.v01',execute_configuration_v01),\n admit(root,'sentinel.observability.v01',execute_observability_v01))\n"}],"definition":{"business_semantics":{"business_object_class":"DOMAIN_OBJECT","business_object_namespace":"sentinel.command","input_bindings":[{"input_name":"command","source_kind":"RECORD","source_name":"command","value_type":"TEXT"},{"input_name":"session","source_kind":"RECORD","source_name":"session","value_type":"REFERENCE"},{"input_name":"version","source_kind":"RECORD","source_name":"version","value_type":"INTEGER"}],"logical_effect_class":"LOCAL_MONITORING_COMMAND","logical_effect_namespace":"sentinel.command.v01","operation_key":"sentinel.command.v01","selected_action_class":"mock_action:sentinel_monitoring_command"},"code_sha256s":[["hedgehog.domains.landslide_sentinel.capability_registry_v01.execute_command_v01","2542479dddc7485cb1e2220fac51dd59849d571054c1c912b3be3dbd58b0dd28"],["hedgehog.domains.landslide_sentinel.capability_registry_v01.validate_inputs_v01","2542479dddc7485cb1e2220fac51dd59849d571054c1c912b3be3dbd58b0dd28"],["hedgehog.domains.landslide_sentinel.capability_registry_v01.validate_outputs_v01","2542479dddc7485cb1e2220fac51dd59849d571054c1c912b3be3dbd58b0dd28"]],"contract_sha256":"f4a3d5b2fc650a7f42063c488b41716600d94c39414494ea84606444f1a91453","definition_id":"capability_definition:92af37a59646465e110f3de23a937937622bebee06f5521a2529d985e41fff5c","effect_kind":"MOCK_CONSEQUENTIAL","executor_ref"