def validate_action_commit_packet_v02( packet: ActionCommitPacketV02, ) -> tuple[bool, tuple[str, ...]]: reasons: list[str] = []
if not _non_empty(packet.packet_id): _append_reason(reasons, REASON_MISSING_PACKET_ID)
if not packet.root_created: _append_reason(reasons, REASON_MISSING_ROOT_CREATION) if packet.created_by != "root" or not packet.root_created: _append_reason(reasons, REASON_ROOT_ONLY_PACKET_CREATION_REQUIRED) creator_reason = _source_creator_reason(packet.created_by) if creator_reason is not None: _append_reason(reasons, creator_reason)
if not _non_empty(packet.source_root_decision_ref): _append_reason(reasons, REASON_MISSING_SOURCE_ROOT_DECISION_REF) if not _non_empty(packet.human_approval_ref): _append_reason(reasons, REASON_MISSING_HUMAN_APPROVAL_REF)
scope = packet.scope if not isinstance(scope, PermissionScopeV02): _append_reason(reasons, REASON_MISSING_SCOPE) else: if ( not _all_non_empty(scope.allowed_subjects) or not _all_non_empty(scope.forbidden_subjects) or not _all_non_empty(scope.allowed_actions) or not _all_non_empty(scope.forbidden_actions) or not _all_non_empty(scope.allowed_adapters) or not _all_non_empty(scope.forbidden_adapters) or not _non_empty(scope.payment_slot_ref) or not _non_empty(scope.creditor_ref) or not _non_empty(scope.amount) or not _non_empty(scope.currency) ): _append_reason(reasons, REASON_MISSING_SCOPE) if ( SUBJECT_SUPPLIER_B in scope.allowed_subjects or ACTION_SUPPLIER_B_PAYMENT in scope.allowed_actions ): _append_reason(reasons, REASON_SUPPLIER_B_SCOPE_FORBIDDEN) if ( SUBJECT_SHIPMENT_SH_2042 in scope.allowed_subjects or ACTION_SHIPMENT_RELEASE in scope.allowed_actions ): _append_reason(reasons, REASON_SHIPMENT_RELEASE_FORBIDDEN) if ( ACTION_REAL_PAYMENT in scope.allowed_actions or ACTION_REAL_BANK_TRANSFER in scope.allowed_actions ): _append_reason(reasons, REASON_REAL_WORLD_EFFECTS_FORBIDDEN) if ADAPTER_REAL_BANK in scope.allowed_adapters: _append_reason(reasons, REASON_REAL_BANK_ADAPTER_FORBIDDEN) if ADAPTER_REAL_SUPPLIER_API in scope.allowed_adapters: _append_reason(reasons, REASON_REAL_SUPPLIER_API_FORBIDDEN) if ADAPTER_REAL_WAREHOUSE_API in scope.allowed_adapters: _append_reason(reasons, REASON_REAL_WAREHOUSE_API_FORBIDDEN)
ttl = packet.ttl if not isinstance(ttl, PacketTTL): _append_reason(reasons, REASON_MISSING_TTL) else: if ttl.ttl_seconds <= 0 or not ttl.ttl_valid: _append_reason(reasons, REASON_INVALID_TTL) if ttl.expired: _append_reason(reasons, REASON_EXPIRED_PACKET)
idempotency = packet.idempotency if not isinstance(idempotency, IdempotencyKeyV02) or not _non_empty( getattr(idempotency, "key", ""), ): _append_reason(reasons, REASON_MISSING_IDEMPOTENCY_KEY) else: if idempotency.duplicate_packet_id: _append_reason(reasons, REASON_DUPLICATE_PACKET_ID) if ( idempotency.duplicate_idempotency_key and idempotency.terminal_receipt_already_exists ): _append_reason(reasons, REASON_DUPLICATE_IDEMPOTENCY_KEY)
adapter_binding = packet.adapter_binding if ( adapter_binding.real_adapter or adapter_binding.adapter_id == ADAPTER_REAL_BANK ): _append_reason(reasons, REASON_REAL_BANK_ADAPTER_FORBIDDEN) if adapter_binding.adapter_id == ADAPTER_REAL_SUPPLIER_API: _append_reason(reasons, REASON_REAL_SUPPLIER_API_FORBIDDEN) if adapter_binding.adapter_id == ADAPTER_REAL_WAREHOUSE_API: _append_reason(reasons, REASON_REAL_WAREHOUSE_API_FORBIDDEN) if ( isinstance(scope, PermissionScopeV02) and adapter_binding.adapter_id not in scope.allowed_adapters ): _append_reason(reasons, REASON_ADAPTER_BINDING_NOT_ALLOWED_BY_PACKET)
if not packet.receipt_evidence_only: _append_reason(reasons, REASON_RECEIPT_IS_EVIDENCE_ONLY) if packet.real_world_effects_allowed: _append_reason(reasons, REASON_REAL_WORLD_EFFECTS_FORBIDDEN) if packet.production_ready_claimed: _append_reason(reasons, REASON_PRODUCTION_CLAIM_NOT_ALLOWED) if packet.public_auditor_ready_claimed: _append_reason(reasons, REASON_PUBLIC_AUDITOR_CLAIM_NOT_ALLOWED)
return not reasons, tuple(reasons)
def validate_corridor_no_post_root_reasoning_v01( corridor: ContractFulfillmentCorridorV01, ) -> tuple[bool, tuple[str, ...]]: reasons: list[str] = [] if not corridor.deterministic_only: _append_reason(reasons, REASON_NO_EXPANSION_AFTER_ROOT) if corridor.post_root_llm_reasoning_allowed: _append_reason(reasons, REASON_NO_POST_ROOT_LLM_REASONING) if corridor.reasoning_restarted_after_root: _append_reason(reasons, REASON_REASONING_DOES_NOT_RESTART_AFTER_ROOT) return not reasons, tuple(reasons)
