def _canonical_absent_v01() -> Mapping[str, str]: return ABSENT_V01
def is_absent_v01(value: object) -> bool: return value is ABSENT_V01
def _result_v01(reasons: list[str]) -> tuple[bool, tuple[str, ...]]: return not reasons, tuple(dict.fromkeys(reasons))
def _reason_v01(reasons: list[str], reason: str) -> None: if reason not in reasons: reasons.append(reason)
def _stable_exception_reason_v01( exc: ValueError, *, fallback: str, ) -> str: if ( len(exc.args) == 1 and type(exc.args[0]) is str and re.fullmatch(r"[a-z][a-z0-9_]*", exc.args[0]) is not None ): return exc.args[0] return fallback
def validate_identity_text_v01( value: object, *, allow_empty: bool = False, ) -> tuple[bool, tuple[str, ...]]: reasons: list[str] = [] if type(allow_empty) is not bool: return False, ("identity_text_allow_empty_type_invalid",) if type(value) is not str: return False, ("identity_text_type_invalid",) # Exact ASCII strings are already UTF-8/NFC. Keep the full reason path otherwise. if value.isascii() and "\x00" not in value and (allow_empty or value): return True, () try: value.encode("utf-8", errors="strict") except UnicodeError: return False, ("identity_text_surrogate_invalid",) if "\x00" in value: _reason_v01(reasons, "identity_text_nul_invalid") if not allow_empty and not value: _reason_v01(reasons, "identity_text_empty") try: if unicodedata.normalize("NFC", value) != value: _reason_v01(reasons, "identity_text_not_nfc") except Exception: _reason_v01(reasons, "identity_text_normalization_invalid") return _result_v01(reasons)
def normalize_identity_text_v01( value: object, *, allow_empty: bool = False, ) -> str: if type(allow_empty) is not bool: raise ValueError("identity_text_allow_empty_type_invalid") if type(value) is not str: raise ValueError("identity_text_type_invalid") try: normalized = unicodedata.normalize("NFC", value) normalized.encode("utf-8", errors="strict") except Exception: raise ValueError("identity_text_normalization_invalid") from None valid, reasons = validate_identity_text_v01( normalized, allow_empty=allow_empty, ) if not valid: raise ValueError(reasons[0]) return normalized
def validate_lowercase_sha256_hex_v01( value: object, ) -> tuple[bool, tuple[str, ...]]: if type(value) is not str: return False, ("sha256_type_invalid",) try: valid = re.fullmatch(LOWERCASE_SHA256_REGEX_V01, value) is not None except Exception: valid = False return (True, ()) if valid else (False, ("sha256_format_invalid",))
def validate_signed_int64_v01( value: object, ) -> tuple[bool, tuple[str, ...]]: if type(value) is not int: return False, ("int64_type_invalid",) if value < INT64_MIN_V01 or value > INT64_MAX_V01: return False, ("int64_range_invalid",) return True, ()
def validate_positive_int_v01( value: object, ) -> tuple[bool, tuple[str, ...]]: valid, reasons = validate_signed_int64_v01(value) if not valid: return valid, reasons if value <= 0: return False, ("positive_int_invalid",) return True, ()
def canonicalize_set_like_string_tuple_v01(value: object) -> tuple[str, ...]: if type(value) is not tuple: raise ValueError("set_like_tuple_type_invalid") normalized: list[str] = [] for item in value: normalized.append(normalize_identity_text_v01(item)) if len(normalized) != len(set(normalized)): raise ValueError("set_like_tuple_duplicate") return tuple(sorted(normalized, key=lambda item: item.encode("utf-8")))
def validate_set_like_string_tuple_v01( value: object, *, require_non_empty: bool = False, ) -> tuple[bool, tuple[str, ...]]: if type(require_non_empty) is not bool: return False, ("set_like_tuple_require_non_empty_type_invalid",) try: canonical = canonicalize_set_like_string_tuple_v01(value) except ValueError as exc: return False, ( _stable_exception_reason_v01( exc, fallback="set_like_tuple_invalid", ), ) except Exception: return False, ("set_like_tuple_invalid",) if require_non_empty and not canonical: return False, ("set_like_tuple_empty",) if canonical != value: return False, ("set_like_tuple_not_canonical",) return True, ()
def preserve_ordered_string_tuple_v01(value: object) -> tuple[str, ...]: if type(value) is not tuple: raise ValueError("ordered_tuple_type_invalid") return tuple(normalize_identity_text_v01(item) for item in value)
def _validate_ordered_string_tuple_v01( value: object, ) -> tuple[bool, tuple[str, ...]]: try: canonical = preserve_ordered_string_tuple_v01(value) except ValueError as exc: return False, ( _stable_exception_reason_v01( exc, fallback="ordered_tuple_invalid", ), ) except Exception: return False, ("ordered_tuple_invalid",) if canonical != value: return False, ("ordered_tuple_not_canonical",) return True, ()
def _validate_canonical_material_structure_v01( material: object, ) -> tuple[bool, tuple[str, ...], tuple[str, ...]]: reasons: list[str] = [] if type(material) is not tuple: return False, ("canonical_material_type_invalid",), () if not material: return False, ("canonical_material_empty",), () fields: list[str] = [] for pair in material: if type(pair) is not tuple or len(pair) != 2: _reason_v01(reasons, "canonical_material_pair_invalid") continue name = pair[0] valid_name, _ = validate_identity_text_v01(name) if not valid_name: _reason_v01(reasons, "canonical_material_field_name_invalid") continue fields.append(name) if not _canonical_identity_value_is_valid_v01(pair[1]): _reason_v01(reasons, "canonical_material_value_invalid") if len(fields) != len(set(fields)): _reason_v01(reasons, "canonical_material_field_duplicate") valid, reason_tuple = _result_v01(reasons) return valid, reason_tuple, tuple(fields)
def validate_canonical_profile_material_v01( material: object, *, expected_field_names: object = None, ) -> tuple[bool, tuple[str, ...]]: reasons: list[str] = [] if type(expected_field_names) is not tuple: return False, ("canonical_material_expected_fields_type_invalid",) if not expected_field_names: return False, ("canonical_material_expected_fields_empty",) expected_names: list[str] = [] for name in expected_field_names: valid_name, _ = validate_identity_text_v01(name) if not valid_name: return False, ("canonical_material_expected_field_name_invalid",) expected_names.append(name) if len(expected_names) != len(set(expected_names)): return False, ("canonical_material_expected_field_duplicate",) structure_valid, structure_reasons, fields = ( _validate_canonical_material_structure_v01(material) ) if not structure_valid: reasons.extend(structure_reasons) if tuple(fields) != tuple(expected_names): if len(fields) < len(expected_names): _reason_v01(reasons, "canonical_material_field_missing") if len(fields) > len(expected_names): _reason_v01(reasons, "canonical_material_field_unknown") _reason_v01(reasons, "canonical_material_field_order_invalid") return _result_v01(reasons)
def _canonical_identity_value_is_valid_v01(value: object) -> bool: if value is ABSENT_V01: return True if type(value) is str: return validate_identity_text_v01(value, allow_empty=True)[0] if type(value) is bool: return True if type(value) is int: return validate_signed_int64_v01(value)[0] if type(value) is tuple: return all(_canonical_identity_value_is_valid_v01(item) for item in value) return False
def canonical_material_bytes_v01(material: object) -> bytes: structurally_valid, structural_reasons, field_names = ( _validate_canonical_material_structure_v01(material) ) if not structurally_valid: raise ValueError(structural_reasons[0]) # Structure validation already proves these exact field names valid, unique # and ordered. Comparing the material with its own names adds no predicate. try: # The narrower material grammar already excludes cycles, mutable values, # floats, surrogates and caller serializers. Tuple JSON is identical to # the general canonicalizer's list projection; only ABSENT needs mapping. return _json.dumps(material, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False, default=_canonical_material_absent_plain_v01).encode("utf-8", errors="strict") except Exception: raise ValueError("canonical_material_encoding_invalid") from None
def _canonical_material_absent_plain_v01(value: object) -> dict[str, str]: if value is not ABSENT_V01: raise ValueError("canonical_material_encoding_invalid") return dict(ABSENT_V01)
def build_domain_separated_identity_v01( *, domain: str, prefix: str, material: CanonicalMaterialV01, ) -> str: valid_domain, domain_reasons = validate_identity_text_v01(domain) valid_prefix, prefix_reasons = validate_identity_text_v01(prefix) if not valid_domain: raise ValueError(domain_reasons[0]) if not valid_prefix: raise ValueError(prefix_reasons[0]) payload = canonical_material_bytes_v01(material) digest = domain_separated_sha256_hex_v01( domain=domain, payload=payload, ) return prefix + digest
def validate_prefixed_sha256_identity_v01( value: object, *, prefix: object = None, ) -> tuple[bool, tuple[str, ...]]: valid_prefix, _ = validate_identity_text_v01(prefix) if not valid_prefix: return False, ("prefixed_identity_prefix_type_invalid",) if type(value) is not str: return False, ("prefixed_identity_type_invalid",) if not value.startswith(prefix): return False, ("prefixed_identity_prefix_invalid",) valid, _ = validate_lowercase_sha256_hex_v01(value[len(prefix) :]) return (True, ()) if valid else (False, ("prefixed_identity_digest_invalid",))
def validate_canonical_decimal_v01( value: object, ) -> tuple[bool, tuple[str, ...]]: if type(value) is not str: return False, ("canonical_decimal_type_invalid",) try: valid = re.fullmatch(CANONICAL_DECIMAL_REGEX_V01, value) is not None except Exception: valid = False if not valid: return False, ("canonical_decimal_format_invalid",) return True, ()
def normalize_legacy_decimal_v01(value: object) -> str: if type(value) is not str: raise ValueError("legacy_decimal_type_invalid") try: if re.fullmatch(LEGACY_PLAIN_DECIMAL_INPUT_REGEX_V01, value) is None: raise ValueError("legacy_decimal_format_invalid") decimal_value = Decimal(value) except ValueError: raise except (InvalidOperation, ArithmeticError): raise ValueError("legacy_decimal_format_invalid") from None if not decimal_value.is_finite(): raise ValueError("legacy_decimal_non_finite") if decimal_value.is_zero() and value.startswith("-"): raise ValueError("legacy_decimal_negative_zero") if "." in value: normalized = value.rstrip("0").rstrip(".") else: normalized = value valid, reasons = validate_canonical_decimal_v01(normalized) if not valid: raise ValueError(reasons[0]) return normalized
def validate_legacy_decimal_v01( value: object, ) -> tuple[bool, tuple[str, ...]]: try: normalize_legacy_decimal_v01(value) except ValueError as exc: return False, ( _stable_exception_reason_v01( exc, fallback="legacy_decimal_invalid", ), ) except Exception: return False, ("legacy_decimal_invalid",) return True, ()
def validate_canonical_execution_time_v01( value: object, ) -> tuple[bool, tuple[str, ...]]: if type(value) is CanonicalExecutionTimeV01: return validate_signed_int64_v01(value.value) return validate_signed_int64_v01(value)
def build_canonical_execution_time_v01( value: object, ) -> CanonicalExecutionTimeV01: valid, reasons = validate_signed_int64_v01(value) if not valid: raise ValueError(reasons[0]) return CanonicalExecutionTimeV01(value=value)
def parse_utc_timestamp_v01(value: object) -> int: if type(value) is not str: raise ValueError("timestamp_type_invalid") try: if re.fullmatch(UTC_TIMESTAMP_COMPATIBILITY_REGEX_V01, value) is None: raise ValueError("timestamp_format_invalid") year = int(value[0:4]) month = int(value[5:7]) day_value = int(value[8:10]) hour = int(value[11:13]) minute = int(value[14:16]) second = int(value[17:19]) if year < 1 or hour > 23 or minute > 59 or second > 59: raise ValueError("timestamp_component_invalid") parsed_date = date(year, month, day_value) epoch_date = date(1970, 1, 1) epoch_seconds = ( (parsed_date - epoch_date).days * 86400 + hour * 3600 + minute * 60 + second ) except ValueError as exc: reason = _stable_exception_reason_v01( exc, fallback="timestamp_calendar_invalid", ) if reason in ("timestamp_format_invalid", "timestamp_component_invalid"): raise raise ValueError("timestamp_calendar_invalid") from None except Exception: raise ValueError("timestamp_invalid") from None valid, reasons = validate_signed_int64_v01(epoch_seconds) if not valid: raise ValueError(reasons[0]) return epoch_seconds
def validate_utc_timestamp_v01( value: object, ) -> tuple[bool, tuple[str, ...]]: try: parse_utc_timestamp_v01(value) except ValueError as exc: return False, ( _stable_exception_reason_v01( exc, fallback="timestamp_invalid", ), ) except Exception: return False, ("timestamp_invalid",) return True, ()
def format_utc_timestamp_v01(epoch_seconds: object) -> str: valid, reasons = validate_signed_int64_v01(epoch_seconds) if not valid: raise ValueError(reasons[0]) try: day_offset, second_of_day = divmod(epoch_seconds, 86400) epoch_date = date(1970, 1, 1) calendar_date = date.fromordinal(epoch_date.toordinal() + day_offset) hour, remainder = divmod(second_of_day, 3600) minute, second = divmod(remainder, 60) formatted = ( f"{calendar_date.year:04d}-{calendar_date.month:02d}-" f"{calendar_date.day:02d}T{hour:02d}:{minute:02d}:{second:02d}Z" ) except Exception: raise ValueError("timestamp_output_range_invalid") from None try: if parse_utc_timestamp_v01(formatted) != epoch_seconds: raise ValueError("timestamp_round_trip_invalid") except ValueError as exc: raise ValueError( _stable_exception_reason_v01( exc, fallback="timestamp_round_trip_invalid", ) ) from None return formatted
def build_action_temporal_authority_profile_v01( *, issued_at_utc: object, expires_at_utc: object, ttl_seconds: object, temporal_policy_version: object, ) -> ActionTemporalAuthorityProfileV01: valid_issued, issued_reasons = validate_signed_int64_v01(issued_at_utc) valid_expires, expires_reasons = validate_signed_int64_v01(expires_at_utc) valid_ttl, ttl_reasons = validate_positive_int_v01(ttl_seconds) try: policy = normalize_identity_text_v01(temporal_policy_version) except ValueError as exc: raise ValueError( _stable_exception_reason_v01( exc, fallback="temporal_policy_version_invalid", ) ) from None if not valid_issued: raise ValueError(issued_reasons[0]) if not valid_expires: raise ValueError(expires_reasons[0]) if not valid_ttl: raise ValueError(ttl_reasons[0]) try: expected_expires = issued_at_utc + ttl_seconds except Exception: raise ValueError("temporal_authority_arithmetic_invalid") from None valid_sum, _ = validate_signed_int64_v01(expected_expires) if not valid_sum: raise ValueError("temporal_authority_overflow") if expires_at_utc != expected_expires: raise ValueError("temporal_authority_inconsistent") return ActionTemporalAuthorityProfileV01( issued_at_utc=issued_at_utc, expires_at_utc=expires_at_utc, ttl_seconds=ttl_seconds, temporal_policy_version=policy, )
def validate_action_temporal_authority_profile_v01( value: object, ) -> tuple[bool, tuple[str, ...]]: if type(value) is not ActionTemporalAuthorityProfileV01: return False, ("temporal_authority_type_invalid",) try: rebuilt = build_action_temporal_authority_profile_v01( issued_at_utc=value.issued_at_utc, expires_at_utc=value.expires_at_utc, ttl_seconds=value.ttl_seconds, temporal_policy_version=value.temporal_policy_version, ) except ValueError as exc: return False, ( _stable_exception_reason_v01( exc, fallback="temporal_authority_invalid", ), ) except Exception: return False, ("temporal_authority_invalid",) return (True, ()) if rebuilt == value else ( False, ("temporal_authority_not_canonical",), )
def action_temporal_authority_material_v01( value: ActionTemporalAuthorityProfileV01, ) -> CanonicalMaterialV01: valid, reasons = validate_action_temporal_authority_profile_v01(value) if not valid: raise ValueError(reasons[0]) return ( ("issued_at_utc", value.issued_at_utc), ("expires_at_utc", value.expires_at_utc), ("ttl_seconds", value.ttl_seconds), ("temporal_policy_version", value.temporal_policy_version), )
