"""Finite PURE needs, independent admission and the fixed native bridge.
Generated code is data. Host-held origins and resource reservations distinguish an observed admission from a caller-created evidence value. """ from contextvars import ContextVar from dataclasses import dataclass, asdict, field, replace import hashlib import json from pathlib import Path import jsonschema from hedgehog import action_commit_packet_v02 as action from hedgehog import wasm_pure_worker_v01 as worker from hedgehog.kernel import effect_firewall_v01 as firewall
