def semantic_evidence_item( text: str, *, source: str, evidence_kind: str, confidence_label: str = "unknown", candidate_only: bool = True, raw_quote: bool = False, ) -> dict[str, Any]: return { "text": str(text).strip(), "source": source, "evidence_kind": evidence_kind, "confidence_label": confidence_label, "candidate_only": candidate_only, "raw_quote": raw_quote, }
def _default_semantic_evidence_item( text: str, *, evidence_kind: str, ) -> dict[str, Any]: return semantic_evidence_item( text, source="runtime_canonicalization", evidence_kind=evidence_kind, confidence_label="unknown", )
def _as_evidence_item_tuple( value: Iterable[Mapping[str, Any]] | None, *, default_text: str, evidence_kind: str, ) -> tuple[dict[str, Any], ...]: if value is None: return (_default_semantic_evidence_item(default_text, evidence_kind=evidence_kind),) return tuple(dict(item) for item in value)
def validate_semantic_evidence_items( items: Any, *, field: str, ) -> tuple[str, ...]: reasons: list[str] = [] if not _is_non_string_sequence(items): return (f"bounded_semantic_evidence_items_must_be_sequence:{field}",) if not items: return (f"bounded_semantic_evidence_empty_field:{field}",) if len(items) > BOUNDED_SEMANTIC_EVIDENCE_MAX_ITEMS_PER_FIELD: _append_reason(reasons, f"bounded_semantic_evidence_too_many_items:{field}")
for item in items: if not isinstance(item, Mapping): _append_reason( reasons, f"bounded_semantic_evidence_item_must_be_mapping:{field}", ) continue
text = item.get("text") if not isinstance(text, str) or not text.strip(): _append_reason(reasons, f"bounded_semantic_evidence_item_empty_text:{field}") elif len(text.strip()) > BOUNDED_SEMANTIC_EVIDENCE_MAX_ITEM_TEXT_LENGTH: _append_reason( reasons, f"bounded_semantic_evidence_item_text_too_long:{field}", )
if "source" not in item: _append_reason( reasons, f"bounded_semantic_evidence_item_missing_source:{field}", ) elif item.get("source") not in BOUNDED_SEMANTIC_EVIDENCE_ITEM_SOURCES: _append_reason( reasons, f"bounded_semantic_evidence_item_source_not_allowed:{field}", )
if "evidence_kind" not in item: _append_reason( reasons, f"bounded_semantic_evidence_item_missing_kind:{field}", ) elif item.get("evidence_kind") not in BOUNDED_SEMANTIC_EVIDENCE_ITEM_KINDS: _append_reason( reasons, f"bounded_semantic_evidence_item_kind_not_allowed:{field}", )
if item.get("confidence_label") not in BOUNDED_SEMANTIC_EVIDENCE_CONFIDENCE_LABELS: _append_reason( reasons, f"bounded_semantic_evidence_item_confidence_label_not_allowed:{field}", ) if item.get("candidate_only") is not True: _append_reason( reasons, f"bounded_semantic_evidence_item_candidate_only_must_be_true:{field}", ) if item.get("raw_quote") is not False: _append_reason( reasons, f"bounded_semantic_evidence_item_raw_quote_must_be_false:{field}", ) return tuple(reasons)
def _runtime_bounded_semantic_evidence_creator(created_by: Any) -> bool: if not isinstance(created_by, str): return False creator = created_by.strip().lower() if not creator.startswith("runtime/"): return False return "gemini" not in creator and "provider" not in creator
def _bounded_semantic_evidence_raw_text_reasons( packet: Mapping[str, Any], ) -> tuple[str, ...]: reasons: list[str] = [] for key, _value in _walk_key_values(packet): key_text = key or "" if key_text in {"raw_user_request", "raw_user_text"}: _append_reason(reasons, "bounded_semantic_evidence_raw_user_text_forbidden") if key_text == "raw_cross_role_text": _append_reason( reasons, "bounded_semantic_evidence_raw_cross_role_text_forbidden", ) if key_text == "raw_gemini_text": _append_reason( reasons, "bounded_semantic_evidence_raw_gemini_text_forbidden", ) return tuple(reasons)
def _bounded_semantic_evidence_unbounded_dump_reasons( packet: Mapping[str, Any], ) -> tuple[str, ...]: reasons: list[str] = [] for key, _value in _walk_key_values(packet): key_text = key or "" if key_text in {"full_runner_state_dump", "unbounded_context_dump"}: _append_reason(reasons, "unbounded_context_dump_forbidden") if key_text in {"raw_plan_graph_context", "raw_plangraph_context"}: _append_reason(reasons, "unbounded_plangraph_context_dump_forbidden") return tuple(reasons)
def _bounded_semantic_evidence_string_sequence_reasons( value: Any, *, field: str, ) -> tuple[str, ...]: reasons: list[str] = [] if not _is_non_string_sequence(value): return (f"bounded_semantic_evidence_items_must_be_sequence:{field}",) if not value: return (f"bounded_semantic_evidence_empty_field:{field}",) for item in value: if not isinstance(item, str): _append_reason( reasons, f"bounded_semantic_evidence_item_must_be_string:{field}", ) elif not item.strip(): _append_reason( reasons, f"bounded_semantic_evidence_empty_item:{field}", ) return tuple(reasons)
def _bounded_surface_text_has_marker(text: str) -> bool: lowered = text.lower() spaced = lowered.replace("_", " ").replace("-", " ") compact = spaced.replace(" ", "") phrase_markers = ( "action permission", "connector command", "final output", "real world effect", "real robot api", "direct action", "door unlock", "dispatch robot", "execute payment", "payment executed", "shipment released", "create action permission", ) compact_markers = ("actioncommitpacket",) return any(marker in spaced for marker in phrase_markers) or any( marker in compact for marker in compact_markers )
def _bounded_evidence_item_text_is_safe_negative_surface_context( item: Mapping[str, Any], ) -> bool: text = item.get("text") if not isinstance(text, str): return False if item.get("candidate_only") is not True or item.get("raw_quote") is not False: return False if item.get("evidence_kind") not in { "rejected_route", "risk_boundary", "authority_boundary", "approval_condition", "missing_evidence", "uncertainty", }: return False
lowered = text.lower() spaced = lowered.replace("_", " ").replace("-", " ") compact = spaced.replace(" ", "") unsafe_positive_markers = ( "execute payment", "payment executed", "shipment released", "connector command should run", "create action permission", "real world effect allowed", ) unsafe_positive_compact_markers = ("actioncommitpacketcreated",) if any(marker in spaced for marker in unsafe_positive_markers): return False if any(marker in compact for marker in unsafe_positive_compact_markers): return False
safe_negative_markers = ( "rejected", "blocked", "forbidden", "not allowed", "no delegated authority", "no action permission", "without authority", "cannot be authorized", "not authority", "not permission", "root review", "rather than direct action", "must not", "do not", "does not", "is not", "are not", ) return any(marker in spaced for marker in safe_negative_markers)
def _bounded_semantic_evidence_surface_value_forbidden(value: Any) -> bool: if isinstance(value, Mapping): allowed_boundary_keys = { "BoundedSemanticEvidencePacket is not FinalOutput", "BoundedSemanticEvidencePacket is not ActionCommitPacket", "Evidence packet is not action permission", } allowed_false_keys = { "action_permission_claimed", "final_output_claimed", "connector_command_claimed", "action_commit_packet_claimed", "real_world_effects_allowed", } for key, item in value.items(): key_text = str(key) if key_text in allowed_boundary_keys: continue if key_text in allowed_false_keys and item is False: continue if _bounded_surface_text_has_marker(key_text): return True if ( key_text == "text" and isinstance(item, str) and _bounded_surface_text_has_marker(item) and _bounded_evidence_item_text_is_safe_negative_surface_context(value) ): continue if _bounded_semantic_evidence_surface_value_forbidden(item): return True elif isinstance(value, (list, tuple, set, frozenset)): return any( _bounded_semantic_evidence_surface_value_forbidden(item) for item in value ) elif isinstance(value, str): return _bounded_surface_text_has_marker(value) return False
def _bounded_semantic_evidence_real_world_surface_reasons( packet: Mapping[str, Any], ) -> tuple[str, ...]: if _bounded_semantic_evidence_surface_value_forbidden(packet): return ("bounded_semantic_evidence_real_world_action_surface_forbidden",) return ()
def _selected_vector_ids_from_route_context( route_context_packet: Mapping[str, Any], ) -> tuple[Any, ...]: return _as_tuple(route_context_packet.get("selected_vector_ids"))
def _route_id_matches_context( source_route_id: Any, route_context_packet: Mapping[str, Any], ) -> bool: explicit_route = ( route_context_packet.get("selected_route_id") or route_context_packet.get("route_id") or route_context_packet.get("source_route_id") ) if explicit_route: return source_route_id == explicit_route allowed_routes = set(_as_tuple(route_context_packet.get("allowed_routes"))) return bool(source_route_id) and source_route_id in allowed_routes
