dedSemanticEvidencePacket is not FinalOutput": True, "BoundedSemanticEvidencePacket is not ActionCommitPacket": True, "Evidence packet is not action permission": True, "Gemini proposes, Root disposes": True, "observed_semantic_facts": _as_evidence_item_tuple( observed_semantic_facts, default_text="Bounded semantic fact remains candidate evidence.", evidence_kind="observed_fact", ), "missing_evidence": _as_evidence_item_tuple( missing_evidence, default_text="Missing evidence remains unresolved.", evidence_kind="missing_evidence", ), "uncertainty_notes": _as_evidence_item_tuple( uncertainty_notes, default_text="Uncertainty remains visible for Architect review.", evidence_kind="uncertainty", ), "risk_boundary_notes": _as_evidence_item_tuple( risk_boundary_notes, default_text="Risk boundary remains advisory and bounded.", evidence_kind="risk_boundary", ), "rejected_action_routes": _as_evidence_item_tuple( rejected_action_routes, default_text="External action route remains rejected.", evidence_kind="rejected_route", ), "required_approvals_or_conditions": _as_evidence_item_tuple( required_approvals_or_conditions, default_text="Required condition remains pending review.", evidence_kind="approval_condition", ), "authority_boundary_notes": _as_evidence_item_tuple( authority_boundary_notes, default_text="Root remains final authority.", evidence_kind="authority_boundary", ), "selected_vector_ids": _as_tuple(selected_vector_ids) or ("vector:bounded_semantic_review",), "required_guards": _as_tuple(required_guards) or ( "ContextPacket validation", "structured rationale validation", "Root final authority", ), } ) return packet
def validate_bounded_semantic_evidence_packet( packet: Mapping[str, Any], *, route_context_packet: Mapping[str, Any] | None = None, orchestrator_proposal: Mapping[str, Any] | None = None, structured_rationale_validation: Mapping[str, Any] | None = None, ) -> dict[str, Any]: reasons: list[str] = [] packet_type = packet.get("packet_type")
