"""Finite admitted transforms and an effect executor, with no authority cache."""
from contextvars import ContextVar
import json
from hedgehog import action_commit_packet_v02 as action
from hedgehog import work_execution_host_v01 as hosts
from hedgehog.kernel import effect_firewall_v01 as firewall
from . import contracts_v01 as c

EXECUTION = ContextVar('sentinel_current_finite_execution', default=None)


def records(values):
    return tuple(action.build_action_effect_parameter_record_v01(parameter_name=n, value_type=t, value=v)
                 for n,(t,v) in sorted(values.items()))


def values(records):
    return {r.parameter_name:r.value for r in records}


def compute(operation, inputs):
    data = json.loads(values(inputs)['material'])
    if operation == 'sentinel.compile.v01' or operation == 'sentinel.diagnostic.v01':
        data = c.diagnostic(data)
    elif operation == 'sentinel.contract.v01':
        c.require(data['selection'] in c.DIAGNOSTICS and type(data['healthy']) is bool, 'diagnostic_result_required')
    elif operation == 'sentinel.information.v01':
        c.require(type(data['summary']) is str and bool(data['record_id']), 'actual_memory_summary_required')
        data = dict(record_id=data['record_id'], summary=data['summary'], informational_only=True)
    elif operation == 'sentinel.configuration.v01':
        c.validate_policy(data['contract'])
        if data.get('kind')=='CURRENT_CONFIGURATION':
            c.require(set(data)=={'kind','rainfall','contract','diagnostic_result_ref'} and bool(data['diagnostic_result_ref']),
                'current_configuration_material')
            refs=dict(diagnostic_result_ref=data['diagnostic_result_ref'])
        else:
            c.require(bool(data['recomputed_result_ref']) and bool(data['consumed_binding_ref']), 'consumed_delta_required')
            refs={k:data[k] for k in ('delta_result_ref','recomputed_result_ref','source_artifact_ref')}
        data=dict(cadence_seconds=c.cadence(data['rainfall'],data['contract']),contract=data['contract'],
            input_sha256=c.digest(data),**refs)
    elif operation == 'sentinel.observability.v01':
        data=c.observability(data)
    else:
        raise ValueError('unknown_admitted_operation')
    return records(dict(material=('TEXT',c.canonical(data).decode()), fingerprint=('REFERENCE',c.identity('work',data))))


def validate_inputs_v01(definition, inputs):
    errors = firewall.validate_capability_values_v01(definition.input_fields, inputs)
    if not errors and definition.effect_kind == 'MOCK_CONSEQUENTIAL':
        try:
            session = EXECUTION.get()
            c.require(session is not None, 'finite_execution_context_missing')
            session.validate_effect(values(inputs))
        except (ValueError, KeyError, TypeError) as exc:
            errors = (str(exc),)
    return firewall.build_capability_validation_evidence_v01(definition=definition, values=inputs,
        invocation_id=None, valid=not errors, reason_codes=errors)


def execute_compile_v01(invocation):
    return compute('sentinel.compile.v01', invocation.inputs)


def execute_contract_v01(invocation):
    return compute('sentinel.contract.v01', invocation.inputs)


def execute_diagnostic_v01(invocation):
    return compute('sentinel.diagnostic.v01', invocation.inputs)


def execute_command_v01(invocation):
    session = EXECUTION.get()
    c.require(session is not None and invocation.owning_root_id == session.root, 'executor_local_root')
    result = session.execute_effect(values(invocation.inputs), invocation.invocation_id)
    return records(dict(material=('TEXT',c.canonical(result).decode()), fingerprint=('REFERENCE',c.identity('result',result))))


def validate_outputs_v01(definition, invocation, output):
    errors = firewall.validate_capability_values_v01(definition.output_fields, output)
    if not errors:
        if definition.effect_kind == 'PURE':
            if output != compute(definition.operation_id, invocation.inputs):
                errors = ('actual_contract_output',)
        else:
            session = EXECUTION.get()
            actual = None if session is None else session.executed.get(invocation.invocation_id)
            if actual is None or values(output) != dict(material=c.canonical(actual).decode(),fingerprint=c.identity('result',actual)):
                errors = ('actual_effect_output',)
    return firewall.build_capability_validation_evidence_v01(definition=definition, values=output,
        invocation_id=invocation.invocation_id, valid=not errors, reason_codes=errors)


def admit(root, operation, executor, consequential=False, resource_refs=()):
    functions = (validate_inputs_v01, validate_outputs_v01, executor)
    sources = tuple(hosts.observe_local_capability_code_v01(f) for f in functions)
    fields = [('material','TEXT')] if not consequential else [('command','TEXT'),('session','REFERENCE'),('version','INTEGER')]
    semantics = None
    if consequential:
        semantics = firewall.build_capability_business_semantics_v01(operation_key=operation,
            selected_action_class='mock_action:sentinel_monitoring_command', logical_effect_class='LOCAL_MONITORING_COMMAND',
            logical_effect_namespace=operation, business_object_class='DOMAIN_OBJECT', business_object_namespace='sentinel.command',
            input_bindings=tuple(firewall.build_capability_business_input_binding_v01(input_name=n,
                source_kind='RECORD',source_name=n,value_type=t) for n,t in fields))
    definition = firewall.build_capability_definition_v01(operation_id=operation,version='v01',
        effect_kind='MOCK_CONSEQUENTIAL' if consequential else 'PURE',business_semantics=semantics,
        input_fields=tuple(firewall.build_capability_field_v01(name=n,value_type=t,required=True,consequential=consequential) for n,t in fields),
        output_fields=tuple(firewall.build_capability_field_v01(name=n,value_type=t,required=True,consequential=False)
            for n,t in [('material','TEXT'),('fingerprint','REFERENCE')]),resource_refs=resource_refs,
        input_validator_ref=sources[0].public_symbol,output_validator_ref=sources[1].public_symbol,executor_ref=sources[2].public_symbol,
        code_sha256s=tuple((s.public_symbol,s.source_sha256) for s in sources))
    return hosts.admit_local_capability_v01(definition=definition,input_validator=functions[0],output_validator=functions[1],
        executor=functions[2],catalogue_revision=0,host_instance_ref='host:'+root)


def execute_information_v01(invocation):
    return compute('sentinel.information.v01', invocation.inputs)


def execute_configuration_v01(invocation):
    return compute('sentinel.configuration.v01', invocation.inputs)


def execute_observability_v01(invocation):
    return compute('sentinel.observability.v01',invocation.inputs)


def catalogue(root, session):
    return (admit(root,'sentinel.compile.v01',execute_compile_v01),
            admit(root,'sentinel.contract.v01',execute_contract_v01),
            admit(root,'sentinel.command.v01',execute_command_v01,True,(session,)),
            admit(root,'sentinel.diagnostic.v01',execute_diagnostic_v01),
            admit(root,'sentinel.information.v01',execute_information_v01),
            admit(root,'sentinel.configuration.v01',execute_configuration_v01),
            admit(root,'sentinel.observability.v01',execute_observability_v01))

"""Closed fixed-point local measurements and finite diagnostic policy."""
import hashlib
import json

DOMAIN = 'LANDSLIDE_SENTINEL'
DIAGNOSTICS = ('REFERENCE_INTEGRITY', 'INDEPENDENT_RESERVE_SERIES', 'TEMPORAL_CONTEXT_APPLICABILITY',
               'SPATIAL_CONTEXT_APPLICABILITY', 'EVIDENCE_GAPS')
SERIES_POLICY = dict(minimum_samples=3,minimum_span=20,maximum_gap=15,newest_max_age=10,maximum_range_um=1000)
DIAGNOSTIC_CATALOGUE = {
    'REFERENCE_INTEGRITY': 'Compare the two current channel records: calibration identifier association, health and lineage separation. This is a current-pair metadata comparison, not a history-variation measurement or physical certification.',
    'INDEPENDENT_RESERVE_SERIES': 'Measure reserve variation over the admitted historical window after accepted plan and native read. Independence, calibration and receipt checks are compulsory source-fitness guards, not an investigation of all current-channel associations.',
    'TEMPORAL_CONTEXT_APPLICABILITY': 'Compare contextual measurement time, receipt time, known interval and current evaluation. Report temporal suitability or historical/missing evidence; transport time cannot renew a measurement.',
    'SPATIAL_CONTEXT_APPLICABILITY': 'Inspect contextual site and source identities against the intended site. Report scope match or absent spatial mapping, without inventing coordinates or causal relevance.',
    'EVIDENCE_GAPS': 'Compare supplied evidence with the declared duty-specific requirements: current-pair metadata for local/reviewer duties, or hourly rainfall context support for the environmental duty. Return specific missing, incompatible, unresolved or supported relationships; unrelated physical certification is a limitation, not an automatic prerequisite.',
}
INVESTIGATION_VERSION='sentinel.investigation.v02'


def investigation(selection,duty):
    require(selection in DIAGNOSTICS,'investigation_selection')
    environmental=duty=='CLOUD_ENVIRONMENTAL_ANALYST'
    require(duty in ('LOCAL_SLOPE_ANALYST','CLOUD_ENVIRONMENTAL_ANALYST','ADVERSARIAL_SENSOR_REVIEWER'),'investigation_duty')
    require(selection in (('TEMPORAL_CONTEXT_APPLICABILITY','SPATIAL_CONTEXT_APPLICABILITY','EVIDENCE_GAPS') if environmental
        else ('REFERENCE_INTEGRITY','INDEPENDENT_RESERVE_SERIES','EVIDENCE_GAPS')),'investigation_duty_scope')
    if selection=='INDEPENDENT_RESERVE_SERIES':
        target='RESERVE_WINDOW_VARIATION';use='BOUNDED_RESERVE_CONSISTENCY'
        required=['ACTUAL_NATIVE_RECEIPT','ADMITTED_RESERVE_HISTORY','CURRENT_PRIMARY_LINEAGE','SERIES_FITNESS']
        relationship='Measure range and span of the acquired reserve window after all source-fitness checks.'
    elif selection=='TEMPORAL_CONTEXT_APPLICABILITY':
        target='RAINFALL_MEASUREMENT_INTERVAL';use='CURRENT_HOURLY_RAINFALL_CONTEXT'
        required=['RAINFALL_RECORD','SCENARIO_SECONDS','MM_X1000','ACCUMULATION_1H','EXPLICIT_3600_SECOND_INTERVAL','CURRENT_ENDPOINT']
        relationship='Compare actual interval duration/statistic/units and endpoint age with the declared hourly context use.'
    elif selection=='SPATIAL_CONTEXT_APPLICABILITY':
        target='CONTEXT_SITE_RELATIONSHIP';use='CONTEXT_FOR_SYNTHETIC_SITE'
        required=['RAINFALL_RECORD','SOURCE_SITE_ID','TARGET_SITE_ID']
        relationship='Compare declared synthetic site identities; separately retain missing verified physical mapping.'
    elif selection=='EVIDENCE_GAPS' and environmental:
        target='HOURLY_CONTEXT_EVIDENCE_REQUIREMENTS';use='CURRENT_HOURLY_RAINFALL_CONTEXT'
        required=['RAINFALL_RECORD','SUPPORTED_INTERVAL_STATISTIC_UNITS','CURRENT_ENDPOINT','SYNTHETIC_SITE_SCOPE']
        relationship='Evaluate each supplied rainfall record against temporal and synthetic site requirements; name each unsupported relationship.'
    else:
        target='CURRENT_CHANNEL_METADATA' if selection=='REFERENCE_INTEGRITY' else 'CURRENT_PAIR_EVIDENCE_REQUIREMENTS'
        use='CURRENT_PAIR_METADATA_COMPARISON'
        required=['CURRENT_DISPLACEMENT_RECORD','CURRENT_RESERVE_RECORD','CURRENT_CALIBRATION_IDS','HEALTH','DISTINCT_LINEAGES']
        relationship='Compare actual current channel/calibration associations and distinct lineage identifiers, not reserve history variation.'
    return dict(version=INVESTIGATION_VERSION,duty=duty,target=target,intended_use=use,required_evidence=required,
        checked_relationship=relationship,source_scope='DUTY_OBSERVATIONS_WITH_COMPULSORY_COMPANIONS',
        source_refs_meaning='CITATIONS_NOT_ACQUISITION_OR_OPTIONAL_SAFETY_FILTERS',
        bounded_results=['SUPPORTED','MISSING','INCOMPATIBLE','UNRESOLVED'],
        cannot_establish=['PHYSICAL_CALIBRATION_CERTIFICATION','GEOGRAPHICAL_RELEVANCE','LANDSLIDE_PREDICTION','ACTION_PERMISSION'])


def temporal_findings(records,tick):
    """Measurement support, not transport recency, determines hourly applicability."""
    results=[]
    if not records:return [dict(source_id=None,status='MISSING',reasons=['RAINFALL_RECORD_MISSING'])]
    for value in records:
        missing=[];incompatible=[];unresolved=[]
        start=value.get('observed_start');end=value.get('observed_end');received=value.get('received')
        times=all(type(v) is int and v>=0 for v in (start,end,received,tick))
        if not times:missing.append('EXPLICIT_SCENARIO_INTERVAL_SUPPORT_MISSING')
        else:
            if not start<=end<=received<=tick:incompatible.append('TIME_ORDER_OR_FUTURE_TIME')
            if start<=end and end-start!=3600:incompatible.append('HOURLY_INTERVAL_DURATION_MISMATCH')
            if end<=tick and tick-end>60:unresolved.append('HISTORICAL_ENDPOINT_NOT_CURRENT')
        if value.get('channel')!='rainfall':incompatible.append('NOT_RAINFALL_CONTEXT')
        if value.get('unit')!='mm_x1000':incompatible.append('UNSUPPORTED_UNITS')
        if value.get('statistic')!='accumulation_1h':incompatible.append('UNSUPPORTED_STATISTIC')
        if value.get('status')!='HEALTHY' or value.get('value') is None:missing.append('MEASUREMENT_NOT_ADEQUATE')
        results.append(dict(source_id=value.get('observation_id'),status='INCOMPATIBLE' if incompatible else
            'MISSING' if missing else 'UNRESOLVED' if unresolved else 'SUPPORTED',reasons=incompatible+missing+unresolved,
            measured_interval=[start,end],received=received,endpoint_age=tick-end if type(end) is int else None,
            time_basis='SCENARIO_SECONDS',unit=value.get('unit'),statistic=value.get('statistic')))
    return results


def investigation_findings(row,contract):
    records=row['observations'];selection=row['selection'];spec=row['investigation']
    if selection=='TEMPORAL_CONTEXT_APPLICABILITY' or (selection=='EVIDENCE_GAPS' and spec['duty']=='CLOUD_ENVIRONMENTAL_ANALYST'):
        findings=temporal_findings(records,row['tick'])
        if selection=='EVIDENCE_GAPS':
            findings += [dict(source_id=v['observation_id'],relationship='SYNTHETIC_SITE_SCOPE',
                status='SUPPORTED' if v['site']==row['site'] else 'INCOMPATIBLE',reasons=[] if v['site']==row['site'] else ['SITE_ID_MISMATCH']) for v in records]
        return dict(findings=findings,measured=[v['observed_end'] for v in records],received=[v['received'] for v in records],
            scope='TEMPORAL_AND_DECLARED_SYNTHETIC_SCOPE_ONLY' if selection=='EVIDENCE_GAPS' else 'TEMPORAL_ONLY',
            physical_mapping='NOT_ESTABLISHED')
    if selection=='SPATIAL_CONTEXT_APPLICABILITY':
        findings=([dict(source_id=v['observation_id'],status='SUPPORTED' if v['site']==row['site'] else 'INCOMPATIBLE',
            relationship='SYNTHETIC_SITE_IDENTITY',reasons=[] if v['site']==row['site'] else ['SITE_ID_MISMATCH']) for v in records]
            or [dict(source_id=None,status='MISSING',reasons=['RAINFALL_RECORD_MISSING'])])
        return dict(findings=findings,sites=sorted({v['site'] for v in records}),target_site=row['site'],
            physical_mapping='NOT_ESTABLISHED',physical_applicability='UNRESOLVED_NO_VERIFIED_MAPPING')
    findings=[]
    for channel in ('displacement','reserve'):
        matches=[v for v in records if v['channel']==channel]
        if len(matches)!=1:
            findings.append(dict(channel=channel,status='MISSING',reasons=['REQUIRED_CURRENT_CHANNEL_MISSING']));continue
        value=matches[0];reasons=[]
        if value['calibration']!=contract['calibration']:reasons.append('CURRENT_CALIBRATION_MISMATCH')
        if value['status']!='HEALTHY' or value['value'] is None:reasons.append('INADEQUATE_CHANNEL')
        if not 0<=row['tick']-value['observed_end']<=contract['max_local_age_seconds']:reasons.append('CURRENT_CHANNEL_AGE')
        findings.append(dict(source_id=value['observation_id'],channel=channel,calibration=value['calibration'],
            status='INCOMPATIBLE' if reasons else 'SUPPORTED',reasons=reasons))
    if len(records)==2:
        distinct=len({v['lineage'] for v in records})==2
        findings.append(dict(relationship='CURRENT_PAIR_LINEAGE_SEPARATION',lineages=[v['lineage'] for v in records],
            status='SUPPORTED' if distinct else 'INCOMPATIBLE',reasons=[] if distinct else ['CURRENT_PAIR_LINEAGES_CORRELATED']))
    return dict(findings=findings,source_ids=[v['observation_id'] for v in records],physical_zero_check='NOT_ESTABLISHED')


def performed_investigation(result):
    """Compare executed relationships/evidence, not operation labels or prose."""
    require('investigation' in result,'current_investigation_result_required')
    detail=result['detail']
    if result['selection']=='INDEPENDENT_RESERVE_SERIES':
        return dict(work='RESERVE_WINDOW_VARIATION',source_ref=detail['source_ref'],samples=detail['sample_ids'],
            span=detail['measured_span'],range_value=detail['range_value'],fitness=detail['fitness'],reasons=detail['reasons'])
    # Reference comparison and a gaps inventory doing the same checks do not form a contrast.
    return dict(work='RECORD_RELATIONSHIP_CHECKS',findings=detail['findings'])
POLICY = dict(version='sentinel.policy.v01', calibration='calibration:sentinel:v01',
              rain_fast_mm_x1000=30000, normal_cadence_seconds=60, fast_cadence_seconds=15,
              critical_displacement_um=5000, critical_reserve_um=5000, max_local_age_seconds=10)


def require(condition, reason):
    if not condition:
        raise ValueError(reason)


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True, allow_nan=False).encode()


def digest(value):
    return hashlib.sha256(value if isinstance(value, bytes) else canonical(value)).hexdigest()


def identity(kind, value):
    return 'sentinel:'+kind+':'+digest(value)


def measurement(value):
    require(type(value) is dict and set(value)=={'sensor', 'value', 'unit', 'scenario_tick', 'healthy', 'calibration'}, 'measurement_shape')
    require(value['sensor'] in ('rainfall', 'displacement', 'reserve','channel_level','vibration'), 'measurement_sensor')
    require(type(value['value']) is int and 0 <= value['value'] <= 10000000, 'measurement_missing_or_range')
    require(value['unit']=={'rainfall':'mm_x1000','channel_level':'synthetic_level_mm','vibration':'synthetic_intensity_milli'}.get(value['sensor'],'um'), 'measurement_units')
    require(type(value['scenario_tick']) is int and value['scenario_tick'] >= 0 and type(value['healthy']) is bool, 'measurement_time_health')
    require(type(value['calibration']) is str and value['calibration'].startswith('calibration:sentinel:'), 'measurement_calibration')
    return dict(value)


def diagnostic(material):
    require(type(material) is dict and set(material) in ({'selection','frames','contract'},
        {'selection','frames','contract','semantic_bindings','checks'},
        {'selection','frames','contract','semantic_bindings','checks','phase'},
        {'selection','frames','contract','semantic_bindings','checks','phase','accepted_plan'}), 'diagnostic_material')
    if 'checks' in material:
        from .semantic_adapter_v01 import validate_material
        validate_material(material)
        if material.get('phase')=='PLAN':
            results=[dict(selection=row['selection'],semantic_ref=row['semantic_ref'],healthy=True,
                action='READ_RESERVE_SERIES' if row['selection']=='INDEPENDENT_RESERVE_SERIES' else 'NONE',
                source_ref='synthetic:reserve_series:v01' if row['selection']=='INDEPENDENT_RESERVE_SERIES' else None,
                input_sha256=digest(row),meaning='ADMITTED_PLAN_NOT_MEASUREMENT_OR_PERMISSION') for row in material['checks']]
            for result,row in zip(results,material['checks'],strict=True):
                if 'investigation' in row:result['investigation']=row['investigation']
        else:results=[diagnostic_check(row,material['contract']) for row in material['checks']]
        return dict(selection=material['selection'],healthy=all(v['healthy'] for v in results),checks=results,
            input_sha256=digest(material),semantic_refs=[v['contribution']['contribution_id'] for v in material['semantic_bindings']],
            contract=material['contract'],stage=material.get('phase','RESULT'))
    selection=material['selection']
    require(selection in DIAGNOSTICS, 'diagnostic_not_admitted')
    frames=tuple(measurement(v) for v in material['frames'])
    require({v['sensor'] for v in frames}=={'rainfall','displacement','reserve'} and len(frames)==3, 'diagnostic_independent_inputs')
    checked=(frames if selection=='REFERENCE_INTEGRITY' else
             tuple(v for v in frames if (v['sensor']=='rainfall')==(selection=='TEMPORAL_CONTEXT_APPLICABILITY')))
    validate_policy(material['contract'])
    result=all(v['healthy'] and v['calibration']==material['contract']['calibration'] for v in checked)
    if selection=='TEMPORAL_CONTEXT_APPLICABILITY':
        result=result and max(v['scenario_tick'] for v in frames)-checked[0]['scenario_tick']<=180
    return dict(selection=selection, healthy=result, checked_sensors=[v['sensor'] for v in checked],
                input_sha256=digest(material), contract=material['contract'])


def diagnostic_check(row,contract):
    from .events_v01 import validate
    records=row['observations'];[validate(v) for v in records]
    selection=row['selection'];require(selection in DIAGNOSTICS,'check_selection')
    if selection=='INDEPENDENT_RESERVE_SERIES':
        series=row['series'];require(series['classification']=='MOCK_SOURCE_READ' and bool(series['receipt_ref']),'series_actual_receipt')
        samples=series['records'];[validate(v) for v in samples]
        require(bool(samples),'series_missing_samples')
        failures=[]
        if series['source_ref']!='synthetic:reserve_series:v01':failures.append('SOURCE_NOT_ADMITTED')
        if not all(v['site']==row['site'] and v['channel']=='reserve' and v['unit']=='um' for v in samples):failures.append('SOURCE_SCOPE_OR_UNITS')
        if not all(v['calibration']==contract['calibration'] for v in samples):failures.append('CALIBRATION_INCOMPATIBLE')
        primary={v['lineage'] for v in records if v['channel']=='displacement'}
        if not primary or len({v['lineage'] for v in samples})!=1 or any(v['lineage'] in primary for v in samples):failures.append('NOT_INDEPENDENT')
        if not all(v['status']=='HEALTHY' and v['value'] is not None for v in samples):failures.append('MISSING_OR_INADEQUATE')
        if len(samples)<SERIES_POLICY['minimum_samples'] or len({v['observation_id'] for v in samples})!=len(samples):failures.append('SAMPLE_COUNT_OR_DUPLICATE')
        if any(not (left['observed_end']<right['observed_start'] and left['sequence']<right['sequence'] and
            right['observed_end']-left['observed_end']<=SERIES_POLICY['maximum_gap']) for left,right in zip(samples,samples[1:])):failures.append('ORDER_OR_GAP')
        if samples[-1]['observed_end']-samples[0]['observed_end']<SERIES_POLICY['minimum_span']:failures.append('INSUFFICIENT_WINDOW')
        if not 0<=row['tick']-samples[-1]['observed_end']<=SERIES_POLICY['newest_max_age']:failures.append('STALE_LATEST_SAMPLE')
        if any(v['received']>row['tick'] for v in samples):failures.append('FUTURE_RECEIPT')
        values=[v['value'] for v in samples if v['value'] is not None]
        spread=max(values)-min(values) if values else None
        fitness=not failures;healthy=fitness and spread<=SERIES_POLICY['maximum_range_um']
        detail=dict(sample_ids=[v['observation_id'] for v in samples],receipt_ref=series['receipt_ref'],
            source_ref=series['source_ref'],range_value=spread,fitness='ELIGIBLE' if fitness else 'INELIGIBLE',
            reasons=failures,outcome='BOUNDED_CONSISTENT' if healthy else 'UNRESOLVED_OR_INCONSISTENT',
            measured_span=samples[-1]['observed_end']-samples[0]['observed_end'],policy=SERIES_POLICY)
    elif 'investigation' in row:
        detail=investigation_findings(row,contract)
        healthy=all(v['status']=='SUPPORTED' for v in detail['findings'])
        detail['outcome']='SUPPORTED_FOR_DECLARED_USE' if healthy else 'NOT_SUPPORTED_FOR_DECLARED_USE'
    elif selection=='TEMPORAL_CONTEXT_APPLICABILITY':
        healthy=bool(records) and all(0<=row['tick']-v['observed_end']<=60 and v['received']<=row['tick'] for v in records)
        detail=dict(applicability='CURRENT_CONTEXT' if healthy else 'HISTORICAL_OR_INAPPLICABLE',
            measured=[v['observed_end'] for v in records],received=[v['received'] for v in records],
            scope='TEMPORAL_ONLY_NOT_SPATIAL_OR_LOCAL_SENSOR_AUTHORITY')
    elif selection=='SPATIAL_CONTEXT_APPLICABILITY':
        healthy=bool(records) and all(v['site']==row['site'] for v in records)
        detail=dict(applicability='MATCHING_SYNTHETIC_CONTEXT_SCOPE' if healthy else 'NO_VERIFIED_SITE_MAPPING',
            sites=sorted({v['site'] for v in records}),target_site=row['site'],physical_sensor_claim=False)
    elif selection=='EVIDENCE_GAPS':
        missing=['PHYSICAL_ZERO_CHECK_CERTIFICATION_NOT_PROVIDED']
        if not records:missing.append('MEASUREMENTS_MISSING')
        if any(v['status']!='HEALTHY' for v in records):missing.append('INADEQUATE_CHANNEL')
        healthy=False;detail=dict(outcome='NEEDS_EVIDENCE',missing=missing,source_ids=[v['observation_id'] for v in records])
    else:
        healthy=bool(records) and len({v['lineage'] for v in records})==len(records)
        healthy=healthy and all(v['status']=='HEALTHY' and v['calibration']==contract['calibration'] for v in records)
        detail=dict(independent_lineages=sorted({v['lineage'] for v in records}),source_ids=[v['observation_id'] for v in records],
            outcome='METADATA_CONSISTENT' if healthy else 'METADATA_INCONSISTENT',physical_zero_check='NOT_ESTABLISHED')
    result=dict(selection=selection,healthy=healthy,detail=detail,semantic_ref=row['semantic_ref'],input_sha256=digest(row))
    if 'investigation' in row:result['investigation']=row['investigation']
    return result


def cadence(rainfall,policy=None):
    policy=validate_policy(POLICY if policy is None else policy)
    value=measurement(rainfall)
    require(value['sensor']=='rainfall' and value['healthy'], 'rainfall_unavailable')
    require(value['calibration']==policy['calibration'],'rainfall_current_calibration')
    return policy['fast_cadence_seconds'] if value['value'] >= policy['rain_fast_mm_x1000'] else policy['normal_cadence_seconds']


def critical(frames, tick, policy=None):
    policy=validate_policy(POLICY if policy is None else policy)
    measured={v['sensor']:measurement(v) for v in frames}
    local=[measured[k] for k in ('displacement','reserve')]
    return (all(v['healthy'] and 0 <= tick-v['scenario_tick'] <= policy['max_local_age_seconds'] for v in local)
            and local[0]['value'] >= policy['critical_displacement_um']
            and local[1]['value'] >= policy['critical_reserve_um'])


def observability(material):
    from .events_v01 import validate
    require(set(material)=={'records','tick','site','policy','purpose'},'observability_shape')
    require(material['purpose'] in ('local','channel'),'observability_purpose')
    policy=material['policy'];validate_policy(policy)
    channels=('displacement','reserve') if material['purpose']=='local' else ('channel_level','vibration')
    records=material['records'];[validate(v) for v in records]
    current=[v for v in records if v['channel'] in channels and v['status']=='HEALTHY' and v['site']==material['site']
        and v['calibration']==policy['calibration'] and 0<=material['tick']-v['observed_end']<=policy['max_local_age_seconds']]
    independent=len(current)==2 and len({v['channel'] for v in current})==2 and len({v['lineage'] for v in current})==2
    coincident=independent and max(v['observed_start'] for v in current)<=min(v['observed_end'] for v in current)
    limits=(policy['critical_displacement_um'],policy['critical_reserve_um']) if material['purpose']=='local' else (500,700)
    floor=coincident and all(next(v['value'] for v in current if v['channel']==ch)>=lim for ch,lim in zip(channels,limits))
    return dict(observability='ADEQUATE' if coincident else 'LIMITED' if current else 'INSUFFICIENT',hard_critical=bool(floor),
        source_ids=[v['observation_id'] for v in current],input_sha256=digest(material),policy=policy,purpose=material['purpose'])


def validate_policy(policy):
    require(type(policy) is dict and set(policy)==set(POLICY),'policy_closed_shape')
    require(type(policy['version']) is str and policy['version'].startswith('sentinel.policy.'),'policy_revision')
    require(type(policy['calibration']) is str and policy['calibration'].startswith('calibration:sentinel:'),'policy_calibration')
    require(all(type(policy[k]) is int and policy[k]>0 for k in POLICY if k not in ('version','calibration')),'policy_integer')
    require((policy['normal_cadence_seconds'],policy['fast_cadence_seconds'])==(60,15),'unsupported_cadence_policy')
    return policy

"""Explicit evidence projection; no serialization of runtime Host authority.""" from dataclasses import fields, is_dataclass import json import os from pathlib import Path import time from . import contracts_v01 as c
def plain(value): if value is None or type(value) in (str,int,float,bool):return value if type(value) in (list,tuple):return [plain(v) for v in value] if type(value) is dict:return {k:plain(v) for k,v in value.items()} c.require(is_dataclass(value) and 'SourceContext' not in type(value).__name__ and 'Capture' not in type(value).__name__ and 'ExecutionBundle' not in type(value).__name__, 'runtime_authority_not_serializable') return {f.name:plain(getattr(value,f.name)) for f in fields(value)}
def save(path, value): path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(c.canonical(plain(value))+b'\n')
def phase(directory, name, **values): row=dict(phase=name,monotonic=time.monotonic(),wall_epoch=time.time(),**values) for path in (Path(directory)/'phases.jsonl',Path(os.environ.get('LS0_PHASE_LOG',str(Path(directory)/'command_phases.jsonl')))): path.parent.mkdir(parents=True,exist_ok=True) with path.open('a') as stream:stream.write(json.dumps(row,sort_keys=True)+'\n') print(json.dumps(row,sort_keys=True),flush=True) return row
def _package_context(rows, causal_rows, source_head, slice_id='ls0'): """General package construction; relationship validation is a separate public consumer.""" from hedgehog.kernel import abi_v01 as abi, integrity_replay_v01 as integrity from hedgehog.evidence import sealed_evidence_profile_v01 as profile, sealed_package_v01 as package, external_anchor_v01 as anchor artifacts=tuple(abi.build_kernel_artifact_v01(**dict(v,trace_refs=tuple(v['trace_refs']),parent_refs=tuple(v['parent_refs']))) for v in rows) c.require(not abi.validate_kernel_artifact_bundle_v01(artifacts=artifacts),'safe_artifact_bundle') causal=tuple(abi.build_causal_consumption_ref_v01(**dict(v,trace_refs=tuple(v['trace_refs']))) for v in causal_rows) refs=tuple(abi.kernel_artifact_to_canonical_ref_v01(v) for v in artifacts) manifest=integrity.build_artifact_manifest_v01(transaction_id=artifacts[0].transaction_id,profile=integrity.build_default_seal_profile_v01(), artifacts=refs,dependency_edges=tuple(integrity.ArtifactDependencyEdgeV01(v.artifact_id,p) for v in artifacts for p in v.parent_refs), root_ownership_bindings=tuple(integrity.RootOwnershipBindingV01(v.artifact_id,v.owner_root_id) for v in artifacts), evidence_class_bindings=tuple(integrity.EvidenceClassBindingV01(v.artifact_id,'EVIDENCE_ONLY') for v in artifacts), authority_class_bindings=tuple(integrity.AuthorityClassBindingV01(v.artifact_id,v.authority_class) for v in artifacts)) payloads=tuple((v['artifact_id'],v['payload']) for v in rows) verified=integrity.verify_artifact_replay_v01(manifest=manifest,payload_rows=payloads,expected_manifest_hash=manifest.manifest_hash) c.require(verified.replay_status=='PASS','safe_kernel_replay') document=dict(artifacts=rows,causal_refs=causal_rows,execution_head=source_head, kernel_manifest=integrity.artifact_manifest_to_plain_dict_v01(manifest), kernel_replay=integrity.replay_verification_result_to_plain_dict_v01(verified)) if slice_id!='ls0':document['slice_id']=slice_id data=c.canonical(document)+b'\n' programme=profile.build_programme_evidence_identity_v01(programme_id='radiolaria_landslide_sentinel',programme_version=slice_id+'.v01') execution=profile.build_domain_execution_identity_v01(programme_identity=programme,domain_id='landslide_sentinel', execution_head=source_head,source_task_id=slice_id+'_integration',run_id=slice_id+':'+c.digest(document),report_id=c.digest(rows)) attempt=profile.build_live_attempt_identity_v01(programme_identity=programme,domain_execution_identity=execution, attempt_number=1,package_id='sentinel:'+c.digest(document),logical_package_ref='packages/landslide_sentinel/'+slice_id, output_directory_ref='safe_package',provider_mode='deterministic_fixture',model_id='local-safe-export',expected_actor_count=1,provider_call_budget=0) source=profile.build_safe_source_record_v01(source_id='sentinel:source:projection',source_type='PUBLIC_SAFE_DERIVATIVE', evidence_class='EXECUTED_DETERMINISTIC_RUNTIME',canonical_projection=document,media_type='application/json',trace_refs=(manifest.manifest_hash,), contains_raw_prompt=False,contains_raw_provider_response=False,secret_scan_passed=True, observed_provider_call_count=0,observed_network_call_count=0,observed_gemini_call_count=0,real_world_effects_count=0) integrity_source=profile.build_safe_source_record_v01(source_id='sentinel:source:integrity',source_type='PUBLIC_KERNEL_REPLAY', evidence_class='CRYPTOGRAPHIC_INTEGRITY',canonical_projection=document['kernel_replay'],media_type='application/json', trace_refs=(manifest.manifest_hash,),contains_raw_prompt=False,contains_raw_provider_response=False,secret_scan_passed=True, observed_provider_call_count=0,observed_network_call_count=0,observed_gemini_call_count=0,real_world_effects_count=0) records=tuple(profile.build_evidence_artifact_record_v01(artifact_id=v.artifact_id,artifact_type=v.artifact_type, evidence_class='EXECUTED_DETERMINISTIC_RUNTIME',source_record_ids=(source.source_record_id,), canonical_projection=abi.kernel_artifact_to_plain_dict_v01(v),authority_class='EVIDENCE_ONLY',owner_root_id=v.owner_root_id, trace_refs=v.trace_refs,created_authority_count=0,created_permission_count=0,real_world_effects_count=0) for v in artifacts) projection=profile.build_domain_evidence_projection_v01(programme_identity=programme,domain_execution_identity=execution, attempt_identity=attempt,source_records=(source,integrity_source),artifact_records=records,kernel_artifact_refs=refs,causal_consumption_refs=causal, evidence_refs=(manifest.manifest_hash,c.digest(rows)),limitation_refs=('SAFE_DERIVED_NOT_NATIVE_REPLAY','TEST_SUPPLIED_PIN_PENDING_REVIEW', 'EXPORT_AND_REPLAY_COUNTS_ARE_NOT_HISTORICAL_LIVE_COUNTS','STRUCTURAL_LINKS_NOT_SENSOR_TRUTH')) file_record=package.build_safe_file_record_v01(logical_path='projection.json',media_type='application/json',content_bytes=data, evidence_class=source.evidence_class,source_record_ids=(source.source_record_id,integrity_source.source_record_id),terminal_newline_required=True,secret_scan_passed=True) sealed=package.build_sealed_package_manifest_v01(domain_projection=projection,safe_file_records=(file_record,),safe_file_contents=(data,),kernel_manifest_hash=manifest.manifest_hash) context=dict(manifest=sealed,domain_projection=projection,safe_file_contents=(data,)) publication=anchor.build_external_anchor_publication_v01(**context,publication_base_head=source_head) return context,publication,document,artifacts,causal
def write_package(directory, rows, causal_rows, source_head, slice_id='ls0'): """Write a new evidence-only package; never grant present execution authority.""" from hedgehog.kernel import abi_v01 as abi context,publication,document,artifacts,causal=_package_context(rows,causal_rows,source_head,slice_id) c.require(not abi.validate_causal_consumption_bundle_v01(artifacts=artifacts,causal_refs=causal),'safe_causal_relationship') return _persist_package(directory,context,publication,document)
def _persist_package(directory,context,publication,document): from hedgehog.evidence import sealed_package_v01 as package,external_anchor_v01 as anchor target=Path(directory);c.require(not target.exists(),'package_destination_exists');target.mkdir(parents=True) save(target/'projection.json',document) save(target/'manifest.json',package.sealed_package_manifest_to_plain_dict_v01(context['manifest'], domain_projection=context['domain_projection'],safe_file_contents=context['safe_file_contents'])) save(target/'publication.json',anchor.external_anchor_publication_to_plain_dict_v01(publication,**context)) return dict(publication_id=publication.anchor_publication_id,pin_provenance='TEST_SUPPLIED_PIN',review='PENDING_REVIEW', authority='EVIDENCE_ONLY',directory=str(target))
def verify_package(directory, expected_pin): """Disk-only reconstruction and public pin, replay, and causal validation.""" from hedgehog.kernel import abi_v01 as abi from hedgehog.evidence import sealed_package_v01 as package,external_anchor_v01 as anchor,sealed_replay_evidence_v01 as replay target=Path(directory) c.require(target.is_dir() and not target.is_symlink(),'package_directory') c.require({p.name for p in target.iterdir()}=={'projection.json','manifest.json','publication.json'},'package_exact_coverage') def reopen(): c.require(all(not p.is_symlink() and p.is_file() for p in target.iterdir()),'package_regular_files') raw=(target/'projection.json').read_bytes();data=json.loads(raw) c.require(raw==c.canonical(data)+b'\n','package_canonical_bytes') context,publication,doc,artifacts,causal=_package_context(data['artifacts'],data['causal_refs'],data['execution_head'],data.get('slice_id','ls0')) c.require(data==doc,'package_kernel_material') manifest=package.sealed_package_manifest_to_plain_dict_v01(context['manifest'],domain_projection=context['domain_projection'],safe_file_contents=context['safe_file_contents']) c.require((target/'manifest.json').read_bytes()==c.canonical(manifest)+b'\n','package_covered_bytes_changed') pub=anchor.external_anchor_publication_to_plain_dict_v01(publication,**context) c.require((target/'publication.json').read_bytes()==c.canonical(pub)+b'\n','package_publication_changed') return context,publication,artifacts,causal context,publication,artifacts,causal=reopen() verified=anchor.build_anchored_package_verification_v01(anchor_publication=publication,**context,supplied_anchor_publication_id=expected_pin) c.require(verified.verification_status=='ANCHORED_PASS','external_anchor_mismatch') relationship=abi.validate_causal_consumption_bundle_v01(artifacts=artifacts,causal_refs=causal) c.require(not relationship,'public_causal_relationship:'+repr(relationship)) rebuilt,_,_,_=reopen() args=dict(source_manifest=context['manifest'],source_domain_projection=context['domain_projection'],source_safe_file_contents=context['safe_file_contents'], anchor_publication=publication,anchored_verification=verified,supplied_anchor_publication_id=expected_pin, reconstructed_manifest=rebuilt['manifest'],reconstructed_domain_projection=rebuilt['domain_projection'],reconstructed_safe_file_contents=rebuilt['safe_file_contents']) result=replay.build_sealed_replay_evidence_v01(**args,evidence_refs=('sentinel:disk_reopen',expected_pin)) c.require(result.replay_status=='PASS' and not replay.validate_sealed_replay_evidence_v01(result,**args),'public_sealed_replay') return dict(status='PASS',pin_provenance='TEST_SUPPLIED_PIN',review='PENDING_REVIEW', anchor=anchor.anchored_package_verification_to_plain_dict_v01(verified,anchor_publication=publication,**context,supplied_anchor_publication_id=expected_pin), replay=replay.sealed_replay_evidence_to_plain_dict_v01(result,**args),causal_errors=relationship, scope='SAFE_DERIVED_ONLY',provider_calls=0,sensor_calls=0,configuration_calls=0,signal_calls=0,report_effect_calls=0)
def export_run(session, source_head): return export_recorded_run(session.directory,source_head)
def export_recorded_run(directory, source_head): """Derive portable evidence from completed records, never restore a Host.""" from hedgehog.kernel import abi_v01 as abi directory=Path(directory) names=('semantic_work.json','new_configuration.json','critical_pending.json','phases.jsonl') c.require(all((directory/name).is_file() and not (directory/name).is_symlink() for name in names),'recorded_inputs_regular') sources={name:(directory/name).read_bytes() for name in names} semantic=json.loads(sources['semantic_work.json']);configuration=json.loads(sources['new_configuration.json']) critical=json.loads(sources['critical_pending.json']);events=[json.loads(v) for v in sources['phases.jsonl'].splitlines()] output=json.loads(configuration['effect']['output']['material']) intakes=[v for v in events if v['phase']=='ACTUAL_LOCAL_INTAKE'] c.require(intakes and intakes[-1]['cadence_seconds']==output['cadence_seconds'],'recorded_intake_relationship') c.require(configuration['consumed']['recomputed_result_ref'] and critical['final_signal'] and critical['worker_joined'],'recorded_completion_required') documents=[dict(kind='diagnostic',native_work_ref=semantic['work_artifact']['artifact_id'], selection=semantic['semantic']['response']['diagnostic'],actual_mode=semantic['semantic']['actual_mode'], source_documents={name:c.digest(data) for name,data in sources.items()}), dict(kind='current_configuration',native_effects=[configuration['effect']['receipt']['artifact_id'],critical['effect']['receipt']['artifact_id']], cadence=output['cadence_seconds'],consumed_delta=configuration['consumed'],intakes=intakes)] rows=[] for document in documents: obj=abi.build_kernel_artifact_v01(abi_version='v1.0',artifact_id=c.identity('safe_projection',document),artifact_type='SemanticEvidence', schema_version='v1',transaction_id='sentinel:safe_export',owner_root_id='sentinel:evidence_custodian', source_component='sentinel_safe_export',authority_class='EVIDENCE_ONLY',lifecycle_state='VALIDATED',payload=dict(safe_document=document), trace_refs=(c.digest(document),),parent_refs=tuple(v['artifact_id'] for v in rows[-1:]), time_envelope=dict(pt_created_at='2026-09-14T00:00:00Z',kt_asof='2026-09-14T00:00:00Z',et_observed_at=None, ct_session_anchor='sentinel:historical_export',ttl_seconds=0,freshness_class='static',valid_from=None,valid_to=None)) rows.append(abi.kernel_artifact_to_plain_dict_v01(obj)) causal=abi.build_causal_consumption_ref_v01(producer_actor_id='sentinel_safe_export',source_artifact_id=rows[0]['artifact_id'], output_field='/safe_document',consumer_component='sentinel_safe_export',downstream_artifact_id=rows[1]['artifact_id'], decision_effect='Evidence projection relationship only',disposition='USED',reason_code='used:sentinel_safe_derivation',trace_refs=(semantic['work_artifact']['artifact_id'],)) return write_package(directory/'safe_package',rows,[plain(causal)],source_head)
class BoundaryObserver: """Passive code-object counters, not OS-wide transport or sensor monitoring.""" def __init__(self): self.counts={};self.codes={};self.tool=3
def __enter__(self): import sys from .monitoring_runtime_v01 import Sentinel,ControlledEpisode,SentinelMemory from .events_v01 import CapabilityState from .semantic_adapter_v01 import GeminiHarness from .outbox_v01 import Outbox,Receiver from hedgehog import local_drs_resolver as resolver,work_execution_host_v01 as host from hedgehog import drs_memory_resolution_v01 as memory from hedgehog.kernel import continuous_delta_runtime_v01 as delta,fractal_runtime_v02 as fractal from google.genai.models import Models,AsyncModels functions=dict(harness_attempt=GeminiHarness.respond,harness_transport=Models.generate_content, harness_async_transport=AsyncModels.generate_content,site_request=CapabilityState.request, sensor_attempt=Sentinel.intake,local_work=Sentinel.pure_consumer,drs_search=resolver.resolve_semantic_candidates, drs_write=resolver.write_semantic_record,drs_descent=memory.execute_local_memory_descent_v01, mock_effect=ControlledEpisode.execute_effect,series_read=ControlledEpisode.read_reserve_series,native_dispatch=host.dispatch_current_action_v01, outbox_queue=Outbox.queue,outbox_deliver=Outbox.deliver,receiver_receive=Receiver.receive, public_D=fractal.run_fractal_runtime_v02,public_E=delta.run_continuous_delta_runtime_v01) self.codes={fn.__code__:name for name,fn in functions.items()} self.counts={name:0 for name in functions} self.counts.update(sensor_completed=0,site_completed=0,harness_completed=0,configuration_effect=0,signal_effect=0,report_effect=0,series_effect=0) sys.monitoring.use_tool_id(self.tool,'sentinel-boundaries') def enter(code,offset): name=self.codes[code];self.counts[name]+=1 if name=='mock_effect': frame=sys._getframe(1);inputs=frame.f_locals['inputs'];op=json.loads(inputs['command'])['op'] key=('series_effect' if op=='READ_RESERVE_SERIES' else 'configuration_effect' if op=='APPLY_MONITORING_CONFIG' else ('signal_effect' if op=='SET_LOCAL_SIGNAL_STATE' else 'report_effect')) self.counts[key]+=1 def returned(code,offset,value): if self.codes[code]=='sensor_attempt' and value is not None:self.counts['sensor_completed']+=1 if self.codes[code]=='site_request':self.counts['site_completed']+=1 if self.codes[code]=='harness_attempt':self.counts['harness_completed']+=1 for event,fn in ((sys.monitoring.events.PY_START,enter),(sys.monitoring.events.PY_RETURN,returned)): sys.monitoring.register_callback(self.tool,event,fn) for code in self.codes:sys.monitoring.set_local_events(self.tool,code,sys.monitoring.events.PY_START|sys.monitoring.events.PY_RETURN) return self
def snapshot(self):return dict(self.counts,site_rejected=self.counts['site_request']-self.counts['site_completed'], harness_rejected=self.counts['harness_attempt']-self.counts['harness_completed'])
def delta(self,before):return {k:v-before[k] for k,v in self.snapshot().items()}
def __exit__(self,*args): import sys for code in self.codes:sys.monitoring.set_local_events(self.tool,code,0) sys.monitoring.free_tool_id(self.tool)
def export_story(directory,source_head): from datetime import datetime,timezone from hedgehog.kernel import abi_v01 as abi directory=Path(directory);story=json.loads((directory/'story.json').read_bytes()) sources={p.name:c.digest(p.read_bytes()) for p in directory.glob('*.json') if p.is_file()} documents=[dict(kind='LS1_SOURCE_BOUND_CONTROLLED_STORY',source_documents=sources,root=story['root'],modes=story['modes']), dict(kind='LS1_EFFECT_AND_CLEARANCE_DERIVATIVE',story=story)] rows=[];created=datetime.now(timezone.utc).isoformat() for document in documents: obj=abi.build_kernel_artifact_v01(abi_version='v1.0',artifact_id=c.identity('ls1_safe_projection',document),artifact_type='SemanticEvidence', schema_version='v1',transaction_id='sentinel:ls1_safe_export',owner_root_id='sentinel:evidence_custodian', source_component='sentinel_safe_export',authority_class='EVIDENCE_ONLY',lifecycle_state='VALIDATED',payload=dict(safe_document=document), trace_refs=(c.digest(document),),parent_refs=tuple(v['artifact_id'] for v in rows[-1:]), time_envelope=dict(pt_created_at=created,kt_asof=created,et_observed_at=None,ct_session_anchor='sentinel:ls1_export', ttl_seconds=0,freshness_class='static',valid_from=None,valid_to=None)) rows.append(abi.kernel_artifact_to_plain_dict_v01(obj)) ref=abi.build_causal_consumption_ref_v01(producer_actor_id='sentinel_safe_export',source_artifact_id=rows[0]['artifact_id'], output_field='/safe_document',consumer_component='sentinel_safe_export',downstream_artifact_id=rows[1]['artifact_id'], decision_effect='Safe evidence derivative only',disposition='USED',reason_code='used:ls1_story_sources',trace_refs=(story['root'],)) return write_package(directory/'safe_package',rows,[plain(ref)],source_head,'ls1')

"""Finite demo policy, not scientifically validated landslide prediction."""
from . import contracts_v01 as c

POLICY = dict(critical_um=5000,recovery_um=1000,recovery_duration=30,recovery_samples=3,
              required_channels=['displacement','reserve'],maximum_gap=15)


def local_pair(book,purpose,contract=None):
    contract=c.POLICY if contract is None else c.validate_policy(contract)
    rows=[book.current(ch,purpose,max_local_age_seconds=contract['max_local_age_seconds'])
        for ch in POLICY['required_channels']]
    c.require(len({v['lineage'] for v in rows})==2,'independent_witnesses_required')
    c.require(max(v['observed_start'] for v in rows)<=min(v['observed_end'] for v in rows),'coincident_witnesses_required')
    return rows


def features(book,purpose='critical',contract=None):
    contract=c.POLICY if contract is None else c.validate_policy(contract)
    rows=local_pair(book,purpose,contract)
    c.require(all(v['calibration']==contract['calibration'] for v in rows),'current_calibration_required')
    limits=(contract['critical_displacement_um'],contract['critical_reserve_um'])
    return dict(observability='ADEQUATE',source_ids=[v['observation_id'] for v in rows],
        hard_critical=all(v['value']>=limit for v,limit in zip(rows,limits)),
        ratios_micros=[v['value']*1000000//limit for v,limit in zip(rows,limits)],
        recovery_point=all(v['value']<=POLICY['recovery_um'] for v in rows))


class Incident:
    def __init__(self):
        self.incident_id=None;self.state='QUIET';self.witnesses=[];self.seen=set();self.transitions=[]
        self.recovery_dependencies=None;self.revoked_coverage=[]

    def evaluate(self,book,contract=None):
        contract=c.POLICY if contract is None else c.validate_policy(contract)
        try: value=features(book,contract=contract)
        except ValueError as error:
            self.witnesses=[]
            return dict(observability='INADEQUATE',reason=str(error),clearance=False,new_incident=False)
        rows=local_pair(book,'recovery',contract)
        dependencies=dict(channels=[dict(site=v['site'],channel=v['channel'],lineage=v['lineage'],
            calibration=v['calibration'],unit=v['unit'],statistic=v['statistic']) for v in rows],
            recovery_policy=POLICY,contract={k:contract[k] for k in
                ('calibration','critical_displacement_um','critical_reserve_um','max_local_age_seconds')})
        frozen=c.canonical(dependencies)
        if self.recovery_dependencies!=frozen:
            if self.witnesses:
                self.revoked_coverage.append(dict(tick=book.tick,reason='recovery_dependencies_changed',
                    previous_dependencies=self.recovery_dependencies.decode(),witnesses=list(self.witnesses)))
            self.witnesses=[];self.recovery_dependencies=frozen
        if value['hard_critical']:
            self.witnesses=[]
            new=self.incident_id is None
            if new:
                self.incident_id=c.identity('incident',value);self.state='ACTIVE'
                self.transitions.append(dict(state=self.state,tick=book.tick,source_ids=value['source_ids']))
            return dict(value,new_incident=new,clearance=False)
        if self.state!='ACTIVE': return dict(value,new_incident=False,clearance=False)
        ids=tuple(value['source_ids'])
        if not value['recovery_point']:
            self.witnesses=[]
        elif not any(ref in self.seen for ref in ids):
            measured={v['channel']:[v['observed_start'],v['observed_end']] for v in rows}
            previous=self.witnesses[-1]['measured'] if self.witnesses else None
            advancing=previous is None or all(measured[ch][0]>previous[ch][1] for ch in measured)
            if advancing:
                if previous and any(measured[ch][1]-previous[ch][1]>POLICY['maximum_gap'] for ch in measured):self.witnesses=[]
                self.seen.update(ids);self.witnesses.append(dict(tick=book.tick,source_ids=list(ids),measured=measured,
                    received={v['channel']:v['received'] for v in rows}))
        spans=({ch:self.witnesses[-1]['measured'][ch][1]-self.witnesses[0]['measured'][ch][1]
                for ch in POLICY['required_channels']} if self.witnesses else {})
        clearance=(len(self.witnesses)>=POLICY['recovery_samples'] and
                   min(spans.values())>=POLICY['recovery_duration'])
        return dict(value,new_incident=False,clearance=clearance,witnesses=list(self.witnesses),measured_spans=spans)

    def close(self,tick,receipt):
        c.require(self.state=='ACTIVE' and bool(receipt),'incident_close_receipt')
        self.state='CLOSED';self.transitions.append(dict(state='CLOSED',tick=tick,receipt=receipt))

"""Finite coordinator: deterministic work, one local Root/Host, mock targets.""" from dataclasses import replace import json from pathlib import Path import secrets import threading import time from hedgehog import action_commit_packet_v02 as a, work_execution_host_v01 as hosts from hedgehog.kernel import work_composition_v01 as w, abi_v01 as abi from . import contracts_v01 as c, capability_registry_v01 as caps, kernel_adapter_v01 as k from . import semantic_adapter_v01 as semantics from .evidence_v01 import phase, plain, save
class Sentinel: def __init__(self, directory, fixture, *, harness=None): self.directory=Path(directory);self.directory.mkdir(parents=True,exist_ok=False) (self.directory/'logs').mkdir() self.id='sentinel:'+''.join(secrets.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(12)) self.root='SiteSafetyRoot:'+self.id self.fixture=json.loads(c.canonical(fixture));self.frames=[c.measurement(v) for v in fixture['frames']] self.source=k.CurrentSource();self.expires=self.source.epoch+7200;self.version=0 self.contract=dict(c.POLICY);self.executed={};self.timings=[];self.history=[] self.signal=False;self.cadence_seconds=c.POLICY['normal_cadence_seconds'];self.tick=0;self.next_intake=0;self.intakes=[] self.source_hashes=c.digest(fixture);self.resource_plan={'configuration':self.id,'signal':self.id} self.catalogue=caps.catalogue(self.root,self.id) self.host=hosts.build_root_work_execution_host_v01(owning_root_id=self.root,registry=a.build_empty_action_commit_packet_registry_v02(), catalogue=self.catalogue,packet_bindings=(),current_dependency_observations=(),logical_time_bridge=self.source.snapshot.logical_time_bridge, trusted_source=self.source) self.request='Inspect local slope measurements and propose a finite diagnostic.' material,semantic=semantics.collect(self.frames,fixture['reference_note'],self.root,self.source.sample().evaluation_time,harness=harness) self.semantic_responses=[material];self.semantic_evidence=semantic source,_=k.semantic_source(self.request,self.id,self.root,self.source.sample().evaluation_time,material) self.program,self.results,self.work_artifact=k.materialize(self,material,source) output=json.loads(caps.values(self.results[-1].result.output)['material']) self.diagnostic_review=k.root_review(self.root,'transaction:'+self.id,c.identity('diagnostic_review',output),self.id, dict(actual_work_completed=all(v.status=='COMPLETED' for v in self.results),healthy=output['healthy'], selected_actual=output['selection']==material['selection']),self.work_artifact.artifact_id, self.program.candidate.bsep_ref,self.program.topology_artifact.artifact_id,self.source.sample().evaluation_time,claim_value=output) save(self.directory/'semantic_work.json',dict(semantic=semantic,program=self.program.candidate,results=self.results, work_artifact=abi.kernel_artifact_to_plain_dict_v01(self.work_artifact),consumed_review=self.diagnostic_review[2])) self.journal('SENTINEL_READY',root=self.root,profile=semantic['profile'],effects=len(self.executed))
def journal(self,name,**values):return phase(self.directory,name,**values)
def rain_dependency(self): return dict(rainfall=next(dict(v) for v in self.frames if v['sensor']=='rainfall'))
def stable_sources(self): return dict(local=[dict(v) for v in self.frames if v['sensor']!='rainfall'],site=self.fixture['site'],policy=self.contract, health=dict(collector='HEALTHY',configuration_target='MOCK_AVAILABLE'))
def authorization_fact(self, value): return dict(command=value,rainfall=self.rain_dependency(),stable_sources=self.stable_sources())
def validate_effect(self, inputs): c.require(inputs['session']==self.id and inputs['version']==self.version, 'current_local_invocation') command=json.loads(inputs['command']);op=command.get('op') c.require(self.source.snapshot.evaluation_time < self.expires, 'monitoring_expired') if op=='APPLY_MONITORING_CONFIG': c.require(set(command)=={'op','cadence_seconds','basis_ref'} and command['cadence_seconds'] in (15,60) and bool(command['basis_ref']), 'configuration_closed_inputs') elif op=='SET_LOCAL_SIGNAL_STATE': c.require(set(command)=={'op','state','basis_ref'} and command['state'] in ('ON','OFF') and bool(command['basis_ref']), 'signal_closed_inputs') else:raise ValueError('operation_not_admitted')
def execute_effect(self, inputs, invocation_id): # This target only applies bounded inputs; Root/currentness remain outside it. command=json.loads(inputs['command']) if command['op']=='APPLY_MONITORING_CONFIG': self.cadence_seconds=command['cadence_seconds'];self.next_intake=self.tick+self.cadence_seconds else:self.signal=command['state']=='ON' result=dict(op=command['op'],cadence_seconds=self.cadence_seconds,next_intake=self.next_intake,signal=self.signal, invocation_id=invocation_id,adapter_kind='DETERMINISTIC_MOCK') self.executed[invocation_id]=result return result
def intake(self,tick): c.require(type(tick) is int and tick>=self.tick,'scenario_clock_rollback') self.tick=tick if tick<self.next_intake:return None c.require(all(v['scenario_tick']<=tick for v in self.frames),'future_reading_at_intake') sample=dict(scenario_tick=tick,frames=json.loads(c.canonical(self.frames)),cadence_seconds=self.cadence_seconds, current_wall=self.source.sample().evaluation_time) self.intakes.append(sample);self.next_intake=tick+self.cadence_seconds self.journal('ACTUAL_LOCAL_INTAKE',scenario_tick=tick,cadence_seconds=self.cadence_seconds) return sample
def prepare_config(self, *, reviewed=False): current,_=semantics.collect(self.frames,self.fixture['reference_note'],self.root, self.source.sample().evaluation_time,policy=self.contract) if reviewed: material=dict(current,stable_sources=json.loads(c.canonical(self.stable_sources()))) self.monitor_review=k.assemble(self,material) ref=self.monitor_review['results'][0].result.result_id if reviewed else self.results[-1].result.result_id material=dict(kind='CURRENT_CONFIGURATION',rainfall=self.rain_dependency()['rainfall'],contract=dict(self.contract),diagnostic_result_ref=ref) work=self.pure_consumer('sentinel.configuration.v01',material) output=json.loads(caps.values(work[1][0].result.output)['material']) c.require(output['input_sha256']==c.digest(material) and output['contract']==self.contract,'configuration_current_work') self.configuration_work=work basis=k.review_work(self,work,material) save(self.directory/'configuration_work.json',dict(material=material,program=work[0].candidate,results=work[1],output=output, artifact=abi.kernel_artifact_to_plain_dict_v01(work[2]))) value=dict(op='APPLY_MONITORING_CONFIG',cadence_seconds=output['cadence_seconds'],basis_ref=work[2].artifact_id) authorization,inputs,observation,review=k.prepare_command(self,value,dict(actual_diagnostic=self.results[-1].status=='COMPLETED', actual_current_rainfall=c.measurement(self.rain_dependency()['rainfall'])['healthy']),accepted_work=basis) clock=self.source.sample(observation) packet,_=hosts.install_current_action_v01(self.host,**authorization,inputs=inputs,admission_id=self.catalogue[2].admission_id, expected_revision=self.host.revision,**clock_args(clock)) self.monitor_pending=dict(authorization=authorization,inputs=inputs,observation=observation,review=review,packet_id=packet, fact=self.last_prepared_fact,registry=self.host.registry) self.initial_capture=hosts.capture_current_action_source_v01(self.host,packet_id=packet,expected_revision=self.host.revision,**clock_args(self.source.sample())) if reviewed:self.monitor_baseline=k.prepare_delta_baseline(self) save(self.directory/'pending.json',dict(packet_id=packet,inputs=inputs,review=review[2],observation=observation, expires=authorization['root_bound'].canonical_projection.temporal_authority.expires_at_utc,current=self.initial_capture.evaluation_time, effects=len(self.executed),capture_ordinal=self.initial_capture.capture_ordinal,source_revision=self.initial_capture.source_revision)) return packet
def dispatch_pending(self): clock=self.source.sample();token=caps.EXECUTION.set(self) try: registry,_=hosts.dispatch_current_action_v01(self.host,packet_id=self.monitor_pending['packet_id'],task_id=self.id, expected_revision=self.host.revision,**clock_args(clock)) finally:caps.EXECUTION.reset(token) receipt=registry.action_packet_fulfillment_attempt_contexts[-1].receipt c.require(receipt is not None,'actual_native_receipt') save(self.directory/'pending_receipt.json',abi.kernel_artifact_to_plain_dict_v01(receipt)) return receipt
