def critical_while_pending(self): old=c.canonical(dict(frames=self.frames,context='optional_site_cloud_context',root=self.root)) started=threading.Event();release=threading.Event();returned=[] worker=threading.Thread(target=pending_stub,args=(old,self.directory,started,release,returned),name='sentinel-optional-provider-stub') worker.start();c.require(started.wait(5),'pending_stub_start') try: self.frames=[dict(self.fixture['critical_local'][0]),dict(self.fixture['critical_local'][1]),self.rain_dependency()['rainfall']] self.tick=90;observation=self.journal('INDEPENDENT_CRITICAL_OBSERVATION',frames=self.frames) hard=c.critical(self.frames,self.tick,self.contract);c.require(hard,'hard_critical_evidence_missing') ref=c.identity('hard_critical',dict(frames=self.frames,tick=self.tick)) token=caps.EXECUTION.set(self) try:effect=k.dispatch(self,dict(op='SET_LOCAL_SIGNAL_STATE',state='ON',basis_ref=ref),dict(independent_local_hard_floor=hard,optional_response_pending=not returned)) finally:caps.EXECUTION.reset(token) completed=self.journal('CRITICAL_EFFECT_COMPLETED',signal=self.signal,packet_id=effect['packet_id']) c.require(self.signal and not returned,'signal_before_optional_response') count=len(self.executed) try:hosts.dispatch_current_action_v01(self.host,packet_id=effect['packet_id'],task_id=self.id, expected_revision=self.host.revision,**clock_args(self.source.sample())) except ValueError as error:duplicate=str(error) else:raise ValueError('duplicate_signal_executed') c.require(len(self.executed)==count,'duplicate_no_effect') finally: release.set();worker.join(10) c.require(not worker.is_alive(),'owned_stub_not_reaped') c.require(returned and completed['monotonic']<returned[0]['monotonic'],'critical_event_order') save(self.directory/'critical_pending.json',dict(old_context_sha256=c.digest(old),observation=observation, effect=effect,completed=completed,late_response=returned[0],duplicate_refusal=duplicate,final_signal=self.signal, implicit_off=False,worker_joined=True