MEMORY_POLICY='sentinel.semantic_recipe.v01' DOMAIN='LANDSLIDE_SENTINEL'
def stamp(now): return datetime.fromtimestamp(now,timezone.utc).isoformat()
def memory_dependencies(session): return dict(calibration=session.contract['calibration'],site=session.fixture['site'],policy=MEMORY_POLICY, monitoring_policy=c.digest(session.contract),health={ch:any(v['sensor']==ch and v['healthy'] for v in session.frames) for ch in ('displacement','reserve')})
