class SentinelMemory: def __init__(self,directory): self.drs=LocalDRS(Path(directory)) self.events=[]
def _write(self,session,kind,value,sources,ttl): c.require(type(ttl) is int and 0<ttl<=86400,'memory_finite_validity') c.require(session.source.sample().evaluation_time < session.expires, 'memory_current_time') now=session.source.sample().evaluation_time material=dict(kind=kind,request=session.request,dependencies=memory_dependencies(session),value=value,sources=sources) review=_review(session.root,material,now) record=_record(material,review,now,ttl,session.root) plain=address.meaning_record_to_plain_data_v01(record) result=resolver.write_semantic_record(self.drs,resolver.SemanticDRSRecordInput(record_id=record.meaning_record_id, domain=DOMAIN,content=dict(kind=kind,request=session.request,worldstate=memory_dependencies(session),material=material, record=plain,root_result=kernel.roots.root_decision_result_to_plain_dict_v01(review[2])), semantic_keys=('monitoring',kind),time_envelope=dict(pt_created_at=stamp(now),kt_asof=stamp(now),et_observed_at=stamp(now), ct_session_anchor=session.id,ttl_seconds=ttl,freshness_class='static',valid_from=stamp(now),valid_to=stamp(now+ttl)), provenance=dict(request_id=session.id,created_by='root_orchestrator',trace_refs=[dict(trace_id=sources[0])]), root_final_ref=review[2].decision_id,worldstate_ref=c.digest(material['dependencies']))) self.events.append(dict(op='WRITE',record=result,root_input=kernel.roots.root_decision_input_to_plain_dict_v01(review[1]), records_written=1,storage='EXPLICIT_DURABLE_LOCAL_DRS',creates_permission=False)) return record.meaning_record_id
def remember(self,session,ttl=3600): c.require(all(r.status=='COMPLETED' for r in session.results),'memory_actual_diagnostic_work') actual=json.loads(caps.values(session.results[-1].result.output)['material']) # Opaque result identities belong to source references, not free-text summaries. value=dict(selection=actual['selection'],checked_sensors=actual['checked_sensors'],healthy=actual['healthy']) return self._write(session,'semantic_recipe',value, [session.work_artifact.artifact_id,session.results[-1].result.result_id],ttl)
def select(self,*,root,request,dependency,now,kind='semantic_recipe',policy=MEMORY_POLICY): query=resolver.SemanticResolveQuery(query_id=c.identity('memory_search',dict(root=root,request=request,dependency=dependency,now=now,kind=kind)), domain=DOMAIN,semantic_terms=('monitoring',kind),content_filters=dict(kind=kind,request=request), temporal_query=dict(as_of=stamp(now)),worldstate=dependency,require_root_review=True) report=resolver.resolve_semantic_candidates(self.drs,query,layers=('work',)) event=dict(op='SEARCH',query=asdict(query),report=asdict(report),evaluations=[]) self.events.append(event) for candidate in report.candidates: wrapper=self.drs.read_record('work',candidate.record_id) value=wrapper['content'];material=value['material'];plain=value['record'] oldtime=plain['time_envelope'];owner=plain['authority_envelope']['owning_local_root_id'] # Rebuild historical value only; this is not current execution authority. historical=_review(owner,material,oldtime['pt_created_at']) c.require(kernel.roots.root_decision_result_to_plain_dict_v01(historical[2])==value['root_result'],'memory_historical_root_binding') record=_record(material,historical,oldtime['pt_created_at'],oldtime['ttl_seconds'],owner) c.require(address.meaning_record_to_plain_data_v01(record)==plain and record.meaning_record_id==candidate.record_id,'memory_record_content_binding') current=memory.build_drs_temporal_query_v01(query_mode='CURRENT_DECISION',semantic_address_id=record.semantic_address.semantic_address_id, scope_fingerprint=c.digest(dependency),as_of=now,evaluation_time=now,evaluation_time_source='INJECTED_CURRENT_DECISION_TIME', time_range_start=now,time_range_end=now+1,required_time_axes=('PT','KT','ET','CT','TTL','VALIDITY'), freshness_policy_id=record.time_envelope.freshness_policy_id,max_age_seconds=record.time_envelope.ttl_seconds, domain=DOMAIN,risk_class='LOW',reuse_intent='CONTEXT',requested_reuse_classes=('CONTEXT_ONLY',), required_evidence_classes=('SOURCE_IDENTITY','SOURCE_INTEGRITY','PROVENANCE_CHAIN','TIME_FITNESS','POLICY_COMPATIBILITY', 'SCHEMA_COMPATIBILITY','CONFLICT_CLEARANCE','ROOT_DECISION','SOURCE_HISTORY'),forbidden_changes=('POLICY_CHANGED',), policy_version=policy,schema_versions=(MEMORY_POLICY,),owning_local_root_id=root) ev=memory.evaluate_drs_candidate_v01(semantic_address=record.semantic_address,query=current,meaning_record=record) event['evaluations'].append(memory.query_evaluation_state_to_plain_data_v01(ev)) if candidate.blocked or not ev.eligible_for_ranking:continue budget=memory.build_memory_descent_budget_v01(max_depth=0,max_records_opened=1,max_pointers_opened=0,max_artifacts_opened=0, max_bytes_opened=0,max_lineage_edges=0,max_conflict_records=0) plan=memory.build_retrieval_plan_v01(query_id=current.query_id,semantic_address_id=record.semantic_address.semantic_address_id, proposed_record_ids=(record.meaning_record_id,),proposed_memory_pointer_ids=(),proposed_artifact_pointer_ids=(), requested_descent_class='SUMMARY_ONLY',proposed_budget_id=budget.memory_descent_budget_id,required_access_policy_ids=(),reason_codes=()) review=kernel.root_review(root,current.query_id,plan.retrieval_plan_id,record.semantic_address.semantic_address_id, dict(eligible=ev.eligible_for_ranking,current_dependency=material['dependencies']==dependency),record.meaning_record_id, 'sentinel:memory:bsep','sentinel:memory:topology',now,predicate='approve_controlled_memory_descent_plan_v01', claim_value=memory.retrieval_plan_to_plain_data_v01(plan)) root_hash=integrity.domain_separated_sha256_hex_v01(domain='hedgehog:drs:memory_descent_root_result_binding:v01', payload=c.canonical(kernel.roots.root_decision_result_to_plain_dict_v01(review[2]))) req=memory.build_memory_descent_request_v01(retrieval_plan_id=plan.retrieval_plan_id,query_id=current.query_id, owning_local_root_id=root,root_kernel_id=review[0].kernel_id,root_decision_input_id=review[1].decision_input_id, root_decision_id=review[2].decision_id,root_decision_hash=root_hash,requested_descent_class='SUMMARY_ONLY',approved_descent_class='SUMMARY_ONLY', proposed_budget_id=budget.memory_descent_budget_id,approved_budget=budget,approved_record_ids=(record.meaning_record_id,), approved_memory_pointer_ids=(),approved_artifact_pointer_ids=()) result=memory.execute_local_memory_descent_v01(retrieval_plan=plan,proposed_budget=budget,descent_request=req, root_kernel=review[0],root_decision_input=review[1],root_decision_result=review[2],source_records=(record,)) c.require(result.limits_respected and not result.reason_codes and result.opened_record_ids==(record.meaning_record_id,), 'memory_descent_refused') event.update(query_current=memory.drs_temporal_query_to_plain_data_v01(current),plan=memory.retrieval_plan_to_plain_data_v01(plan), descent=memory.memory_descent_result_to_plain_data_v01(result),root=kernel.roots.root_decision_result_to_plain_dict_v01(review[2])) selected=json.loads(result.safe_summaries[0]) return selected,dict(record_id=record.meaning_record_id,descent_id=result.memory_descent_result_id) return None
class ControlledEpisode(Sentinel): """One continuing coordinator; story labels never select its decisions.""" def __init__(self,directory,fixture): from .events_v01 import EventBook,AllocationLedger,CapabilityState from .incident_policy_v01 import Incident from .outbox_v01 import Outbox,Receiver super().__init__(directory,fixture) self.book=EventBook();self.budgets=AllocationLedger();self.capabilities=CapabilityState() self.budgets.allocate('pure_work',32,'continuing_episode_local_compute') self.incident=Incident();self.routes=[];self.work_mode='deterministic';self.role_results=[] self.outbox=Outbox(self.directory/'outbox');self.receiver=Receiver(self.directory/'receiver') self.pending_worker=None;self.pending_return=[];self.effects=[];self.report=None save(self.directory/'signal_readback.json',dict(signal=False,receipt_ref=None))
def ingest(self,records,tick): self.book.ingest(records,tick);self.tick=self.book.tick from .events_v01 import compatibility self.frames=[compatibility(record) for record in self.book.latest.values() if record['value'] is not None and record['channel'] in ('rainfall','displacement','reserve')] self.journal('EVENTS_INGESTED',tick=tick,records=records)
def ingest_rainfall(self,value): from .events_v01 import observation old=self.book.latest['rainfall'] self.ingest([observation('rainfall',value['value'],value['scenario_tick'],old['sequence']+1)],value['scenario_tick']) c.require(all(self.book.current(ch,'configuration') for ch in ('displacement','reserve')),'retained_configuration_current')
def intake(self,tick): self.book.advance(tick) result=super().intake(tick) if result is not None: from .events_v01 import compatibility result['frames']=[compatibility(v) for v in self.book.latest.values() if v['value'] is not None] result['absent_channels']=[ch for ch,v in self.book.latest.items() if v['value'] is None] result['observation_ids']={ch:v['observation_id'] for ch,v in self.book.latest.items()} result['observed_at']={ch:v['observed_end'] for ch,v in self.book.latest.items()} c.require(all(t<=tick for t in result['observed_at'].values()),'future_rich_intake') return result
def command(self,value,checks,*,accepted_work=None): token=caps.EXECUTION.set(self) try:effect=k.dispatch(self,value,checks,accepted_work=accepted_work) finally:caps.EXECUTION.reset(token) self.effects.append(effect);return effect
def validate_effect(self,inputs): command=json.loads(inputs['command']);op=command.get('op') if op=='READ_RESERVE_SERIES': c.require(inputs['session']==self.id and inputs['version']==self.version,'current_local_invocation') c.require(set(command)=={'op','basis_ref','source_ref','tick'} and command['tick']==self.tick,'series_read_current') c.require(command['source_ref']=='synthetic:reserve_series:v01' and bool(command['basis_ref']),'series_read_source') c.require(self.source.snapshot.evaluation_time<self.expires,'monitoring_expired') basis=getattr(self,'accepted_plans',{}).get(command['basis_ref']) output=k.validate_reviewed_work(self,basis) c.require(output['stage']=='PLAN' and any(v['action']==op and v['source_ref']==command['source_ref'] for v in output['checks']),'series_current_selected_plan') elif op in ('QUEUE_INCIDENT_REPORT','DELIVER_INCIDENT_REPORT'): c.require(inputs['session']==self.id and inputs['version']==self.version,'current_local_invocation') c.require(self.source.snapshot.evaluation_time<self.expires,'monitoring_expired') expected={'op','basis_ref','report'} if op=='QUEUE_INCIDENT_REPORT' else {'op','basis_ref','message_id'} c.require(set(command)==expected and bool(command['basis_ref']),'report_command_shape') if op=='DELIVER_INCIDENT_REPORT': c.require(self.capabilities.available('site_upload'),'upload_unavailable') self.outbox.read(command['message_id']) else:c.require(len(c.canonical(command['report']))<8192 and command['report']['classification']=='TEST','report_bound') else:super().validate_effect(inputs)
def execute_effect(self,inputs,invocation_id): command=json.loads(inputs['command']);op=command['op'] if op=='READ_RESERVE_SERIES': result=dict(op=op,classification='MOCK_SOURCE_READ',records=self.read_reserve_series(command['source_ref'],command['tick']), invocation_id=invocation_id,adapter_kind='DETERMINISTIC_MOCK') self.executed[invocation_id]=result;return result if op in ('QUEUE_INCIDENT_REPORT','DELIVER_INCIDENT_REPORT'): result=(self.outbox.queue(command['report']) if op=='QUEUE_INCIDENT_REPORT' else self.outbox.deliver(command['message_id'],self.receiver)) result=dict(result,op=op,invocation_id=invocation_id,adapter_kind='DETERMINISTIC_MOCK') self.executed[invocation_id]=result;return result result=super().execute_effect(inputs,invocation_id) if op=='SET_LOCAL_SIGNAL_STATE':save(self.directory/'signal_readback.json',dict(signal=self.signal,receipt_ref=invocation_id)) if op=='APPLY_MONITORING_CONFIG':result.update(configured_at=self.tick,due_at=self.next_intake) return result
def read_signal(self): return json.loads((self.directory/'signal_readback.json').read_bytes())
