def start_optional(self): c.require(self.capabilities.available('site_context') and self.pending_worker is None,'optional_request_not_admissible') old=c.canonical(dict(observations=self.book.latest,capability_revision=self.capabilities.revision,root=self.root)) self.budgets.allocate('optional_context',2,c.digest(old));self.budgets.consume('optional_context','REQUEST_ENTER') self.capabilities.request('site_context',c.digest(old)) self.optional_started=threading.Event();self.optional_release=threading.Event() self.pending_worker=threading.Thread(target=pending_stub,args=(old,self.directory,self.optional_started,self.optional_release,self.pending_return), name='sentinel-ls1-optional-immutable-worker') self.pending_worker.start();c.require(self.optional_started.wait(5),'optional_worker_not_started') self.pending_snapshot=c.canonical(self.budgets.tasks['optional_context']) self.journal('OPTIONAL_ACTUALLY_PENDING',context_sha256=c.digest(old),task=self.budgets.tasks['optional_context'])
