def evaluate_local(self): assessment=self.incident.evaluate(self.book,contract=self.contract) if assessment['new_incident']: task='critical:'+self.incident.incident_id self.budgets.allocate(task,6,c.digest(self.book.latest)) self.budgets.consume(task,'LOCAL_WORK_ENTER');work=self.local_work() self.budgets.consume(task,'ROOT_NATIVE_SIGNAL_ENTER') effect=self.command(dict(op='SET_LOCAL_SIGNAL_STATE',state='ON',basis_ref=c.identity('critical_witnesses',assessment)), dict(hard_floor=assessment['hard_critical'],current_work=work['features']['hard_critical'],single_incident=not self.read_signal()['signal'])) self.on_effect=effect;self.on_completed=self.journal('INCIDENT_ON_COMPLETED',tick=self.tick,packet_id=effect['packet_id']) self.budgets.entries.append(dict(operation='NATIVE_RESULT',task=task,packet_id=effect['packet_id'], receipt_id=effect['receipt']['artifact_id'],host_revision=self.host.revision,root=self.root)) if self.pending_worker is not None: c.require(not self.pending_return and c.canonical(self.budgets.tasks['optional_context'])==self.pending_snapshot,'pending_costs_preserved') self.report=dict(incident_id=self.incident.incident_id,previous_report_ref=None,classification='TEST', generated_at=self.tick,historical_interval=[self.tick,self.tick],source_hashes=[c.digest(v) for v in self.book.latest.values()], signal_receipt=effect['receipt']['artifact_id'],observations=json.loads(c.canonical(self.book.latest))) self.budgets.consume(task,'ROOT_NATIVE_QUEUE_ENTER') queued=self.command(dict(op='QUEUE_INCIDENT_REPORT',basis_ref=effect['receipt']['artifact_id'],report=self.report), dict(actual_on=self.read_signal()['signal'],incident_active=self.incident.state=='ACTIVE')) self.message=json.loads(queued['output']['material']) elif assessment['clearance']: effect=self.command(dict(op='SET_LOCAL_SIGNAL_STATE',state='OFF',basis_ref=c.identity('clearance',assessment)), dict(measured_clearance=assessment['clearance'],incident_active=self.incident.state=='ACTIVE',actual_signal=self.read_signal()['signal'])) c.require(not self.read_signal()['signal'],'off_readback') self.incident.close(self.tick,effect['receipt']['artifact_id']);self.off_effect=effect save(self.directory/'clearance.json',dict(assessment=assessment,effect=effect,readback=self.read_signal())) self.journal('LOCAL_ASSESSMENT',tick=self.tick,assessment=assessment,incident_state=self.incident.state,signal=self.read_signal()['signal']) return assessment
def release_optional(self): if self.pending_worker is None:return self.optional_release.set();self.pending_worker.join(10) c.require(not self.pending_worker.is_alive(),'owned_optional_not_joined') self.budgets.consume('optional_context','HISTORICAL_RESPONSE_RETURN') self.budgets.tasks['optional_context']['state']='COMPLETED_HISTORICAL_ONLY' self.journal('OPTIONAL_JOINED',late_response=self.pending_return,budgets=self.budgets.tasks)
def deliver(self): prior=next((row for row in reversed(self.outbox.trail) if row['state']=='RECEIVED' and row['message_id']==self.message['message_id']),None) if prior is not None: ack=self.receiver.readback(self.message['message_id']) c.require(ack==dict(message_id=prior['message_id'],payload_sha256=prior['payload_sha256']),'duplicate_ack_mismatch') c.require(c.digest(self.outbox.read(prior['message_id']))==ack['payload_sha256'],'duplicate_payload_mismatch') self.journal('DELIVERY_DUPLICATE_CONFIRMED',ack=ack,creates_new_action=False) return dict(status='ALREADY_RECEIVED',ack=ack) return self.command(dict(op='DELIVER_INCIDENT_REPORT',basis_ref=self.message['message_id'],message_id=self.message['message_id']), dict(upload_current=self.capabilities.available('site_upload'),immutable_report=self.outbox.read(self.message['message_id'])==c.canonical(self.report)))
def remember_incident(self): c.require(self.incident.state=='CLOSED' and not self.read_signal()['signal'],'incident_summary_closed') store=SentinelMemory(self.directory/'incident_drs') value=dict(incident_id=self.incident.incident_id,signal_on_at=self.on_completed['tick'], signal_off_at=self.incident.transitions[-1]['tick'],message_id=self.message['message_id'], off_receipt=self.off_effect['receipt']['artifact_id']) ref=store._write(self,'incident_summary',value,[c.digest(self.off_effect['receipt'])],3600) save(self.directory/'incident_memory_write.json',dict(record_id=ref,value=value,events=store.events)) return ref
def query_incident(self): store=SentinelMemory(self.directory/'incident_drs') selected=store.select(root=self.root,request=self.request,dependency=memory_dependencies(self), now=self.source.sample().evaluation_time,kind='incident_summary') c.require(selected is not None,'incident_memory_not_found') self.work_mode='memory_informed' try:work=self.pure_consumer('sentinel.information.v01',dict(summary=c.canonical(selected[0]).decode(),record_id=selected[1]['record_id'])) finally:self.work_mode='deterministic' result=dict(selected=selected,events=store.events,result=plain(work[1])) save(self.directory/'incident_memory_query.json',result);return result

"""Immutable local outbox and independently persisted mock receiver acknowledgements."""
import json
from pathlib import Path
from . import contracts_v01 as c


class Outbox:
    def __init__(self,directory):
        self.directory=Path(directory);self.directory.mkdir(parents=True,exist_ok=True)
        self.trail=[]

    def queue(self,report):
        raw=c.canonical(report);ref=c.identity('message',report);path=self.directory/(c.digest(ref.encode())+'.json')
        if path.exists(): c.require(path.read_bytes()==raw,'outbox_identity_conflict')
        else:
            with path.open('xb') as f:f.write(raw)
        self.trail.append(dict(state='QUEUED',message_id=ref,payload_sha256=c.digest(raw)))
        return dict(message_id=ref,payload_sha256=c.digest(raw))

    def read(self,ref):
        raw=(self.directory/(c.digest(ref.encode())+'.json')).read_bytes()
        c.require(c.identity('message',json.loads(raw))==ref,'outbox_immutable_binding')
        return raw

    def deliver(self,ref,receiver):
        raw=self.read(ref);expected=dict(message_id=ref,payload_sha256=c.digest(raw))
        self.trail.append(dict(state='ATTEMPTED',**expected))
        ack=receiver.receive(ref,raw)
        if ack!=expected or receiver.readback(ref)!=expected:
            self.trail.append(dict(state='UNKNOWN',**expected));raise ValueError('receiver_ack_not_verified')
        self.trail.append(dict(state='RECEIVED',**expected));return ack


class Receiver:
    def __init__(self,directory):
        self.directory=Path(directory);self.directory.mkdir(parents=True,exist_ok=True)

    def receive(self,ref,raw):
        c.require(c.identity('message',json.loads(raw))==ref,'receiver_message_binding')
        path=self.directory/(c.digest(ref.encode())+'.json')
        if path.exists(): c.require(path.read_bytes()==raw,'receiver_message_conflict')
        else:
            with path.open('xb') as f:f.write(raw)
        return self.readback(ref)

    def readback(self,ref):
        raw=(self.directory/(c.digest(ref.encode())+'.json')).read_bytes()
        return dict(message_id=ref,payload_sha256=c.digest(raw))

from __future__ import annotations

import json
from pathlib import Path


DRS_LAYERS = {"work", "thoughts", "up", "quarantine", "deadends"}
REQUIRED_RECORD_FIELDS = {
    "record_id",
    "layer",
    "type",
    "domain",
    "content",
    "time_envelope",
    "provenance",
    "status",
}
SENSITIVE_KEY_FRAGMENTS = {
    "credential",
    "credentials",
    "api_key",
    "apikey",
    "token",
    "password",
    "secret",
    "private_key",
    "card_number",
    "cvv",
    "passport_number",
}


def _safe_filename(record_id: str) -> str:
    safe = "".join(char if char.isalnum() or char in "._-" else "_" for char in record_id)
    return f"{safe}.json"


def iter_json_keys(value):
    if isinstance(value, dict):
        for key, child in value.items():
            yield key
            yield from iter_json_keys(child)
    elif isinstance(value, list):
        for item in value:
            yield from iter_json_keys(item)


def assert_no_sensitive_drs_keys(record: dict) -> None:
    for key in iter_json_keys(record):
        normalized = key.lower()
        if any(fragment in normalized for fragment in SENSITIVE_KEY_FRAGMENTS):
            raise ValueError(f"DRS record contains sensitive key name: {key}")


def _validate_pointer(record: dict) -> None:
    if "pointer" not in record:
        return
    pointer = record["pointer"]
    if not isinstance(pointer, dict):
        raise ValueError("DRS record pointer must be an object")
    if "storage_kind" not in pointer or "ref" not in pointer:
        raise ValueError("DRS record pointer requires storage_kind and ref")


class LocalDRS:
    def __init__(self, root_path: Path | str = "data/drs"):
        self.root_path = Path(root_path)

    def layer_path(self, layer: str) -> Path:
        if layer not in DRS_LAYERS:
            raise ValueError(f"invalid DRS layer: {layer}")
        path = self.root_path / layer
        path.mkdir(parents=True, exist_ok=True)
        return path

    def write_record(self, record: dict) -> Path:
        missing = REQUIRED_RECORD_FIELDS - set(record)
        if missing:
            raise ValueError(f"DRS record missing required fields: {sorted(missing)}")
        if not record.get("time_envelope"):
            raise ValueError("DRS record requires time_envelope")
        assert_no_sensitive_drs_keys(record)
        _validate_pointer(record)

        layer = record["layer"]
        path = self.layer_path(layer) / _safe_filename(record["record_id"])
        payload = json.dumps(record, indent=2, sort_keys=True)

        if path.exists():
            with path.open("r", encoding="utf-8") as handle:
                existing = json.load(handle)
            if existing != record:
                raise ValueError(f"DRS record already exists with different content: {path}")
            return path

        path.write_text(payload, encoding="utf-8")
        return path

    def read_record(self, layer: str, record_id: str) -> dict:
        path = self.layer_path(layer) / _safe_filename(record_id)
        with path.open("r", encoding="utf-8") as handle:
            return json.load(handle)

    def read_layer(self, layer: str) -> list[dict]:
        path = self.layer_path(layer)
        records = []
        for record_path in sorted(path.glob("*.json")):
            with record_path.open("r", encoding="utf-8") as handle:
                records.append(json.load(handle))
        return records

    def query_records(self, temporal_query: dict, layers: list[str]) -> list[dict]:
        if not temporal_query or "as_of" not in temporal_query:
            raise ValueError("TemporalQuery with as_of is required")

        records = []
        for layer in layers:
            for record in self.read_layer(layer):
                if record.get("time_envelope"):
                    records.append(json.loads(json.dumps(record)))
        return records

