def _profile(type_name: str) -> tuple[str, str, str, tuple[str, ...]]: for name, identity_field, domain, prefix, fields in _IDENTITY_PROFILES: if name == type_name: return identity_field, domain, prefix, fields raise ValueError("drs_identity_profile_invalid")
def _identity_plain(value: object) -> object: if type(value) is tuple: return [_identity_plain(item) for item in value] if type(value) is DRSTemporalQueryV01: return [_identity_plain(getattr(value, name)) for name in _QUERY_FIELDS] if type(value) is QueryEvaluationStateV01: return [ _identity_plain(getattr(value, name)) for name in _QUERY_EVALUATION_FIELDS ] if type(value) is ResolutionCandidateV01: return [_identity_plain(getattr(value, name)) for name in _CANDIDATE_FIELDS] if type(value) is RetrievalPlanV01: return [_identity_plain(getattr(value, name)) for name in _PLAN_FIELDS] if type(value) is MemoryDescentBudgetV01: return [_identity_plain(getattr(value, name)) for name in _BUDGET_FIELDS] if type(value) is MemoryDescentRequestV01: return [_identity_plain(getattr(value, name)) for name in _REQUEST_FIELDS] if type(value) is MemoryDescentResultV01: return [_identity_plain(getattr(value, name)) for name in _RESULT_FIELDS] if type(value) is DRSResolutionReportV01: return [_identity_plain(getattr(value, name)) for name in _REPORT_FIELDS] if type(value) is LegacyDRSProjectionV01: return [ _identity_plain(getattr(value, name)) for name in _LEGACY_PROJECTION_FIELDS ] if type(value) is RootShortcutAuthorizationProjectionV01: return [_identity_plain(getattr(value, name)) for name in _ROOT_SHORTCUT_FIELDS] if type(value) is ReuseCertificateV01: return [_identity_plain(getattr(value, name)) for name in _REUSE_CERTIFICATE_FIELDS] return _canonical_plain_value(value)
def _plain_value(value: object) -> object: if type(value) is tuple: return [_plain_value(item) for item in value] if type(value) is DRSTemporalQueryV01: return {name: _plain_value(getattr(value, name)) for name in _QUERY_FIELDS} if type(value) is QueryEvaluationStateV01: return { name: _plain_value(getattr(value, name)) for name in _QUERY_EVALUATION_FIELDS } if type(value) is ResolutionCandidateV01: return {name: _plain_value(getattr(value, name)) for name in _CANDIDATE_FIELDS} if type(value) is RetrievalPlanV01: return {name: _plain_value(getattr(value, name)) for name in _PLAN_FIELDS} if type(value) is MemoryDescentBudgetV01: return {name: _plain_value(getattr(value, name)) for name in _BUDGET_FIELDS} if type(value) is MemoryDescentRequestV01: return {name: _plain_value(getattr(value, name)) for name in _REQUEST_FIELDS} if type(value) is MemoryDescentResultV01: return {name: _plain_value(getattr(value, name)) for name in _RESULT_FIELDS} if type(value) is DRSResolutionReportV01: return {name: _plain_value(getattr(value, name)) for name in _REPORT_FIELDS} if type(value) is SemanticAddressV01: return semantic_address_to_plain_data_v01(value) if type(value) is MeaningRecordV01: return meaning_record_to_plain_data_v01(value) if type(value) is LegacyDRSProjectionV01: return legacy_drs_projection_to_plain_data_v01(value) if type(value) is RootShortcutAuthorizationProjectionV01: return root_shortcut_authorization_projection_to_plain_data_v01(value) if type(value) is ReuseCertificateV01: return reuse_certificate_to_plain_data_v01(value) return _plain_data_value(value)
def _identity(value: object, type_name: str) -> str: identity_field, domain, prefix, fields = _profile(type_name) material = [ _identity_plain(getattr(value, name)) for name in fields if name != identity_field ] digest = _domain_separated_sha256_hex_v01( domain=domain, payload=_canonical_json_bytes_v01(material), ) return prefix + digest
def _id_reason(value: object, type_name: str) -> str | None: identity_field, _, prefix, _ = _profile(type_name) actual = getattr(value, identity_field) if ( type(actual) is not str or not actual.startswith(prefix) or len(actual) != len(prefix) + 64 or not _is_sha256(actual[len(prefix):]) or actual != _identity(value, type_name) ): return "drs_identity_invalid" return None
def _finish( provisional: object, *, type_name: str, reasons: tuple[str, ...], validator: object, ) -> object: if reasons: raise ValueError(reasons[0]) from None identity_field, _, _, _ = _profile(type_name) final = _replace(provisional, **{identity_field: _identity(provisional, type_name)}) if not callable(validator): raise ValueError("drs_builder_invalid") from None valid, final_reasons = validator(final) if not valid: raise ValueError(final_reasons[0]) from None return final
def _version_reasons(value: object) -> list[str]: if type(value) is not str: return ["drs_exact_type_required"] if value != _PROFILE_VERSION: return ["drs_schema_version_mismatch"] return []
def _prefixed_id(value: object, prefix: str) -> bool: return ( type(value) is str and value.startswith(prefix) and len(value) == len(prefix) + 64 and _is_sha256(value[len(prefix):]) )
def _exact_bool_reasons(values: tuple[object, ...]) -> list[str]: return [] if all(type(value) is bool for value in values) else ["drs_exact_type_required"]
def _query_reasons(value: object, *, check_identity: bool) -> tuple[str, ...]: if type(value) is not DRSTemporalQueryV01: return ("drs_exact_type_required",) reasons = _version_reasons(value.temporal_query_version) if type(value.query_mode) is not str or value.query_mode not in DRS_QUERY_MODES_V01: reasons.append("drs_query_mode_invalid") if not _prefixed_id(value.semantic_address_id, "drsaddr_v01:"): reasons.append("drs_address_scope_mismatch") if not _is_sha256(value.scope_fingerprint): reasons.append("drs_sha256_invalid") for item in ( value.as_of, value.evaluation_time, value.time_range_start, value.time_range_end, ): if not _is_int64(item): reasons.append("drs_time_type_invalid") if ( type(value.time_range_start) is int and type(value.as_of) is int and type(value.time_range_end) is int and not (value.time_range_start <= value.as_of < value.time_range_end) ): reasons.append("drs_time_validity_interval_invalid") if type(value.evaluation_time_source) is not str or value.evaluation_time_source not in _EVALUATION_TIME_SOURCES: reasons.append("drs_evaluation_time_source_invalid") reasons.extend( _token_tuple_reasons(value.required_time_axes, maximum_items=16) ) if type(value.required_time_axes) is tuple and any( item not in _TIME_AXES for item in value.required_time_axes if type(item) is str ): reasons.append("drs_time_axis_missing") if not _is_reference(value.freshness_policy_id): reasons.append("drs_freshness_policy_invalid") if not _is_nonnegative_int(value.max_age_seconds): reasons.append("drs_exact_int_required") for item in (value.domain, value.risk_class, value.policy_version): if not _is_token(item): reasons.append("drs_query_component_invalid") if type(value.reuse_intent) is not str or value.reuse_intent not in _REUSE_INTENTS: reasons.append("drs_query_component_invalid") reasons.extend( _token_tuple_reasons( value.requested_reuse_classes, maximum_items=16 ) ) if type(value.requested_reuse_classes) is tuple and any( item not in DRS_REUSE_CLASSES_V01 for item in value.requested_reuse_classes if type(item) is str ): reasons.append("drs_reuse_class_invalid") reasons.extend( _token_tuple_reasons( value.required_evidence_classes, maximum_items=32 ) ) reasons.extend( _token_tuple_reasons(value.forbidden_changes, maximum_items=32) ) reasons.extend( _token_tuple_reasons(value.schema_versions, maximum_items=32) ) if not _is_reference(value.owning_local_root_id): reasons.append("drs_root_owner_mismatch") if check_identity and not reasons: reason = _id_reason(value, "DRSTemporalQueryV01") if reason: reasons.append(reason) return _dedupe(reasons)
def build_drs_temporal_query_v01( *, query_mode: str, semantic_address_id: str, scope_fingerprint: str, as_of: int, evaluation_time: int, evaluation_time_source: str, time_range_start: int, time_range_end: int, required_time_axes: tuple[str, ...], freshness_policy_id: str, max_age_seconds: int, domain: str, risk_class: str, reuse_intent: str, requested_reuse_classes: tuple[str, ...], required_evidence_classes: tuple[str, ...], forbidden_changes: tuple[str, ...], policy_version: str, schema_versions: tuple[str, ...], owning_local_root_id: str, ) -> DRSTemporalQueryV01: try: provisional = DRSTemporalQueryV01( temporal_query_version=_PROFILE_VERSION, query_id="drsquery_v01:" + "0" * 64, query_mode=query_mode, semantic_address_id=semantic_address_id, scope_fingerprint=scope_fingerprint, as_of=as_of, evaluation_time=evaluation_time, evaluation_time_source=evaluation_time_source, time_range_start=time_range_start, time_range_end=time_range_end, required_time_axes=required_time_axes, freshness_policy_id=freshness_policy_id, max_age_seconds=max_age_seconds, domain=domain, risk_class=risk_class, reuse_intent=reuse_intent, requested_reuse_classes=requested_reuse_classes, required_evidence_classes=required_evidence_classes, forbidden_changes=forbidden_changes, policy_version=policy_version, schema_versions=schema_versions, owning_local_root_id=owning_local_root_id, ) return _finish(provisional, type_name="DRSTemporalQueryV01", reasons=_query_reasons(provisional, check_identity=False), validator=validate_drs_temporal_query_v01) except ValueError as exc: reason = str(exc) raise ValueError(reason if reason.startswith("drs_") else "drs_temporal_query_invalid") from None except Exception: raise ValueError("drs_temporal_query_invalid") from None
def validate_drs_temporal_query_v01(value: object) -> tuple[bool, tuple[str, ...]]: try: reasons = _query_reasons(value, check_identity=True) return not reasons, reasons except Exception: return False, ("drs_temporal_query_invalid",)
def drs_temporal_query_to_plain_data_v01(value: object) -> dict[str, object]: if type(value) is not DRSTemporalQueryV01: raise ValueError("drs_exact_type_required") from None return {name: _plain_value(getattr(value, name)) for name in _QUERY_FIELDS}
