_SENSITIVITY_CLASSES = ( "PUBLIC", "INTERNAL", "CONFIDENTIAL_REFERENCE_ONLY", "SECRET_REFERENCE_ONLY", ) _LINEAGE_RELATION_CLASSES = ( "DERIVED_FROM", "SUPPORTS", "WARNS_AGAINST", "CONTRADICTS", "SUPERSEDES", "REPLACES", "SAME_TRACE", "REFERENCES", "BLOCKED_BY_POLICY", "DEGRADED_FROM", ) _AUTHORITY_CLASSES = ( "UNTRUSTED_SEMANTIC_DRAFT", "CONNECTOR_OBSERVATION", "EVIDENCE_CANDIDATE", "ROOT_ACCEPTED_CONTEXT", "ROOT_ACCEPTED_WORK", "ROOT_FINAL_REFERENCE", "ACTION_HISTORY_REFERENCE", ) _ROOT_ACCEPTANCE_STATES = ( "UNREVIEWED", "ACCEPTED_CONTEXT", "ACCEPTED_WORK", "REJECTED", "QUARANTINED", ) _ROOT_EVIDENCE_AUTHORITY_CLASSES = ( "ROOT_ACCEPTED_CONTEXT", "ROOT_ACCEPTED_WORK", "ROOT_FINAL_REFERENCE", ) _INT64_MIN = -(2**63) _INT64_MAX = 2**63 - 1 _SHA256_HEX = _re.compile(r"\A[0-9a-f]{64}\Z") _TOKEN = _re.compile(r"\A[A-Za-z0-9][A-Za-z0-9._:/-]{0,127}\Z") _MEDIA_TYPE = _re.compile( r"\A[A-Za-z0-9][A-Za-z0-9.+-]*/" r"[A-Za-z0-9][A-Za-z0-9.+-]{0,126}\Z" ) _REFERENCE = _re.compile( r"\A[A-Za-z0-9][A-Za-z0-9._:/#-]{0,255}\Z" ) _FIELD_NAME = _re.compile(r"\A[a-z][a-z0-9_]{0,127}\Z") _SEALED_REFERENCE = _re.compile( r"\A(?:" r"sealed-secret-ref:[A-Za-z0-9][A-Za-z0-9._:/#-]{0,237}|" r"audit-ref:[A-Za-z0-9][A-Za-z0-9._:/#-]{0,245}|" r"scope-ref:[A-Za-z0-9][A-Za-z0-9._:/#-]{0,245}" r")\Z" ) _G2B_CANONICAL_ID = _re.compile( r"\A(?:drsaddr|drsmem|drsart|drsedge|drsauth|drstime|drsmeaning|" r"drsquery|drsqeval|drscandidate|drsplan|drsbudget|drsdescentreq|" r"drsdescentres|drsrootshortcut|reusecert|drsreport|drslegacyproj|" r"drsg2ahistory)_v01:[0-9a-f]{64}\Z" ) _PRIVATE_KEY = _re.compile(r"-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----", _re.IGNORECASE) _KEY_VALUE_SECRET = _re.compile( r"(?<![A-Za-z0-9])(?:" r"api_key|api-key|apikey|x-api-key|password|passwd|secret|token|" r"access_token|access-token|refresh_token|refresh-token|" r"client_secret|client-secret|" r"authentication_secret|authentication-secret|" r"bank_account|bank-account|iban|cvv" r")[=:]", _re.IGNORECASE, ) _AUTHENTICATION_HEADER = _re.compile( r"(?<![A-Za-z0-9])(?:" r"(?:bearer|basic)[ \t]+\S|" r"authorization:[ \t]*\S" r")", _re.IGNORECASE, ) _IBAN = _re.compile( r"(?<![A-Za-z0-9])" r"[A-Z][ ]?[A-Z][ ]?[0-9][ ]?[0-9]" r"(?:[ ]?[A-Z0-9]){11,30}" r"(?![ ]?[A-Z0-9])", _re.IGNORECASE, ) _CARD_NUMBER = _re.compile( r"(?<![0-9])(?<![0-9][ -])" r"[0-9](?:[ -]?[0-9]){12,18}" r"(?![ -]?[0-9])" ) _PASSPORT = _re.compile( r"(?<![A-Za-z0-9])passport[:_][ \t-]?" r"[A-Za-z0-9]*[0-9][A-Za-z0-9]*(?![A-Za-z0-9])", _re.IGNORECASE, )
_SEMANTIC_ADDRESS_FIELDS = ( "address_profile_version", "namespace", "domain", "subject_class", "intent_class", "meaning_schema_id", "meaning_schema_version", "semantic_address_id", ) _MEMORY_POINTER_FIELDS = ( "pointer_version", "pointer_id", "storage_class", "object_reference", "content_sha256", "record_class", "byte_length", "access_policy_id", "sensitivity_class", "allowed_use_classes", "forbidden_use_classes", "summary_read_permitted", "payload_read_permitted", "creates_authority", "creates_permission", ) _ARTIFACT_POINTER_FIELDS = ( "pointer_version", "pointer_id", "storage_class", "object_reference", "content_sha256", "media_type", "byte_length", "access_policy_id", "sensitivity_class", "allowed_use_classes", "forbidden_use_classes", "summary_read_permitted", "payload_read_permitted", "creates_authority", "creates_permission", ) _LINEAGE_EDGE_FIELDS = ( "lineage_edge_version", "lineage_edge_id", "source_meaning_record_id", "target_meaning_record_id", "relation_class", "claim_dimension", "source_history_hash", "evidence_ref_ids", "created_at", "recording_component", "creates_authority", "transfers_authority", ) _AUTHORITY_ENVELOPE_FIELDS = ( "authority_envelope_version", "authority_envelope_id", "authority_class", "owning_local_root_id", "source_root_decision_input_id", "source_root_decision_id", "source_root_decision_hash", "authority_scope_fingerprint", "root_acceptance_state", "recording_component", "creates_authority", "creates_permission", "action_permission_present", ) _TIME_ENVELOPE_FIELDS = ( "time_envelope_version", "time_envelope_id", "pt_created_at", "kt_as_of", "et_observed_at", "ct_context_anchor", "ttl_seconds", "valid_from", "valid_to", "source_observed_at", "source_reported_at", "system_ingested_at", "system_verified_at", "freshness_policy_id", ) _MEANING_RECORD_FIELDS = ( "meaning_record_version", "meaning_record_id", "semantic_address", "predecessor_record_id", "supersession_reason", "safe_summary", "semantic_tags", "resonance_reason", "memory_pointers", "artifact_pointers", "source_reference_ids", "lineage_edges", "time_envelope", "authority_envelope", "persistent_lifecycle_state", "risk_hints", "conflict_hints", "reuse_policy_class", "policy_version", "schema_versions", "content_fingerprint", "recording_component", "local_reference_kernel_scope", "creates_authority", "creates_permission", )
_IDENTITY_PROFILES = ( ( "SemanticAddressV01", "semantic_address_id", "hedgehog:drs:semantic_address:v01", "drsaddr_v01:", _SEMANTIC_ADDRESS_FIELDS, ), ( "MemoryPointerV01", "pointer_id", "hedgehog:drs:memory_pointer:v01", "drsmem_v01:", _MEMORY_POINTER_FIELDS, ), ( "ArtifactPointerV01", "pointer_id", "hedgehog:drs:artifact_pointer:v01", "drsart_v01:", _ARTIFACT_POINTER_FIELDS, ), ( "LineageEdgeV01", "lineage_edge_id", "hedgehog:drs:lineage_edge:v01", "drsedge_v01:", _LINEAGE_EDGE_FIELDS, ), ( "DRSAuthorityEnvelopeV01", "authority_envelope_id", "hedgehog:drs:authority_envelope:v01", "drsauth_v01:", _AUTHORITY_ENVELOPE_FIELDS, ), ( "DRSTimeEnvelopeV01", "time_envelope_id", "hedgehog:drs:time_envelope:v01", "drstime_v01:", _TIME_ENVELOPE_FIELDS, ), ( "MeaningRecordV01", "meaning_record_id", "hedgehog:drs:meaning_record:v01", "drsmeaning_v01:", _MEANING_RECORD_FIELDS, ), )
