def _dedupe(reasons: list[str]) -> tuple[str, ...]: return tuple(dict.fromkeys(reasons))
def _is_exact_str(value: object) -> bool: return type(value) is str
def _is_token(value: object) -> bool: return _token_reason(value) is None
def _is_sha256(value: object) -> bool: return type(value) is str and _SHA256_HEX.fullmatch(value) is not None
def _is_int64(value: object) -> bool: return type(value) is int and _INT64_MIN <= value <= _INT64_MAX
def _is_nonnegative_int(value: object) -> bool: return type(value) is int and 0 <= value <= _INT64_MAX
def _is_reference(value: object, *, allow_none: bool = False) -> bool: if allow_none and value is None: return True return _reference_reason(value) is None
def _token_reason(value: object) -> str | None: if type(value) is not str: return "drs_exact_type_required" if _TOKEN.fullmatch(value) is None: return "drs_text_bound_invalid" return _secret_reason(value)
def _reference_reason(value: object) -> str | None: if type(value) is not str: return "drs_exact_type_required" if _REFERENCE.fullmatch(value) is None: secret = _secret_reason(value) return secret or "drs_text_bound_invalid" return _secret_reason(value)
def _media_type_reason(value: object) -> str | None: if type(value) is not str: return "drs_exact_type_required" if len(value) > 128 or _MEDIA_TYPE.fullmatch(value) is None: return "drs_text_bound_invalid" return None
def _typed_id_reason(value: object, prefix: str) -> str | None: if type(value) is not str: return "drs_exact_type_required" if ( not value.startswith(prefix) or len(value) != len(prefix) + 64 or not _is_sha256(value[len(prefix):]) ): return "drs_text_bound_invalid" return None
def _secret_reason(value: str) -> str | None: if _SHA256_HEX.fullmatch(value) or _G2B_CANONICAL_ID.fullmatch(value): return None if value.startswith(("sealed-secret-ref:", "audit-ref:", "scope-ref:")): if _SEALED_REFERENCE.fullmatch(value) is None: return "drs_secret_payload_forbidden" if _KEY_VALUE_SECRET.search(value) or _AUTHENTICATION_HEADER.search(value): return "drs_secret_payload_forbidden" if _PRIVATE_KEY.search(value) or _IBAN.search(value): return "drs_secret_payload_forbidden" if _CARD_NUMBER.search(value) or _PASSPORT.search(value): return "drs_secret_payload_forbidden" return None
def _bounded_text(value: object, *, maximum: int) -> str | None: if type(value) is not str or not value: return "drs_exact_type_required" if len(value) > maximum: return "drs_text_bound_invalid" if any( (ord(char) < 32 and char not in "\n\t") or ord(char) == 127 for char in value ): return "drs_text_bound_invalid" return _secret_reason(value)
def _tuple_reasons( value: object, *, item_reason: object, maximum_items: int, require_unique: bool = True, ) -> tuple[str, ...]: if type(value) is not tuple: return ("drs_exact_type_required",) if len(value) > maximum_items: return ("drs_tuple_bound_invalid",) reasons: list[str] = [] for item in value: reason = item_reason(item) if reason: reasons.append(reason) if require_unique and all(type(item) is str for item in value): if len(set(value)) != len(value): reasons.append("drs_tuple_duplicate_invalid") return _dedupe(reasons)
def _token_tuple_reasons( value: object, *, maximum_items: int = 64, require_unique: bool = True, ) -> tuple[str, ...]: return _tuple_reasons( value, item_reason=_token_reason, maximum_items=maximum_items, require_unique=require_unique, )
def _reference_tuple_reasons( value: object, *, maximum_items: int = 64, require_unique: bool = True, ) -> tuple[str, ...]: return _tuple_reasons( value, item_reason=_reference_reason, maximum_items=maximum_items, require_unique=require_unique, )
def _safe_text_tuple_reasons( value: object, *, maximum_items: int, maximum_chars: int, require_unique: bool = True, ) -> tuple[str, ...]: return _tuple_reasons( value, item_reason=lambda item: _bounded_text( item, maximum=maximum_chars ), maximum_items=maximum_items, require_unique=require_unique, )
def _sha256_tuple_reasons( value: object, *, maximum_items: int, require_unique: bool = True, ) -> tuple[str, ...]: return _tuple_reasons( value, item_reason=lambda item: ( None if _is_sha256(item) else "drs_sha256_invalid" ), maximum_items=maximum_items, require_unique=require_unique, )
def _typed_id_tuple_reasons( value: object, *, prefix: str, maximum_items: int, invalid_reason: str, require_unique: bool = True, ) -> tuple[str, ...]: reasons = _tuple_reasons( value, item_reason=lambda item: _typed_id_reason(item, prefix), maximum_items=maximum_items, require_unique=require_unique, ) return tuple( invalid_reason if reason == "drs_text_bound_invalid" else reason for reason in reasons )
def _field_name_tuple_reasons( value: object, *, maximum_items: int, ) -> tuple[str, ...]: return _tuple_reasons( value, item_reason=lambda item: ( None if type(item) is str and _FIELD_NAME.fullmatch(item) else ( "drs_exact_type_required" if type(item) is not str else "drs_text_bound_invalid" ) ), maximum_items=maximum_items, )
def _string_tuple_reasons( value: object, *, maximum_items: int = 64, maximum_bytes: int = 256, require_unique: bool = True, ) -> tuple[str, ...]: return _safe_text_tuple_reasons( value, maximum_items=maximum_items, maximum_chars=maximum_bytes, require_unique=require_unique, )
def _canonical_plain_value(value: object) -> object: if value is None or type(value) in (str, int, bool): return value if type(value) is tuple: return [_canonical_plain_value(item) for item in value] if type(value) is SemanticAddressV01: return [ _canonical_plain_value(getattr(value, name)) for name in _SEMANTIC_ADDRESS_FIELDS ] if type(value) is MemoryPointerV01: return [ _canonical_plain_value(getattr(value, name)) for name in _MEMORY_POINTER_FIELDS ] if type(value) is ArtifactPointerV01: return [ _canonical_plain_value(getattr(value, name)) for name in _ARTIFACT_POINTER_FIELDS ] if type(value) is LineageEdgeV01: return [ _canonical_plain_value(getattr(value, name)) for name in _LINEAGE_EDGE_FIELDS ] if type(value) is DRSAuthorityEnvelopeV01: return [ _canonical_plain_value(getattr(value, name)) for name in _AUTHORITY_ENVELOPE_FIELDS ] if type(value) is DRSTimeEnvelopeV01: return [ _canonical_plain_value(getattr(value, name)) for name in _TIME_ENVELOPE_FIELDS ] if type(value) is MeaningRecordV01: return [ _canonical_plain_value(getattr(value, name)) for name in _MEANING_RECORD_FIELDS ] raise ValueError("canonical_json_value_invalid")
def _plain_data(value: object, field_names: tuple[str, ...]) -> dict[str, object]: return { name: _plain_data_value(getattr(value, name)) for name in field_names }
def _plain_data_value(value: object) -> object: if value is None or type(value) in (str, int, bool): return value if type(value) is tuple: return [_plain_data_value(item) for item in value] if type(value) is SemanticAddressV01: return _plain_data(value, _SEMANTIC_ADDRESS_FIELDS) if type(value) is MemoryPointerV01: return _plain_data(value, _MEMORY_POINTER_FIELDS) if type(value) is ArtifactPointerV01: return _plain_data(value, _ARTIFACT_POINTER_FIELDS) if type(value) is LineageEdgeV01: return _plain_data(value, _LINEAGE_EDGE_FIELDS) if type(value) is DRSAuthorityEnvelopeV01: return _plain_data(value, _AUTHORITY_ENVELOPE_FIELDS) if type(value) is DRSTimeEnvelopeV01: return _plain_data(value, _TIME_ENVELOPE_FIELDS) if type(value) is MeaningRecordV01: return _plain_data(value, _MEANING_RECORD_FIELDS) raise ValueError("drs_exact_type_required")
def _identity( value: object, *, identity_field: str, domain: str, prefix: str, field_names: tuple[str, ...], ) -> str: material = [ _canonical_plain_value(getattr(value, name)) for name in field_names if name != identity_field ] digest = _domain_separated_sha256_hex_v01( domain=domain, payload=_canonical_json_bytes_v01(material), ) return prefix + digest
def _profile_for(type_name: str) -> tuple[str, str, str, tuple[str, ...]]: for name, identity_field, domain, prefix, field_names in _IDENTITY_PROFILES: if name == type_name: return identity_field, domain, prefix, field_names raise ValueError("drs_identity_profile_invalid")
def _finish_build( provisional: object, *, type_name: str, reasons_without_identity: tuple[str, ...], validator: object, ) -> object: if reasons_without_identity: raise ValueError(reasons_without_identity[0]) from None identity_field, domain, prefix, field_names = _profile_for(type_name) identity = _identity( provisional, identity_field=identity_field, domain=domain, prefix=prefix, field_names=field_names, ) final = _replace(provisional, **{identity_field: identity}) if not callable(validator): raise ValueError("drs_builder_invalid") from None valid, reasons = validator(final) if not valid: raise ValueError(reasons[0]) from None return final
def _id_reason( value: object, *, type_name: str, ) -> str | None: identity_field, domain, prefix, field_names = _profile_for(type_name) actual = getattr(value, identity_field) if type(actual) is not str or not actual.startswith(prefix): return "drs_identity_invalid" if len(actual) != len(prefix) + 64 or not _is_sha256(actual[len(prefix):]): return "drs_identity_invalid" expected = _identity( value, identity_field=identity_field, domain=domain, prefix=prefix, field_names=field_names, ) if actual != expected: if type_name == "MeaningRecordV01": return "drs_meaning_record_identity_invalid" if type_name in ("MemoryPointerV01", "ArtifactPointerV01"): return "drs_pointer_identity_invalid" return "drs_identity_invalid" return None
def _version_reason(value: object) -> str | None: if type(value) is not str: return "drs_exact_type_required" if value != DRS_G2B_PROFILE_VERSION_V01: return "drs_schema_version_mismatch" return None
def _semantic_address_reasons( value: object, *, check_identity: bool, ) -> tuple[str, ...]: if type(value) is not SemanticAddressV01: return ("drs_exact_type_required",) reasons: list[str] = [] reason = _version_reason(value.address_profile_version) if reason: reasons.append(reason) for item in ( value.namespace, value.domain, value.subject_class, value.intent_class, value.meaning_schema_id, value.meaning_schema_version, ): token_reason = _token_reason(item) if token_reason: reasons.append( token_reason if token_reason == "drs_secret_payload_forbidden" else "drs_address_component_invalid" ) if type(value.namespace) is str and value.namespace.lower().startswith( ("user:", "person:", "query:") ): reasons.append("drs_address_dynamic_material_forbidden") if check_identity and not reasons: reason = _id_reason(value, type_name="SemanticAddressV01") if reason: reasons.append(reason) return _dedupe(reasons)
def build_semantic_address_v01( *, namespace: str, domain: str, subject_class: str, intent_class: str, meaning_schema_id: str, meaning_schema_version: str, ) -> SemanticAddressV01: try: provisional = SemanticAddressV01( address_profile_version=SEMANTIC_ADDRESS_PROFILE_VERSION_V01, namespace=namespace, domain=domain, subject_class=subject_class, intent_class=intent_class, meaning_schema_id=meaning_schema_id, meaning_schema_version=meaning_schema_version, semantic_address_id="drsaddr_v01:" + "0" * 64, ) return _finish_build( provisional, type_name="SemanticAddressV01", reasons_without_identity=_semantic_address_reasons( provisional, check_identity=False ), validator=validate_semantic_address_v01, ) except ValueError as exc: reason = str(exc) allowed = { "drs_exact_type_required", "drs_schema_version_mismatch", "drs_address_component_invalid", "drs_address_dynamic_material_forbidden", "drs_identity_invalid", } raise ValueError(reason if reason in allowed else "drs_address_invalid") from None except Exception: raise ValueError("drs_address_invalid") from None
def validate_semantic_address_v01( value: object, ) -> tuple[bool, tuple[str, ...]]: try: reasons = _semantic_address_reasons(value, check_identity=True) return not reasons, reasons except Exception: return False, ("drs_address_invalid",)
