def _pointer_common_reasons( value: object, *, artifact: bool, check_identity: bool, ) -> tuple[str, ...]: expected_type = ArtifactPointerV01 if artifact else MemoryPointerV01 if type(value) is not expected_type: return ("drs_exact_type_required",) reasons: list[str] = [] reason = _version_reason(value.pointer_version) if reason: reasons.append(reason) allowed_storage = ( DRS_ARTIFACT_POINTER_STORAGE_CLASSES_V01 if artifact else DRS_MEMORY_POINTER_STORAGE_CLASSES_V01 ) if type(value.storage_class) is not str or value.storage_class not in allowed_storage: reasons.append("drs_pointer_storage_class_invalid") if not _is_reference(value.object_reference): reasons.append( _secret_reason(value.object_reference) if type(value.object_reference) is str and _secret_reason(value.object_reference) else "drs_pointer_reference_invalid" ) if not _is_sha256(value.content_sha256): reasons.append("drs_sha256_invalid") descriptor = value.media_type if artifact else value.record_class descriptor_reason = ( _media_type_reason(descriptor) if artifact else _token_reason(descriptor) ) if descriptor_reason: reasons.append("drs_pointer_descriptor_invalid") if value.byte_length is not None and not _is_nonnegative_int(value.byte_length): reasons.append("drs_exact_int_required") if not _is_reference(value.access_policy_id): reasons.append("drs_pointer_access_policy_denied") if type(value.sensitivity_class) is not str or value.sensitivity_class not in _SENSITIVITY_CLASSES: reasons.append("drs_pointer_sensitivity_invalid") reasons.extend(_token_tuple_reasons(value.allowed_use_classes)) reasons.extend(_token_tuple_reasons(value.forbidden_use_classes)) if ( type(value.allowed_use_classes) is tuple and type(value.forbidden_use_classes) is tuple and all(type(item) is str for item in value.allowed_use_classes) and all(type(item) is str for item in value.forbidden_use_classes) and set(value.allowed_use_classes) & set(value.forbidden_use_classes) ): reasons.append("drs_pointer_access_policy_denied") if t