str: reasons.append("drs_kernel_scope_invalid") if value.creates_authority is not False: reasons.append("drs_non_authority_law_invalid") if value.creates_permission is not False: reasons.append("drs_non_permission_law_invalid") if check_identity and not reasons: reason = _id_reason(value, type_name="MeaningRecordV01") if reason: reasons.append(reason) return _dedupe(reasons)
