def _copy_typed_tuple( value: object, item_type: type[object], *, allow_empty: bool, ) -> tuple[object, ...]: if ( type(value) is not tuple or (not allow_empty and not value) or any(type(item) is not item_type for item in value) ): raise ValueError("domain_evidence_projection_invalid") return tuple(item for item in value)
def _copy_text_tuple(value: object, *, allow_empty: bool) -> tuple[str, ...]: if not _valid_text_tuple(value, allow_empty=allow_empty): raise ValueError("evidence_duplicate_identity") return tuple(item for item in value)
def _valid_text(value: object) -> bool: if type(value) is not str or not value or value != value.strip(): return False if any( 0xD800 <= ord(character) <= 0xDFFF or _unicodedata.category(character) in ("Cc", "Cf", "Cs", "Zl", "Zp") for character in value ): return False try: value.encode("utf-8", errors="strict") except UnicodeError: return False return True
def _valid_text_tuple(value: object, *, allow_empty: bool) -> bool: return bool( type(value) is tuple and (allow_empty or value) and all(_valid_text(item) for item in value) and len(value) == len(set(value)) )
def _logical_ref_valid(value: object) -> bool: if not _valid_text(value) or type(value) is not str: return False if ( value.startswith("/") or "\\" in value or _WINDOWS_DRIVE.match(value) is not None or _unicodedata.normalize("NFC", value) != value ): return False parts = value.split("/") return all(part not in ("", ".", "..") for part in parts)
def _valid_execution_head(value: object) -> bool: return type(value) is str and _EXECUTION_HEAD.fullmatch(value) is not None
def _valid_sha256(value: object) -> bool: return type(value) is str and _LOWER_HEX_64.fullmatch(value) is not None
def _positive_int(value: object) -> bool: return type(value) is int and value >= 1
def _nonnegative_int(value: object) -> bool: return type(value) is int and value >= 0
def _has_duplicates(values: tuple[object, ...]) -> bool: return len(values) != len(set(values))
def _dedupe(errors: object) -> tuple[str, ...]: return tuple(dict.fromkeys(errors))
def _stable_projection_builder_reason(error: ValueError) -> str: allowed = ( "domain_evidence_projection_invalid", "evidence_identity_mismatch", "evidence_nested_identity_mismatch", "evidence_duplicate_identity", "evidence_reference_unresolved", "evidence_external_call_forbidden", "evidence_authority_creation_forbidden", "evidence_permission_creation_forbidden", "evidence_effect_forbidden", "evidence_status_mismatch", ) if ( type(error) is ValueError and len(error.args) == 1 and type(error.args[0]) is str and error.args[0] in allowed ): return error.args[0] return "domain_evidence_projection_invalid"

"""Pure in-memory, deterministic, domain-neutral G1-B2 Kernel contracts.

This module defines a versioned Kernel artifact envelope and field-level
causal-consumption evidence. It has no provider, LLM, network, filesystem, or
domain imports; no transition registry, Root Decision Kernel, or Effect
Firewall; and no Root decision creation, permission creation, FinalOutput
creation, or effect. Authority and lifecycle remain independent. ABI envelope
data does not itself create authority, and causal evidence does not prove
semantic truth. This is not production API stability certification.
"""

from __future__ import annotations

from collections.abc import Mapping as _Mapping
