def _affected_walk_v01( *, changed_nodes: tuple[str, ...], graph: DependencyGraphIndexV01, dependency_edges: tuple[DeltaDependencyEdgeV01, ...], positions: dict[str, int], ) -> dict[str, object]: reverse: dict[str, list[DeltaDependencyEdgeV01]] = { node_id: [] for node_id in graph.ordered_node_ids } for edge in dependency_edges: reverse[edge.dependency_artifact_id].append(edge) for rows in reverse.values(): rows.sort(key=lambda edge: edge.canonical_order) frontier = deque(changed_nodes) distance = {node_id: 0 for node_id in changed_nodes} cause: dict[str, str | None] = {node_id: None for node_id in changed_nodes} traversed_edge_count = 0 while frontier: dependency_id = frontier.popleft() for edge in reverse[dependency_id]: traversed_edge_count += 1 dependent_id = edge.dependent_artifact_id if dependent_id in distance: continue next_distance = distance[dependency_id] + 1 if next_distance > graph.max_hops: raise ValueError("g2e_affected_hop_bound_exceeded") distance[dependent_id] = next_distance cause[dependent_id] = edge.edge_id if len(distance) > graph.max_nodes: raise ValueError("g2e_affected_node_bound_exceeded") frontier.append(dependent_id) affected = tuple( sorted( (node_id for node_id, hops in distance.items() if hops > 0), key=lambda node_id: (distance[node_id], positions[node_id], node_id), ) ) direct = tuple(node_id for node_id in affected if distance[node_id] == 1) transitive = tuple(node_id for node_id in affected if distance[node_id] > 1) changed_set = set(changed_nodes) affected_set = set(affected) unaffected = tuple( node_id for node_id in graph.ordered_node_ids if node_id not in changed_set and node_id not in affected_set ) visited_rows = tuple((node_id, 0, None) for node_id in changed_nodes) + tuple( (node_id, distance[node_id], cause[node_id]) for node_id in affected ) return { "ordered_changed_node_ids": changed_nodes, "ordered_directly_affected_ids": direct, "ordered_transitively_affected_ids": transitive, "ordered_affected_ids": affected, "ordere