r, descriptor in enumerate(normalized, start=1): dependent, dependency, pointers, edge_class = descriptor replay_edge_sha256 = _source_replay_edge_sha256_v01( source_manifest_id=source_manifest_id, source_manifest_hash=manifest.manifest_hash, source_replay_id=replay.replay_id, dependent_artifact_id=dependent, dependency_artifact_id=dependency, positions=positions, ) edges.append( build_delta_dependency_edge_v01( graph_basis_sha256=graph_basis, graph_version=graph_version, dependent_artifact_id=dependent, dependency_artifact_id=dependency, dependency_field_pointers=pointers, edge_class=edge_class, transaction_id=transaction_id, owning_root_id=owning_root_id, domain_id=domain_id, canonical_order=canonical_order, source_replay_edge_sha256=replay_edge_sha256, trace_refs=( source_manifest_id, manifest.manifest_hash, replay.replay_id, ), ) ) return graph_basis, tuple(edges)
def compute_affected_set_v01( *, request: AffectedSetRequestV01, delta: WorldStateDeltaV01, graph: DependencyGraphIndexV01, source_bindings: tuple[DeltaSourceBindingV01, ...], changed_field_bindings: tuple[ChangedFieldBindingV01, ...], changed_artifact_bindings: tuple[ChangedArtifactBindingV01, ...], dependency_edges: tuple[DeltaDependencyEdgeV01, ...], baseline_source_artifacts: tuple[KernelArtifactV01, ...], observed_source_artifacts: tuple[KernelArtifactV01, ...], ) -> AffectedSetResultV01: changed_nodes, positions = _carrier_context_v01( request=request, delta=delta, graph=graph, source_bindings=source_bindings, changed_field_bindings=changed_field_bindings, changed_artifact_bindings=changed_artifact_bindings, dependency_edges=dependency_edges, baseline_source_artifacts=baseline_source_artifacts, observed_source_artifacts=observed_source_artifacts, ) walk = _affected_walk_v01( changed_nodes=changed_nodes, graph=graph, dependency_edges=dependency_edges, positions=positions, ) return _build_affected_set_result_internal_v01( affected_request_id=request.affected_request_id, delta_id=delta.delta_id, graph_id=graph.graph_id, graph_version=graph.graph_version, graph_basis_sha256=graph.graph_basis_sha256, ordered_changed_node_ids=walk["ordered_changed_node_ids"], ordered_directly_affected_ids=walk["ordered_directly_affected_ids"], ordered_transitively_affected_ids=walk[ "ordered_transitively_affected_ids" ], ordered_affected_ids=walk["ordered_affected_ids"], ordered_unaffected_ids=walk["ordered_unaffected_ids"], visited_rows=walk["visited_rows"], traversed_edge_count=walk["traversed_edge_count"], maximum_observed_hops=walk["maximum_observed_hops"], trace_refs=request.trace_refs, )
