def _invalidation_record_errors_v01(value: object) -> tuple[str, ...]: if type(value) is not ArtifactInvalidationRecordV01: return ("g2e_invalidation_record_invalid",) errors: list[str] = [] if ( not _prefixed_identity_valid( value.affected_set_id, "g2e_affected_set_result_v01:" ) or not _text_valid(value.artifact_id) or not _text_valid(value.artifact_type) or not _prefixed_identity_valid( value.triggering_delta_id, "g2e_world_state_delta_v01:" ) or not _text_tuple_valid( value.triggering_binding_ids, minimum=1, maximum=MAX_CHANGED_BINDINGS_V01 ) or not _text_tuple_valid(value.trace_refs, minimum=1) or type(value.root_review_required) is not bool ): errors.append("g2e_invalidation_record_invalid") if value.invalidation_reason_class not in G2E_INVALIDATION_REASON_CLASSES_V01: errors.append("g2e_invalidation_reason_invalid") if value.deleted is not False: errors.append("g2e_invalidation_deletion_forbidden") if value.historical_artifact_preserved is not True: errors.append("g2e_invalidation_history_mutation") if value.predecessor_artifact_id != value.artifact_id: errors.append("g2e_invalidation_predecessor_mismatch") if value.superseded_by_artifact_id is not None: errors.append("g2e_invalidation_supersession_mismatch") if ( value.current_eligible_before is not True or value.current_eligible_after is not False or value.g2a_packet_relation not in G2E_G2A_PACKET_RELATIONS_V01 or value.g2b_reuse_relation not in G2E_G2B_REUSE_RELATIONS_V01 or value.g2c_route_relation not in G2E_G2C_ROUTE_RELATIONS_V01 ): errors.append("g2e_invalidation_record_invalid") expected_root_review = bool( value.g2a_packet_relation == "PACKET_ROOT_REVIEW_REQUIRED" or value.g2b_reuse_relation == "REUSE_CERTIFICATE_STALE" or value.g2c_route_relation == "ROUTE_REVALIDATION_REQUIRED" ) if value.root_review_required is not expected_root_review: errors.append("g2e_invalidation_record_invalid") if _identity_errors(value): errors.append("g2e_invalidation_history_mutation") return _ordered_reasons(errors)
