def _g2e4_root_review_v01( *, phase: str, request_id: str, candidate_id: str, candidate_plain: dict[str, object], transaction_id: str, target_root_id: str, topology_ref: str, evidence_refs: tuple[str, ...], validator_ids: tuple[str, ...], policy_id: str, time_source_artifact: KernelArtifactV01, root_kernel: RootDecisionKernelV01, artifact_parent_refs: tuple[str, ...], artifact_trace_refs: tuple[str, ...], prior_root_state: dict[str, object], requested_outcome: str = "ACCEPT", ) -> dict[str, object]: if phase not in {"PLAN", "FINAL"} or requested_outcome not in { "ACCEPT", "BLOCKED_FAIL_CLOSED", "NEEDS_USER", "NEEDS_MORE_EVIDENCE", "DEFER", "REJECT", "NO_UPDATE", }: raise ValueError("g2e_root_pair_invalid") if not evidence_refs: raise ValueError("g2e_root_pair_invalid") subject = ( "selective_recomputation_plan" if phase == "PLAN" else "selective_recomputation_result" ) evidence_ids = tuple( _g2e4_derived_id_v01( "g2e_semantic_evidence_v01:", "HEDGEHOG_G2E_SEMANTIC_EVIDENCE_V01", {"phase": phase, "candidate_id": candidate_id, "ref": ref}, ) for ref in evidence_refs ) bindings = tuple( semantic_work.build_evidence_binding_v01( evidence_id=evidence_id, evidence_ref=ref, evidence_class=f"G2E_{phase}_EVIDENCE", source_component_id="continuous_delta_runtime_v01", provenance_ref=time_source_artifact.artifact_id, evidence_state=( "MISSING" if requested_outcome == "NEEDS_MORE_EVIDENCE" and index == 0 else "PRESENT" ), ) for index, (evidence_id, ref) in enumerate( zip(evidence_ids, evidence_refs, strict=True) ) ) request = semantic_work.build_semantic_work_request_v01( request_id=request_id, transaction_id=transaction_id, target_root_id=target_root_id, runtime_topology_ref=topology_ref, bounded_context_refs=evidence_refs, permitted_actor_ids=("deterministic_runtime",), permitted_contribution_modes=("DETERMINISTIC",), requested_subjects=(subject,), required_evidence_classes=(f"G2E_{phase}_EVIDENCE",), forbidden_claims=( "AUTHORITY", "PERMISSION", "ACTION_COMMIT_PACKET", "RECEI