g in contribution.constraint_bindings: errors.extend(_constraint_errors(binding)) if type(contribution.uncertainty_bindings) is tuple: for binding in contribution.uncertainty_bindings: errors.extend(_uncertainty_errors(binding)) if not _valid_text_tuple(contribution.requested_validators, allow_empty=True): errors.append("requested_validator_invalid") if not _valid_text_tuple( contribution.forbidden_claims_observed, allow_empty=True ): errors.append("actor_contribution_invalid") if contribution.forbidden_claims_observed: errors.append("forbidden_claim_observed") if type(contribution.evidence_bindings) is tuple: evidence_ids = tuple(item.evidence_id for item in contribution.evidence_bindings) if len(evidence_ids) != len(set(evidence_ids)): errors.append("evidence_binding_invalid") evidence_by_id = { item.evidence_id: item for item in contribution.evidence_bindings } if type(contribution.claims) is tuple: for claim in contribution.claims: if type(claim) is not NormalizedClaimV01: continue for evidence_id in claim.evidence_refs: binding = evidence_by_id.get(evidence_id) if binding is None or binding.evidence_state == EVIDENCE_STATE_REJECTED: errors.append("evidence_ref_unbound") for values, reason in ( (contribution.constraint_bindings, "constraint_binding_invalid"), (contribution.uncertainty_bindings, "uncertainty_binding_invalid"), ): if type(values) is tuple: ids = tuple( item.constraint_id if type(item) is ConstraintBindingV01 else item.uncertainty_id for item in values ) if len(ids) != len(set(ids)): errors.append(reason) if type(contribution.uncertainty_bindings) is tuple and type( contribution.claims ) is tuple: claim_ids = {item.claim_id for item in contribution.claims} if any( item.claim_id not in claim_ids for item in contribution.uncertainty_bindings if type(item) is UncertaintyBindingV01 ): errors.append("uncertainty_claim_ref_invalid") return tuple(dict.fromkeys(errors))
