_EXPECTED_IDS = tuple(row[0] for row in _PROFILE_ROWS) _EXPECTED_BY_ID = _MappingProxyType({row[0]: row for row in _PROFILE_ROWS})
def build_default_component_trust_profiles_v01( ) -> tuple[ComponentTrustProfileV01, ...]: return tuple(ComponentTrustProfileV01(*row) for row in _PROFILE_ROWS)
def validate_component_trust_profiles_v01( *, profiles: object, ) -> tuple[str, ...]: try: return _validate_profiles(profiles) except Exception: return ("trust_profile_contract_invalid",)
def component_trust_profile_to_plain_dict_v01( profile: ComponentTrustProfileV01, ) -> dict[str, object]: try: if _profile_errors(profile): raise ValueError("trust_profile_contract_invalid") expected = _EXPECTED_BY_ID.get(profile.component_id) if expected is None or profile != ComponentTrustProfileV01(*expected): raise ValueError("trust_profile_contract_invalid") projected = _profile_plain(profile) _canonical_json_bytes_v01(projected) return projected except Exception: raise ValueError("trust_profile_contract_invalid") from None
