def _exhaust_task(host, task_id, reason): ledger = _ledger(host, task_id) host._tasks[task_id] = replace(ledger, outcome='EXHAUSTED', reason=reason) host._revision += 1 host._events.append(('TASK_EXHAUSTED', host.state_revision, task_id, reason))
def _task_outcome(host, task_id): ledger = _ledger(host, task_id) current = ledger.revisions[-1] return WorkContinuationOutcomeV01(current.program, current.results, inspect_work_task_v01(host, task_id=task_id), ledger.outcome, ledger.reason)
def inspect_work_task_history_v01(context): ledger = _current_context(context) return tuple((r.program, r.results, r.artifact, r.trigger) for r in ledger.revisions)
def inspect_work_task_review_v01(context, *, obligation_id): """Original observed CONTROL evidence, not approval of the current work.""" ledger = _current_context(context) result = next((r for r in ledger.reviews if r[0].obligation_id == obligation_id), None) _require(result is not None, 'work_task_review_not_observed') return result
