ld.bsep_ref, semantic_proposal_ref=old.semantic_proposal_ref, catalogue_revision=trigger.resolution.membership_epoch if missing_trigger else old.catalogue_revision, budget=budget, items=items, trigger_evidence_refs=(trigger.trigger_id,), catalogue=catalogue, source_context=source_context, semantic_proposal=semantic_proposal, continuation_context=replace(context, trigger=trigger)) program = materialize_work_program_v01(candidate, catalogue=catalogue, source_context=source_context, semantic_proposal=semantic_proposal, continuation_context=replace(context, trigger=trigger)) if not missing_trigger: _require(any(type(b.source) is WorkHistoricalOutputV01 and b.source == trigger.output for i in items for b in i.inputs), 'work_task_trigger_not_consumed') usage = replace(ledger.usage, revisions=ledger.usage.revisions + 1) context.host._tasks[old.task_id] = replace(ledger, usage=usage, outcome='ACTIVE', reason=None, revisions=(*ledger.revisions, _TaskRevision(program, source_context, semantic_proposal, trigger, (), None, usage, catalogue))) context.host._revision += 1 return _task_outcome(context.host, old.task_id)
