def advance_work_program_v01(program, *, catalogue, source_context, semantic_proposal, host_map, results=(), review_bindings=(), action_authorizers=None, continuation_context=None): kwargs = dict(catalogue=catalogue, source_context=source_context, semantic_proposal=semantic_proposal, host_map=host_map, results=results, review_bindings=review_bindings, action_authorizers=action_authorizers) if continuation_context is None: _require(not any(type(h) is hosts.RootWorkExecutionHostV01 and h._task_policies for h in host_map.values()), 'work_task_context_required') return _advance_work_program_v01(program, **kwargs) _require(type(continuation_context) is WorkContinuationContextV01, 'work_task_context_type') host = continuation_context.host with host._lock: ledger = _current_context(continuation_context) task_id = ledger.policy.task_id _require(program == ledger.revisions[-1].program and host_map == {host.owning_root_id: host}, 'work_task_current_program') _require(results == ledger.revisions[-1].results, 'work_task_history_omitted') if ledger.outcome == 'EXHAUSTED': return _task_outcome(host, task_id) for item in program.candidate.items: if item.review_obligation_id is not None: _require(any(o.obligation_id == item.review_obligation_id and (o, s, b) in review_bindings for o, s, b in ledger.reviews), 'work_task_review_not_observed') before = (host.state_revision, ledger) try: output = _advance_work_program_v01(program, **kwargs, continuation_context=continuation_context) ledger = _ledger(host, task_id) current = ledger.revisions[-1] artifact = work_program_result_to_artifact_v01(program, output, catalogue=catalogue, host_map=host_map, source_context=source_context, semantic_proposal=semantic_proposal, review_bindings=review_bindings, continuation_context=continuation_context) status = 'COMPLETED' if all(r.status in ('COMPLETED', 'SKIPPED_GUARD_FALSE') for r in output) else ( 'NEEDS_CAPABILITY' if any(r.status == 'NEEDS_CAPABILITY' for r in output) else 'ACTIVE') host._tasks