@dataclass(frozen=True) class DRSResolveTableRowV02: record_id: str record_kind: str freshness_class: str reuse_decision_class: str direct_reuse_allowed: bool context_only: bool root_review_required: bool reason_codes: tuple[str, ...] lineage_ref_count: int source_ref_count: int provenance_ref_count: int
@dataclass(frozen=True) class DRSReuseDecisionReportV02: report_id: str query_id: str resolver_mode: str temporal_query_present: bool records_evaluated_count: int rows: tuple[DRSResolveTableRowV02, ...] decisions: tuple[DRSReuseDecision, ...] freshness_table: tuple[dict[str, object], ...] lineage_table: tuple[dict[str, object], ...] provenance_table: tuple[dict[str, object], ...] reuse_decision_table: tuple[dict[str, object], ...] direct_reuse_allowed_count: int direct_reuse_candidate_count: int context_only_count: int warning_only_count: int rerun_required_count: int blocked_count: int root_review_required_count: int production_ready_claimed: bool = False public_auditor_ready_claimed: bool = False real_world_effects_count: int = 0
def _non_empty_string(value: object) -> bool: return isinstance(value, str) and bool(value.strip())
def _append_reason(reasons: list[str], reason: str) -> None: if reason not in reasons: reasons.append(reason)
def _with_boundary_reasons(record: DRSRecordV02, reasons: list[str]) -> None: if record.lineage_refs: _append_reason(reasons, REASON_LINEAGE_REFS_PRESERVED) if record.provenance_refs: _append_reason(reasons, REASON_PROVENANCE_REFS_PRESERVED) _append_reason(reasons, REASON_CONTEXT_ONLY_NOT_AUTHORITY)
def _with_advisory_score_reasons( record: DRSRecordV02, reasons: list[str], tau_reuse: float, ) -> None: if record.reuse_score >= tau_reuse: _append_reason(reasons, REASON_REUSE_SCORE_NOT_ROOT) if record.semantic_similarity_score is not None: _append_reason(reasons, REASON_SEMANTIC_SIMILARITY_NOT_AUTHORITY)
def _has_conflicting_provenance(record: DRSRecordV02) -> bool: provenance_fragments = record.provenance_refs + record.source_refs return record.conflicting_provenance or any( "conflict" in fragment or "contradict" in fragment for fragment in provenance_fragments )
def validate_freshness_envelope( envelope: DRSFreshnessEnvelope | None, ) -> tuple[bool, tuple[str, ...]]: if envelope is None: return False, (REASON_MISSING_TIME_ENVELOPE,)
reasons: list[str] = [] invalid_required_time = not ( _non_empty_string(envelope.physical_time) and _non_empty_string(envelope.knowledge_time) and _non_empty_string(envelope.event_time) and _non_empty_string(envelope.context_time) ) if invalid_required_time: reasons.append(REASON_MISSING_TIME_ENVELOPE) invalid_ttl = not ( envelope.ttl_seconds is None or (isinstance(envelope.ttl_seconds, int) and envelope.ttl_seconds >= 0) ) if invalid_ttl: reasons.append(REASON_INVALID_TTL_SECONDS) if reasons: return False, tuple(reasons) return True, ()
def validate_temporal_query( query: TemporalQueryV02 | None, ) -> tuple[bool, tuple[str, ...]]: if query is None: return False, (REASON_MISSING_TEMPORAL_QUERY,) if not ( _non_empty_string(query.query_id) and _non_empty_string(query.as_of) and _non_empty_string(query.context_time) ): return False, (REASON_MISSING_TEMPORAL_QUERY,) return True, ()
def _freshness_class(record: DRSRecordV02) -> str: if record.time_envelope is None: return FRESHNESS_BLOCKED_BY_POLICY_OR_CONFLICT return record.time_envelope.freshness_class
def _claims_boundary(record: DRSRecordV02) -> bool: return any( ( record.truth_claimed, record.authority_claimed, record.action_permission_claimed, record.final_output_claimed, record.contains_action_permission, ) )
def _hard_gates_allow_direct_reuse( record: DRSRecordV02, query: TemporalQueryV02, *, tau_reuse: float, ) -> bool: return ( query.allow_direct_reuse_if_all_gates_pass and record.root_shortcut_allowed and record.policy_ok and record.permission_ok and record.reuse_score >= tau_reuse and _freshness_class(record) == FRESHNESS_FRESH_CONTEXT and not record.changed_facts and not record.conflict_pressure and not _has_conflicting_provenance(record) and not record.duplicate_poisoning_pressure and not record.wrong_domain_near_match and not record.quarantine_proximity and not record.deadend_proximity and not record.contains_receipt and not record.accepted_evidence and record.root_final_ref is None and not _claims_boundary(record) )
def _candidate_shape(record: DRSRecordV02, tau_reuse: float) -> bool: return record.policy_ok and record.reuse_score >= tau_reuse and not ( record.changed_facts or record.conflict_pressure or _has_conflicting_provenance(record) or record.duplicate_poisoning_pressure or record.wrong_domain_near_match or record.quarantine_proximity or record.deadend_proximity or _freshness_class(record) in _STALE_FRESHNESS_CLASSES or _claims_boundary(record) )
def _make_decision( record: DRSRecordV02, *, decision_class: str, direct_reuse_allowed: bool, reason_codes: Iterable[str], query: TemporalQueryV02 | None, ) -> DRSReuseDecision: root_review_required = True if query is None else ( query.require_root_review or not direct_reuse_allowed ) reasons = list(reason_codes) if root_review_required: _append_reason(reasons, REASON_ROOT_REVIEW_REQUIRED) return DRSReuseDecision( record_id=record.record_id, reuse_decision_class=decision_class, freshness_class=_freshness_class(record), direct_reuse_allowed=direct_reuse_allowed, context_only=decision_class == REUSE_CONTEXT_ONLY, root_review_required=root_review_required, reason_codes=tuple(reasons), lineage_refs=record.lineage_refs, source_refs=record.source_refs, provenance_refs=record.provenance_refs, authority_claimed=False, truth_claimed=False, action_permission_claimed=False, final_output_claimed=False, )
def evaluate_drs_record_v02( record: DRSRecordV02, query: TemporalQueryV02 | None, *, tau_reuse: float = 0.92, ) -> DRSReuseDecision: query_valid, query_reasons = validate_temporal_query(query) envelope_valid, envelope_reasons = validate_freshness_envelope(record.time_envelope) reasons: list[str] = [] _with_boundary_reasons(record, reasons) _with_advisory_score_reasons(record, reasons, tau_reuse)
if not query_valid: reasons.extend(query_reasons) return _make_decision( record, decision_class=REUSE_BLOCKED, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
if not envelope_valid: reasons.extend(envelope_reasons) return _make_decision( record, decision_class=REUSE_BLOCKED, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
if record.contains_action_permission: _append_reason(reasons, REASON_PERMISSION_TRACE_NOT_COMPLETED_ACTION)
if _claims_boundary(record): return _make_decision( record, decision_class=REUSE_BLOCKED, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
if record.contains_receipt: _append_reason(reasons, REASON_OLD_RECEIPT_NOT_PERMISSION) if record.root_final_ref is not None: _append_reason(reasons, REASON_PRIOR_ROOT_FINAL_NOT_SILENT_REUSE) if record.accepted_evidence: _append_reason(reasons, REASON_ACCEPTED_EVIDENCE_NOT_FUTURE_ACTION_PERMISSION)
if record.duplicate_poisoning_pressure: _append_reason( reasons, REASON_DUPLICATE_POISONING_PRESSURE_DOES_NOT_CREATE_AUTHORITY, ) return _make_decision( record, decision_class=REUSE_BLOCKED, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
if record.wrong_domain_near_match: _append_reason(reasons, REASON_WRONG_DOMAIN_NEAR_MATCH_NOT_DIRECT_REUSE) return _make_decision( record, decision_class=REUSE_RERUN_REQUIRED, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
if record.quarantine_proximity: _append_reason(reasons, REASON_QUARANTINE_PROXIMITY_BLOCKS_DIRECT_REUSE) return _make_decision( record, decision_class=REUSE_BLOCKED, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
if record.deadend_proximity: _append_reason(reasons, REASON_DEADEND_PROXIMITY_BLOCKS_OR_DOWNGRADES_REUSE) return _make_decision( record, decision_class=REUSE_BLOCKED, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
if record.changed_facts: _append_reason(reasons, REASON_CHANGED_FACTS_REQUIRE_RERUN_VALIDATION) return _make_decision( record, decision_class=REUSE_RERUN_REQUIRED, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
if record.conflict_pressure or _has_conflicting_provenance(record): _append_reason(reasons, REASON_CONFLICT_REQUIRES_RERUN_VALIDATION) if _has_conflicting_provenance(record): _append_reason(reasons, REASON_CONFLICTING_PROVENANCE_BLOCKS_REUSE) return _make_decision( record, decision_class=REUSE_RERUN_REQUIRED, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
freshness_class = _freshness_class(record) if freshness_class == FRESHNESS_STALE_WARNING: _append_reason(reasons, REASON_STALE_RECORD_NOT_PERMISSION) return _make_decision( record, decision_class=REUSE_WARNING_ONLY, direct_reuse_allowed=False, reason_codes=reasons, query=query, ) if freshness_class in { FRESHNESS_EXPIRED_RERUN_REQUIRED, FRESHNESS_CHANGED_FACT_RERUN_REQUIRED, }: _append_reason(reasons, REASON_STALE_RECORD_NOT_PERMISSION) return _make_decision( record, decision_class=REUSE_RERUN_REQUIRED, direct_reuse_allowed=False, reason_codes=reasons, query=query, ) if freshness_class == FRESHNESS_BLOCKED_BY_POLICY_OR_CONFLICT: _append_reason(reasons, REASON_STALE_RECORD_NOT_PERMISSION) return _make_decision( record, decision_class=REUSE_BLOCKED, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
if ( record.contains_receipt or record.root_final_ref is not None or record.accepted_evidence ): return _make_decision( record, decision_class=REUSE_CONTEXT_ONLY, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
if query is not None and _hard_gates_allow_direct_reuse( record, query, tau_reuse=tau_reuse, ): return _make_decision( record, decision_class=REUSE_DIRECT_REUSE_ALLOWED, direct_reuse_allowed=True, reason_codes=reasons, query=query, )
if _candidate_shape(record, tau_reuse): _append_reason(reasons, REASON_DIRECT_REUSE_DEFAULT_FALSE) return _make_decision( record, decision_class=REUSE_DIRECT_REUSE_CANDIDATE, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
return _make_decision( record, decision_class=REUSE_CONTEXT_ONLY, direct_reuse_allowed=False, reason_codes=reasons, query=query, )
def build_drs_resolve_report_v02( query: TemporalQueryV02 | None, records: tuple[DRSRecordV02, ...] | list[DRSRecordV02], ) -> DRSResolveReport: decisions = tuple(evaluate_drs_record_v02(record, query) for record in records) return DRSResolveReport( query_id=query.query_id if query is not None else "", temporal_query_present=validate_temporal_query(query)[0], records_evaluated_count=len(records), decisions=decisions, direct_reuse_allowed_count=sum( 1 for decision in decisions if decision.direct_reuse_allowed ), context_only_count=sum(1 for decision in decisions if decision.context_only), root_review_required_count=sum( 1 for decision in decisions if decision.root_review_required ), lineage_refs_preserved_count=sum( 1 for decision in decisions if decision.lineage_refs ), production_ready_claimed=False, public_auditor_ready_claimed=False, real_world_effects_count=0, )
def _row_for_decision( record: DRSRecordV02, decision: DRSReuseDecision, ) -> DRSResolveTableRowV02: return DRSResolveTableRowV02( record_id=record.record_id, record_kind=record.record_kind, freshness_class=decision.freshness_class, reuse_decision_class=decision.reuse_decision_class, direct_reuse_allowed=decision.direct_reuse_allowed, context_only=decision.context_only, root_review_required=decision.root_review_required, reason_codes=decision.reason_codes, lineage_ref_count=len(record.lineage_refs), source_ref_count=len(record.source_refs), provenance_ref_count=len(record.provenance_refs), )
def _freshness_row(record: DRSRecordV02, decision: DRSReuseDecision) -> dict[str, object]: envelope = record.time_envelope return { "record_id": record.record_id, "freshness_class": decision.freshness_class, "has_time_envelope": envelope is not None, "physical_time": envelope.physical_time if envelope else None, "knowledge_time": envelope.knowledge_time if envelope else None, "event_time": envelope.event_time if envelope else None, "context_time": envelope.context_time if envelope else None, "ttl_seconds": envelope.ttl_seconds if envelope else None, }
def _lineage_rows(record: DRSRecordV02) -> tuple[dict[str, object], ...]: return tuple( { "record_id": record.record_id, "ref_id": ref.ref_id, "ref_kind": ref.ref_kind, "relation": ref.relation, "source_observed_at": ref.source_observed_at, "system_ingested_at": ref.system_ingested_at, "notes": ref.notes, } for ref in record.lineage_refs )
def _provenance_row(record: DRSRecordV02) -> dict[str, object]: return { "record_id": record.record_id, "source_refs": record.source_refs, "provenance_refs": record.provenance_refs, "prior_trace_ref": record.prior_trace_ref, "root_final_ref": record.root_final_ref, "artifact_refs": record.artifact_refs, "validation_refs": record.validation_refs, }
def _reuse_decision_row(decision: DRSReuseDecision) -> dict[str, object]: return { "record_id": decision.record_id, "reuse_decision_class": decision.reuse_decision_class, "direct_reuse_allowed": decision.direct_reuse_allowed, "context_only": decision.context_only, "root_review_required": decision.root_review_required, "reason_codes": decision.reason_codes, "truth_claimed": decision.truth_claimed, "authority_claimed": decision.authority_claimed, "action_permission_claimed": decision.action_permission_claimed, "final_output_claimed": decision.final_output_claimed, }
def resolve_drs_records_v02( input: LocalDRSResolveInputV02, ) -> DRSReuseDecisionReportV02: decisions = tuple( evaluate_drs_record_v02(record, input.temporal_query) for record in input.records ) rows = tuple( _row_for_decision(record, decision) for record, decision in zip(input.records, decisions, strict=True) ) lineage_table = tuple( row for record in input.records for row in _lineage_rows(record) ) return DRSReuseDecisionReportV02( report_id="local_drs_v0_2_reuse_decision_report", query_id=input.temporal_query.query_id if input.temporal_query else "", resolver_mode=input.resolver_mode, temporal_query_present=validate_temporal_query(input.temporal_query)[0], records_evaluated_count=len(input.records), rows=rows, decisions=decisions, freshness_table=tuple( _freshness_row(record, decision) for record, decision in zip(input.records, decisions, strict=True) ), lineage_table=lineage_table, provenance_table=tuple(_provenance_row(record) for record in input.records), reuse_decision_table=tuple(_reuse_decision_row(decision) for decision in decisions), direct_reuse_allowed_count=sum( 1 for decision in decisions if decision.direct_reuse_allowed ), direct_reuse_candidate_count=sum( 1 for decision in decisions if decision.reuse_decision_class == REUSE_DIRECT_REUSE_CANDIDATE ), context_only_count=sum( 1 for decision in decisions if decision.reuse_decision_class == REUSE_CONTEXT_ONLY ), warning_only_count=sum( 1 for decision in decisions if decision.reuse_decision_class == REUSE_WARNING_ONLY ), rerun_required_count=sum( 1 for decision in decisions if decision.reuse_decision_class == REUSE_RERUN_REQUIRED ), blocked_count=sum( 1 for decision in decisions if decision.reuse_decision_class == REUSE_BLOCKED ), root_review_required_count=sum( 1 for decision in decisions if decision.root_review_required ), production_ready_claimed=False, public_auditor_ready_claimed=False, real_world_effects_count=0, )
def _wow_time( freshness_class: str = FRESHNESS_FRESH_CONTEXT, ) -> DRSFreshnessEnvelope: return DRSFreshnessEnvelope( physical_time="2026-07-06T17:00:24Z", knowledge_time="2026-07-06T17:00:24Z", event_time="2026-07-06T17:00:24Z", context_time="full_wow_v1_2", ttl_seconds=3600, validity_start="2026-07-06T17:00:24Z", validity_end="2026-07-06T18:00:24Z", source_observed_at="2026-07-06T17:00:24Z", system_ingested_at="2026-07-06T17:00:25Z", freshness_class=freshness_class, )
def _wow_lineage(record_id: str, relation: str) -> tuple[DRSLineageRef, ...]: return ( DRSLineageRef( ref_id=f"full_wow_v1_2:{record_id}", ref_kind="full_wow_v1_2_trace", relation=relation, source_observed_at="2026-07-06T17:00:24Z", system_ingested_at="2026-07-06T17:00:25Z", notes=("local proof-level WOW v1.2 regression record",), ), )
def _wow_record( *, record_id: str, record_kind: str, summary: str, relation: str, freshness_class: str = FRESHNESS_FRESH_CONTEXT, **overrides: object, ) -> DRSRecordV02: values = { "record_id": record_id, "record_kind": record_kind, "summary": summary, "time_envelope": _wow_time(freshness_class), "lineage_refs": _wow_lineage(record_id, relation), "source_refs": (f"source:{record_id}",), "provenance_refs": ("audit:full_wow_v1_2",), "prior_trace_ref": "full_wow_v1_2_manual_live_multillm_fractal_real_run", "artifact_refs": (f"artifact:{record_id}",), "validation_refs": (f"validation:{record_id}",), } values.update(overrides) return DRSRecordV02(**values)
def build_wow_v1_2_drs_v02_regression_records() -> tuple[DRSRecordV02, ...]: return ( _wow_record( record_id="supplier_a_prior_scoped_trace", record_kind="supplier_a_prior_scoped_trace", summary="Supplier A prior scoped trace may inform context only.", relation="supports_context", accepted_evidence=True, reuse_score=0.88, ), _wow_record( record_id="supplier_b_blocker_trace", record_kind="supplier_b_blocker_trace", summary="Supplier B blocker trace warns against reuse.", relation="warns_against", conflict_pressure=True, reuse_score=0.1, ), _wow_record( record_id="old_receipt_trace", record_kind="old_receipt_trace", summary="Old receipt trace remains evidence only.", relation="evidence_only", contains_receipt=True, reuse_score=0.95, ), _wow_record( record_id="old_shipment_held_trace", record_kind="old_shipment_held_trace", summary="Old shipment-held trace warns that shipment remains held.", relation="warns_against", freshness_class=FRESHNESS_STALE_WARNING, reuse_score=0.7, ), _wow_record( record_id="old_root_final_trace", record_kind="old_root_final_trace", summary="Old Root Final trace is lineage/provenance only.", relation="root_final_lineage", root_final_ref="root-final:full_wow_v1_2", reuse_score=0.96, ), _wow_record( record_id="changed_warehouse_fact", record_kind="changed_warehouse_fact", summary="Changed warehouse fact requires rerun validation.", relation="requires_rerun", changed_facts=True, reuse_score=0.2, ), _wow_record( record_id="stale_legal_accounting_evidence", record_kind="stale_legal_accounting_evidence", summary="Stale legal/accounting evidence gets freshness downgrade.", relation="stale_warning", freshness_class=FRESHNESS_STALE_WARNING, reuse_score=0.97, semantic_similarity_score=0.98, ), _wow_record( record_id="quarantined_record", record_kind="quarantined_record", summary="Quarantine proximity blocks direct reuse.", relation="blocked_by_quarantine", quarantine_proximity=True, reuse_score=0.99, ), _wow_record( record_id="deadend_record", record_kind="deadend_record", summary="Deadend proximity blocks or downgrades reuse.", relation="blocked_by_deadend", deadend_proximity=True, reuse_score=0.99, ), _wow_record( record_id="wrong_domain_near_match", record_kind="wrong_domain_near_match", summary="Wrong-domain near match cannot be reused directly.", relation="conflicts_with_scope", wrong_domain_near_match=True, semantic_similarity_score=0.99, reuse_score=0.97, ), _wow_record( record_id="permission_trace_completed_action_attempt", record_kind="permission_trace_completed_action_attempt", summary="Permission trace cannot become completed action.", relation="blocked_permission_trace", contains_action_permission=True, reuse_score=0.99, ), )

from __future__ import annotations

import json
import re
from copy import deepcopy
from datetime import datetime, timedelta
from functools import lru_cache
from pathlib import Path

import jsonschema

from hedgehog.time_model import utc_now_iso


ROOT = Path(__file__).resolve().parents[1]
SCHEMAS_DIR = ROOT / "schemas"

REQUIRED_RESULT_PROPOSAL_FIELDS = {
    "proposal_id",
    "producer",
    "vector_id",
    "plan_id",
    "result_payload",
    "evidence",
    "cost",
    "risks",
    "time_envelope",
    "trace_refs",
}

REQUIRED_TIME_ENVELOPE_FIELDS = {
    "pt_created_at",
    "kt_asof",
    "ct_session_anchor",
    "ttl_seconds",
}

FORBIDDEN_KEYS = {"final_output", "answer", "raw_user_text"}
_CANONICAL_UTC_SECOND_RE_V02 = re.compile(
    r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\+00:00"
)


def _resolve_post_vv_checked_at_v02(checked_at: str | None) -> str | None:
    if checked_at is None:
        return None
    if (
        type(checked_at) is not str
        or _CANONICAL_UTC_SECOND_RE_V02.fullmatch(checked_at) is None
    ):
        raise ValueError("post_vv_checked_at_invalid")
    try:
        parsed = datetime.fromisoformat(checked_at)
    except ValueError:
        raise ValueError("post_vv_checked_at_invalid") from None
    if (
        parsed.utcoffset() != timedelta(0)
        or parsed.microsecond != 0
        or parsed.isoformat(timespec="seconds") != checked_at
    ):
        raise ValueError("post_vv_checked_at_invalid")
    return checked_at


def _load_schema(name: str) -> dict:
    with (SCHEMAS_DIR / name).open("r", encoding="utf-8") as handle:
        return json.load(handle)


@lru_cache(maxsize=1)
def _result_proposal_validator() -> jsonschema.Draft202012Validator:
    common_schema = _load_schema("common.schema.json")
    time_envelope_schema = _load_schema("time_envelope.schema.json")
    result_proposal_schema = _load_schema("result_proposal.schema.json")
    store = {
        common_schema["$id"]: common_schema,
        "common.schema.json": common_schema,
        "https://hedgehog-os.local/schemas/common.schema.json": common_schema,
        time_envelope_schema["$id"]: time_envelope_schema,
        "time_envelope.schema.json": time_envelope_schema,
        "https://hedgehog-os.local/schemas/time_envelope.schema.json": time_envelope_schema,
        result_proposal_schema["$id"]: result_proposal_schema,
    }
    resolver = jsonschema.RefResolver.from_schema(result_proposal_schema, store=store)
    return jsonschema.Draft202012Validator(
        result_proposal_schema,
        resolver=resolver,
    )


@lru_cache(maxsize=1)
def _vv_report_validator() -> jsonschema.Draft202012Validator:
    common_schema = _load_schema("common.schema.json")
    vv_report_schema = _load_schema("vv_report.schema.json")
    store = {
        common_schema["$id"]: common_schema,
        "common.schema.json": common_schema,
        "https://hedgehog-os.local/schemas/common.schema.json": common_schema,
        vv_report_schema["$id"]: vv_report_schema,
    }
    resolver = jsonschema.RefResolver.from_schema(vv_report_schema, store=store)
    return jsonschema.Draft202012Validator(
        vv_report_schema,
        resolver=resolver,
    )


def _schema_error_location(error: jsonschema.ValidationError) -> str:
    if not error.absolute_path:
        return "$"
    return ".".join(str(part) for part in error.absolute_path)


def _result_proposal_schema_violations(candidate) -> list[dict]:
    validator = _result_proposal_validator()
    errors = sorted(
        validator.iter_errors(candidate),
        key=lambda error: (list(error.absolute_path), error.message),
    )
    return [
        _violation(
            "vv_runtime_schema_validation_failed",
            "schema",
            (
                "ResultProposal runtime schema validation failed at "
                f"{_schema_error_location(error)}: {error.message}"
            ),
        )
        for error in errors
    ]


def _vv_report_schema_violations(report: dict) -> list[dict]:
    validator = _vv_report_validator()
    errors = sorted(
        validator.iter_errors(report),
        key=lambda error: (list(error.absolute_path), error.message),
    )
    return [
        _violation(
            "vv_outgoing_runtime_schema_validation_failed",
            "schema",
            (
                "Outgoing VVReport runtime schema validation failed at "
                f"{_schema_error_location(error)}: {error.message}"
            ),
        )
        for error in errors
    ]


def _clamp_01(value: float) -> float:
    return max(0.0, min(1.0, value))


def _contains_forbidden_key(value) -> bool:
    if isinstance(value, dict):
        return bool(FORBIDDEN_KEYS & set(value)) or any(
            _contains_forbidden_key(child) for child in value.values()
        )
    if isinstance(value, list):
        return any(_contains_forbidden_key(item) for item in value)
    return False


def _critical_risk_present(proposal: dict) -> bool:
    if not isinstance(proposal, dict):
        return True
    risks = proposal.get("risks", [])
    if not isinstance(risks, list):
        return True
    return any(isinstance(risk, dict) and risk.get("severity") == "critical" for risk in risks)


def _compute_cost_score(cost: dict) -> float:
    if not isinstance(cost, dict):
        return 1.0
    tokens = float(cost.get("tokens", 0) or 0)
    walltime_ms = float(cost.get("walltime_ms", 0) or 0)
    toolcalls = float(cost.get("toolcalls", 0) or 0)
    normalized_cost = tokens / 10_000 + walltime_ms / 60_000 + toolcalls / 100
    return _clamp_01(normalized_cost)


def _avf_final_viability(proposal: dict) -> float | None:
    result_payload = proposal.get("result_payload")
    if not isinstance(result_payload, dict):
        return None
    avf = result_payload.get("avf")
    if not isinstance(avf, dict):
        return None
    value = avf.get("final_viability")
    if isinstance(value, (int, float)):
        return _clamp_01(float(value))
    return None


def _avf_vector_id(proposal: dict) -> str | None:
    result_payload = proposal.get("result_payload")
    if not isinstance(result_payload, dict):
        return None
    avf = result_payload.get("avf")
    if isinstance(avf, dict) and avf.get("vector_id"):
        return avf["vector_id"]
    return result_payload.get("vector_id")


def _avf_soft_mask(proposal: dict) -> float | None:
    result_payload = proposal.get("result_payload")
    if not isinstance(result_payload, dict):
        return None
    avf = result_payload.get("avf")
    if not isinstance(avf, dict):
        return None
    value = avf.get("soft_mask")
    if isinstance(value, (int, float)):
        return _clamp_01(float(value))
    return None


def _violation(violation_id: str, kind: str, description: str) -> dict:
    return {
        "violation_id": violation_id,
        "kind": kind,
        "description": description,
    }


def _payload_semantics(candidate: dict) -> dict:
    if not isinstance(candidate, dict):
        return {
            "artifact_type": None,
            "payload_status": None,
            "task_completed": None,
            "requires_human_input": False,
            "blocked_reason": None,
            "needs_user": False,
            "blocked": False,
        }

    result_payload = candidate.get("result_payload")
    if not isinstance(result_payload, dict):
        return {
            "artifact_type": None,
            "payload_status": None,
            "task_completed": None,
            "requires_human_input": False,
            "blocked_reason": None,
            "needs_user": False,
            "blocked": False,
        }

    payload_status = result_payload.get("status")
    task_completed = result_payload.get("task_completed")
    requires_human_input = result_payload.get("requires_human_input", False) is True
    blocked_reason = result_payload.get("blocked_reason")
    needs_user = requires_human_input or payload_status == "needs_user"
    blocked = bool(blocked_reason) or (
        task_completed is False and payload_status == "needs_user"
    )
    return {
        "artifact_type": result_payload.get("artifact_type"),
        "payload_status": payload_status,
        "task_completed": task_completed,
        "requires_human_input": requires_human_input,
        "blocked_reason": blocked_reason,
        "needs_user": needs_user,
        "blocked": blocked,
    }


def _safe_id(value, fallback: str) -> str:
    return value if isinstance(value, str) and value else fallback


def _safe_optional_id(value) -> str | None:
    return value if isinstance(value, str) and value else None


def _safe_trace_refs(candidate: dict) -> list[dict]:
    trace_refs = candidate.get("trace_refs") if isinstance(candidate, dict) else []
    return list(trace_refs) if isinstance(trace_refs, list) else []


def _dependency_depth(candidate: dict) -> int:
    result_payload = candidate.get("result_payload") if isinstance(candidate, dict) else None
    if not isinstance(result_payload, dict):
        return 0
    value = result_payload.get("dependency_depth", 0)
    return value if isinstance(value, int) and value >= 0 else 0


def _safe_rejected_vv_report(
    *,
    proposal_id: str,
    trace_refs: list[dict],
    violations: list[dict],
    checked_at: str | None = None,
) -> dict:
    return {
        "vv_report_id": f"vv:{proposal_id}",
        "proposal_id": proposal_id,
        "status": "rejected",
        "scores": {
            "schema": 0.0,
            "evidence": 0.0,
            "policy": 0.0,
            "time": 0.0,
            "safety": 0.0,
            "consistency": 0.0,
        },
        "overall_score": 0.0,
        "decision": "reject",
        "checked_at": checked_at if checked_at is not None else utc_now_iso(),
        "violations": violations,
        "normalized_features": {
            "utility": 0.0,
            "robustness": 0.0,
            "compute_cost": 0.0,
            "violations": 1.0,
            "transfer": 0.0,
            "novelty_guard": 0.0,
            "avf_final_viability": None,
            "avf_soft_mask": None,
        },
        "trace_refs": trace_refs,
    }


def _validate_outgoing_vv_report(
    report: dict,
    candidate: dict,
    *,
    checked_at: str | None = None,
) -> dict:
    violations = _vv_report_schema_violations(report)
    if not violations:
        return report
    proposal_id = _safe_id(
        candidate.get("proposal_id") if isinstance(candidate, dict) else None,
        "missing_proposal",
    )
    return _safe_rejected_vv_report(
        proposal_id=proposal_id,
        trace_refs=_safe_trace_refs(candidate),
        violations=violations,
        checked_at=checked_at,
    )


def _validate_result_proposal_with_resolved_checked_at_v02(
    proposal: dict,
    *,
    checked_at: str | None,
) -> dict:
    candidate = deepcopy(proposal)
    violations = _result_proposal_schema_violations(candidate)

    schema_score = 0.0 if violations else 1.0
    required_fields_present = (
        isinstance(candidate, dict)
        and REQUIRED_RESULT_PROPOSAL_FIELDS <= set(candidate)
    )
    if not required_fields_present:
        violations.append(
            _violation(
                "vv_schema_missing_required",
                "schema",
                "ResultProposal is missing required fields.",
            )
        )

    evidence = candidate.get("evidence") if isinstance(candidate, dict) else None
    evidence_score = 1.0 if isinstance(evidence, list) and evidence else 0.0
    if evidence_score == 0.0:
        violations.append(
            _violation(
                "vv_evidence_missing",
                "evidence",
                "ResultProposal evidence is missing or empty.",
            )
        )

    policy_score = 0.0 if _contains_forbidden_key(candidate) else 1.0
    if policy_score == 0.0:
        violations.append(
            _violation(
                "vv_policy_forbidden_key",
                "policy",
                "ResultProposal contains a forbidden user-facing or root-only key.",
            )
        )

    time_envelope = candidate.get("time_envelope") if isinstance(candidate, dict) else None
    time_score = (
        1.0
        if isinstance(time_envelope, dict)
        and REQUIRED_TIME_ENVELOPE_FIELDS <= set(time_envelope)
        else 0.0
    )
    if time_score == 0.0:
        violations.append(
            _violation(
                "vv_time_envelope_invalid",
                "time",
                "ResultProposal TimeEnvelope is missing required fields.",
            )
        )

    safety_score = 0.0 if _critical_risk_present(candidate) else 1.0
    if safety_score == 0.0:
        violations.append(
            _violation(
                "vv_safety_critical_risk",
                "safety",
                "ResultProposal contains a critical risk.",
            )
        )

    consistency_score = (
        1.0
        if isinstance(candidate, dict)
        and candidate.get("proposal_id")
        and candidate.get("vector_id")
        and candidate.get("plan_id")
        and isinstance(candidate.get("result_payload"), dict)
        else 0.0
    )
    if consistency_score == 0.0:
        violations.append(
            _violation(
                "vv_consistency_invalid",
                "consistency",
                "ResultProposal identifiers or result_payload are inconsistent.",
            )
        )

    semantics = _payload_semantics(candidate)
    if (
        schema_score == 1.0
        and policy_score == 1.0
        and time_score == 1.0
        and semantics["needs_user"]
    ):
        violations.append(
            _violation(
                "vv_human_input_required",
                "consistency",
                "ResultProposal requires human input before completion.",
            )
        )
    if (
        schema_score == 1.0
        and policy_score == 1.0
        and time_score == 1.0
        and semantics["blocked"]
    ):
        violations.append(
            _violation(
                "vv_blocked_before_completion",
                "consistency",
                "ResultProposal is blocked before completion.",
            )
        )

    scores = {
        "schema": schema_score,
        "evidence": evidence_score,
        "policy": policy_score,
        "time": time_score,
        "safety": safety_score,
        "consistency": consistency_score,
    }
    overall_score = sum(scores.values()) / len(scores)
    avf_final_viability = _avf_final_viability(candidate) if isinstance(candidate, dict) else None
    avf_soft_mask = _avf_soft_mask(candidate) if isinstance(candidate, dict) else None
    utility = overall_score
    if (
        avf_final_viability is not None
        and avf_soft_mask is not None
        and schema_score == 1.0
        and policy_score == 1.0
        and time_score == 1.0
        and safety_score == 1.0
    ):
        avf_utility = (avf_final_viability * 0.9) + (avf_soft_mask * 0.1)
        utility = (overall_score + avf_utility) / 2

    robustness = (evidence_score + consistency_score + time_score) / 3
    semantic_penalty = 0.0
    if semantics["blocked"]:
        semantic_penalty = 0.4
    elif semantics["needs_user"]:
        semantic_penalty = 0.25
    if semantic_penalty:
        utility = _clamp_01(utility * (1.0 - semantic_penalty))
        robustness = _clamp_01(robustness * (1.0 - semantic_penalty / 2))

    if (
        schema_score == 1.0
        and policy_score == 1.0
        and time_score == 1.0
        and safety_score == 1.0
    ):
        if semantics["needs_user"] or semantics["blocked"]:
            decision = "revise"
        else:
            decision = "accept"
    elif schema_score == 0.0 or policy_score == 0.0 or safety_score == 0.0:
        decision = "reject"
    else:
        decision = "revise"

    status = {
        "accept": "accepted",
        "reject": "rejected",
        "revise": "needs_revision",
    }[decision]

    proposal_id = _safe_id(
        candidate.get("proposal_id") if isinstance(candidate, dict) else None,
        "missing_proposal",
    )
    report = {
        "vv_report_id": f"vv:{proposal_id}",
        "proposal_id": proposal_id,
        "dependency_depth": _dependency_depth(candidate),
        "status": status,
        "scores": scores,
        "overall_score": overall_score,
        "decision": decision,
        "checked_at": checked_at if checked_at is not None else utc_now_iso(),
        "violations": violations,
        "normalized_features": {
            "utility": utility,
            "robustness": robustness,
            "compute_cost": _compute_cost_score(candidate.get("cost", {}) if isinstance(candidate, dict) else {}),
            "violations": _clamp_01(1.0 - policy_score + semantic_penalty),
            "transfer": 0.0,
            "novelty_guard": 0.0,
            "avf_final_viability": avf_final_viability,
            "avf_soft_mask": avf_soft_mask,
        },
        "trace_refs": _safe_trace_refs(candidate),
    }
    vector_id = _safe_optional_id(
        candidate.get("vector_id") if isinstance(candidate, dict) else None
    ) or (
        _safe_optional_id(_avf_vector_id(candidate))
        if isinstance(candidate, dict)
        else None
    )
    if vector_id is not None:
        report["vector_id"] = vector_id
    if isinstance(semantics["artifact_type"], str) and semantics["artifact_type"]:
        report["artifact_type"] = semantics["artifact_type"]
    execution_status = semantics["payload_status"] or status
    if isinstance(execution_status, str) and execution_status:
        report["execution_status"] = execution_status
    if isinstance(candidate, dict) and "request_id" in candidate:
        request_id = _safe_optional_id(candidate["request_id"])
        if request_id is not None:
            report["request_id"] = request_id
    # Final outgoing schema boundary; manual checks above remain in force.
    return _validate_outgoing_vv_report(
        report,
        candidate,
        checked_at=checked_at,
    )


def validate_result_proposal(
    proposal: dict,
    *,
    checked_at: str | None = None,
) -> dict:
    resolved_checked_at = _resolve_post_vv_checked_at_v02(checked_at)
    return _validate_result_proposal_with_resolved_checked_at_v02(
        proposal,
        checked_at=resolved_checked_at,
    )


def validate_result_proposals(
    proposals: list[dict],
    *,
    checked_at: str | None = None,
) -> list[dict]:
    resolved_checked_at = _resolve_post_vv_checked_at_v02(checked_at)
    if resolved_checked_at is None:
        return [validate_result_proposal(proposal) for proposal in proposals]
    return [
        _validate_result_proposal_with_resolved_checked_at_v02(
            proposal,
            checked_at=resolved_checked_at,
        )
        for proposal in proposals
    ]

"""Immutable G2-B Root evidence, reuse certificate, and G2-A history transport."""
from __future__ import annotations
from dataclasses import dataclass as _dataclass from dataclasses import replace as _replace from typing import TYPE_CHECKING as _TYPE_CHECKING
from hedgehog.drs_semantic_address_v01 import ( DRS_G2B_PROFILE_VERSION_V01 as _PROFILE_VERSION, ) from hedgehog.drs_semantic_address_v01 import ( _canonical_json_bytes_v01, _canonical_plain_value, _dedupe, _domain_separated_sha256_hex_v01, _is_int64, _is_reference, _is_sha256, _is_token, _plain_data_value, _token_tuple_reasons, )
if _TYPE_CHECKING: from hedgehog.drs_memory_resolution_v01 import DRSResolutionReportV01 from hedgehog.kernel.root_decision_v01 import ( RootDecisionInputV01, RootDecisionKernelV01, RootDecisionResultV01, )
_ENABLED_REUSE_CLASSES = ( "CONTEXT_ONLY", "ANSWER_SHORTCUT", ) _ACTION_LIFECYCLE_STATES = ( "CREATED", "ROOT_AUTHORIZED", "QUEUED", "PENDING_FULFILLMENT", "FULFILLED_MOCK", "RECEIPT_RECEIVED", "FAILED", "BLOCKED", "EXPIRED", "REVOKED", "SUPERSEDED", ) _IDEMPOTENCY_DISPOSITIONS = ( "UNCLAIMED", "RESERVED", "CONSUMED", "UNCERTAIN_CLOSED", ) _EVALUATION_TIME_SOURCES = ( "INJECTED_CURRENT_DECISION_TIME", "RECORDED_HISTORICAL_AS_OF_TIME", "RECORDED_AUDIT_REPLAY_TIME", "INJECTED_ANALYSIS_TIME", ) _B4_ROOT_RESULT_BINDING_DOMAIN_V01 = ( "hedgehog:drs:root_shortcut_root_result_binding:v01" ) _B4_ROOT_SHORTCUT_PREDICATE_V01 = ( "authorize_non_action_informational_answer_shortcut_v01" ) _B4_ROOT_SHORTCUT_POLICY_REF_V01 = "policy:drs_answer_shortcut:v0.1" _B4_INFORMATIONAL_INTENT_CLASSES_V01 = ( "informational_summary", "informational_lookup", "informational_explanation", "context_lookup", "warning_lookup", "historical_inspection", "trend_analysis", )
_ROOT_SHORTCUT_FIELDS = ( "root_shortcut_projection_version", "root_shortcut_projection_id", "owning_local_root_id", "root_kernel_id", "root_decision_input_id", "root_decision_id", "root_decision_hash", "selected_candidate_id", "semantic_address_id", "meaning_record_id", "query_id", "query_evaluation_id", "allowed_reuse_class", "scope_fingerprint", "policy_version", "schema_versions", "valid_from", "valid_to", "root_shortcut_policy_ref", "carries_validated_authority_evidence", "creates_authority", "creates_permission", "creates_action_commit_packet", "creates_receipt", "creates_effect", "creates_final_output", ) _REUSE_CERTIFICATE_FIELDS = ( "certificate_version", "certificate_id", "semantic_address_id", "meaning_record_id", "query_id", "query_evaluation_id", "resolution_candidate_id", "root_shortcut_authorization_projection_id", "owning_local_root_id", "root_decision_input_id", "root_decision_id", "root_decision_hash", "case_type", "scope_fingerprint", "required_evidence_classes", "observed_evidence_fingerprint", "forbidden_changes", "checked_dependency_fingerprint", "valid_from", "valid_to", "reuse_class", "policy_version", "schema_versions", "root_shortcut_policy_ref", "source_history_hash", "action_history_binding_id", "issued_at", "evaluated_at", "creates_authority", "creates_permission", "creates_final_output", "creates_action_commit_packet", "creates_receipt", "creates_capability", "creates_effect_handle", "creates_effect", "real_world_effects_count", "proves_external_truth", "proves_action_occurred", ) _G2A_HISTORY_FIELDS = ( "binding_version", "binding_id", "packet_id", "registry_id", "transition_history_sha256", "disposition_history_sha256", "lifecycle_state", "disposition", "reservation_owner_packet_id", "terminal_receipt_ref", "current_status_validation_id", "current_status_evaluated_at", "current_status_evaluation_time_source", "shortcut_eligible", "reason_codes", "creates_authority", "creates_permission", ) _IDENTITY_PROFILES = ( ( "RootShortcutAuthorizationProjectionV01", "root_shortcut_projection_id", "hedgehog:drs:root_shortcut_projection:v01", "drsrootshortcut_v01:", _ROOT_SHORTCUT_FIELDS, ), ( "ReuseCertificateV01", "certificate_id", "hedgehog:drs:reuse_certificate:v01", "reusecert_v01:", _REUSE_CERTIFICATE_FIELDS, ), ( "G2AActionHistoryBindingV01", "binding_id", "hedgehog:drs:g2a_history_binding:v01", "drsg2ahistory_v01:", _G2A_HISTORY_FIELDS, ), )
@_dataclass(frozen=True) class RootShortcutAuthorizationProjectionV01: root_shortcut_projection_version: str root_shortcut_projection_id: str owning_local_root_id: str root_kernel_id: str root_decision_input_id: str root_decision_id: str root_decision_hash: str selected_candidate_id: str semantic_address_id: str meaning_record_id: str query_id: str query_evaluation_id: str allowed_reuse_class: str scope_fingerprint: str policy_version: str schema_versions: tuple[str, ...] valid_from: int valid_to: int root_shortcut_policy_ref: str carries_validated_authority_evidence: bool creates_authority: bool creates_permission: bool creates_action_commit_packet: bool creates_receipt: bool creates_effect: bool creates_final_output: bool
