def _plain_value(value: object) -> object: if type(value) is RootShortcutAuthorizationProjectionV01: return { name: _plain_value(getattr(value, name)) for name in _ROOT_SHORTCUT_FIELDS } if type(value) is ReuseCertificateV01: return { name: _plain_value(getattr(value, name)) for name in _REUSE_CERTIFICATE_FIELDS } if type(value) is G2AActionHistoryBindingV01: return { name: _plain_value(getattr(value, name)) for name in _G2A_HISTORY_FIELDS } return _plain_data_value(value)
def _identity_value(value: object) -> object: if type(value) is tuple: return [_identity_value(item) for item in value] return _canonical_plain_value(value)
def _profile(type_name: str) -> tuple[str, str, str, tuple[str, ...]]: for name, identity_field, domain, prefix, fields in _IDENTITY_PROFILES: if name == type_name: return identity_field, domain, prefix, fields raise ValueError("drs_identity_profile_invalid")
def _identity(value: object, type_name: str) -> str: identity_field, domain, prefix, fields = _profile(type_name) material = [ _identity_value(getattr(value, name)) for name in fields if name != identity_field ] digest = _domain_separated_sha256_hex_v01( domain=domain, payload=_canonical_json_bytes_v01(material), ) return prefix + digest
def _id_reason(value: object, type_name: str) -> str | None: identity_field, _, prefix, _ = _profile(type_name) actual = getattr(value, identity_field) if ( type(actual) is not str or not actual.startswith(prefix) or len(actual) != len(prefix) + 64 or not _is_sha256(actual[len(prefix):]) ): return "drs_identity_invalid" if actual != _identity(value, type_name): if type_name == "ReuseCertificateV01": return "reuse_certificate_identity_invalid" return "drs_identity_invalid" return None
def _finish( provisional: object, *, type_name: str, reasons: tuple[str, ...], validator: object, ) -> object: if reasons: raise ValueError(reasons[0]) from None identity_field, _, _, _ = _profile(type_name) final = _replace( provisional, **{identity_field: _identity(provisional, type_name)}, ) if not callable(validator): raise ValueError("drs_builder_invalid") from None valid, final_reasons = validator(final) if not valid: raise ValueError(final_reasons[0]) from None return final
