from __future__ import annotations

from datetime import datetime


REUSE_THRESHOLD = 0.75
FRESHNESS_THRESHOLD = 0.5
GT_TRUST_THRESHOLD = 0.5


def _clamp_01(value: float) -> float:
    return max(0.0, min(1.0, value))


def _parse_timestamp(value: str) -> datetime:
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def compute_freshness_score(record: dict, temporal_query: dict) -> float:
    envelope = record.get("time_envelope", {})
    record_time = envelope.get("kt_asof") or envelope.get("pt_created_at")
    as_of = temporal_query.get("as_of")
    if not record_time or not as_of:
        return 0.0

    age_seconds = max(
        0.0,
        (_parse_timestamp(as_of) - _parse_timestamp(record_time)).total_seconds(),
    )
    max_age_seconds = float(temporal_query.get("max_age_seconds") or 2_592_000)
    if max_age_seconds <= 0:
        return 0.0
    return _clamp_01(1.0 - (age_seconds / max_age_seconds))


def compute_gt_trust_score(record: dict) -> float:
    gt = record.get("gt", {})
    half_life_hours = float(gt.get("half_life_hours") or 0.0)
    decay_rate = float(gt.get("decay_rate") or 1.0)
    half_life_score = _clamp_01(half_life_hours / 1_000.0)
    decay_score = _clamp_01(1.0 / (1.0 + decay_rate * 1_000.0))
    return (half_life_score + decay_score) / 2


def compute_policy_score(record: dict) -> float:
    status = record.get("status")
    if status in {"rejected", "archived"}:
        return 0.0
    if status in {"accepted", "active"}:
        return 1.0
    return 0.5


def compute_conflict_score(record: dict) -> float:
    content = record.get("content", {})
    text = str(content).lower()
    conflict_markers = ("failure", "failed", "dead_end", "deadend", "conflict")
    if any(marker in text for marker in conflict_markers):
        return 0.0
    return 1.0


def compute_reuse_score(record: dict, temporal_query: dict) -> dict:
    freshness = compute_freshness_score(record, temporal_query)
    gt_trust = compute_gt_trust_score(record)
    policy = compute_policy_score(record)
    conflict = compute_conflict_score(record)
    reuse_score = (
        0.30 * freshness
        + 0.30 * gt_trust
        + 0.25 * policy
        + 0.15 * conflict
    )
    eligible = (
        reuse_score >= REUSE_THRESHOLD
        and freshness >= FRESHNESS_THRESHOLD
        and gt_trust >= GT_TRUST_THRESHOLD
        and policy == 1.0
        and conflict == 1.0
    )
    if eligible:
        reason = "eligible"
    elif policy == 0.0:
        reason = "policy_rejected"
    elif conflict == 0.0:
        reason = "conflict_detected"
    elif reuse_score < REUSE_THRESHOLD:
        reason = "reuse_score_below_threshold"
    elif freshness < FRESHNESS_THRESHOLD:
        reason = "freshness_below_threshold"
    elif gt_trust < GT_TRUST_THRESHOLD:
        reason = "gt_trust_below_threshold"
    else:
        reason = "reuse_score_below_threshold"

    return {
        "record_id": record.get("record_id"),
        "freshness": freshness,
        "gt_trust": gt_trust,
        "policy": policy,
        "conflict": conflict,
        "reuse_score": reuse_score,
        "eligible": eligible,
        "reason": reason,
    }


def evaluate_reuse_candidates(records: list[dict], temporal_query: dict) -> dict:
    if not records:
        return {
            "reuse_decision": "none",
            "best_record_id": None,
            "reused_record_ids": [],
            "candidate_scores": [],
        }

    candidate_scores = [
        compute_reuse_score(record, temporal_query)
        for record in records
    ]
    best = max(
        candidate_scores,
        key=lambda score: (score["reuse_score"], score["record_id"] or ""),
    )
    eligible_scores = [score for score in candidate_scores if score["eligible"]]
    reuse_decision = "direct_reuse_candidate" if eligible_scores else "context_only"

    return {
        "reuse_decision": reuse_decision,
        "best_record_id": best["record_id"],
        "reused_record_ids": [],
        "candidate_scores": candidate_scores,
    }

from __future__ import annotations

from collections.abc import Iterable, Mapping
from typing import Any


"""
Dual Rich Context Structured Rationale core contracts.

Structured rationale is JSON explanation, bounded, auditable,
user-readable, and machine-validatable.

Structured rationale is not truth.
Structured rationale is not authority.
Structured rationale is not action permission.
Structured rationale is not FinalOutput.
Structured rationale is not ActionCommitPacket.
Root remains final authority.
"""


STRUCTURED_RATIONALE_SCHEMA_VERSION = "structured_rationale_v0.1"
ORCHESTRATOR_STRUCTURED_RATIONALE_TYPE = "structured_orchestrator_rationale"
ARCHITECT_STRUCTURED_RATIONALE_TYPE = "structured_architect_rationale"

ORCHESTRATOR_STRUCTURED_RATIONALE_REQUIRED_FIELDS = (
    "observed_semantics",
    "route_selection_reason",
    "rejected_routes",
    "required_guards_reasoning",
    "selected_vector_reasoning",
    "uncertainty_notes",
    "authority_boundary",
    "root_review_required",
)

ARCHITECT_STRUCTURED_RATIONALE_REQUIRED_FIELDS = (
    "plan_shape_reason",
    "node_selection_reasoning",
    "executor_constraint_reasoning",
    "forbidden_surface_review",
    "validator_coverage_reasoning",
    "return_to_root_path",
    "uncertainty_notes",
    "authority_boundary",
    "root_review_required",
)

ORCHESTRATOR_STRUCTURED_RATIONALE_ROLE_BOUNDARY_FIELDS = (
    "orchestrator_is_root",
    "creates_action_commit_packet",
    "calls_connectors",
)

ARCHITECT_STRUCTURED_RATIONALE_ROLE_BOUNDARY_FIELDS = (
    "architect_is_root",
    "creates_action_commit_packet",
    "calls_connectors",
)

_COMMON_REQUIRED_FIELDS = (
    "rationale_type",
    "schema_version",
    "truth_claimed",
    "authority_claimed",
    "action_permission_claimed",
    "final_output_claimed",
    "connector_command_claimed",
    "drs_write_claimed",
    "action_commit_packet_claimed",
    "root_bypass_claimed",
    "root_final_authority_preserved",
    "Root remains final authority",
)

_COMMON_FORBIDDEN_CLAIMS = {
    "truth_claimed": "structured_rationale_truth_claim_forbidden",
    "authority_claimed": "structured_rationale_authority_claim_forbidden",
    "action_permission_claimed": (
        "structured_rationale_action_permission_claim_forbidden"
    ),
    "final_output_claimed": "structured_rationale_final_output_claim_forbidden",
    "connector_command_claimed": "structured_rationale_connector_command_forbidden",
    "drs_write_claimed": "structured_rationale_drs_write_forbidden",
    "action_commit_packet_claimed": (
        "structured_rationale_action_commit_packet_forbidden"
    ),
    "root_bypass_claimed": "structured_rationale_root_bypass_forbidden",
}

_RAW_TEXT_MARKERS = (
    "raw_user_text",
    "raw_" + "ge" + "mini_text",
    "raw_cross_role_text",
    "hidden_chain_of_thought",
    "chain_of_thought",
    "private_reasoning",
    "internal_monologue",
)

_UNBOUNDED_DUMP_MARKERS = (
    "full_runner_state_dump",
    "unbounded_context_dump",
    "raw_plan_graph_context",
    "raw_plangraph_context",
)

_SECRET_MARKERS = (
    "api_key",
    "secret",
    "token",
    "password",
    "private_key",
)

_MAX_STRING_LENGTH = 512
_MAX_COLLECTION_LENGTH = 50
_MAX_DEPTH = 8


def _append_reason(reasons: list[str], reason: str) -> None:
    if reason not in reasons:
        reasons.append(reason)


def _as_bounded_field(value: Any, default: Any) -> Any:
    if value is None:
        value = default
    if isinstance(value, Mapping):
        return dict(value)
    if isinstance(value, str):
        return (value,)
    if isinstance(value, Iterable):
        return tuple(value)
    return (value,)


def _default_claims() -> dict[str, Any]:
    return {
        "truth_claimed": False,
        "authority_claimed": False,
        "action_permission_claimed": False,
        "final_output_claimed": False,
        "connector_command_claimed": False,
        "drs_write_claimed": False,
        "action_commit_packet_claimed": False,
        "root_bypass_claimed": False,
        "root_final_authority_preserved": True,
        "Root remains final authority": True,
    }


def _validation_result(
    reasons: Iterable[str],
    rationale_type: str | None,
) -> dict[str, Any]:
    reason_tuple = tuple(reasons)
    return {
        "accepted": not reason_tuple,
        "reasons": reason_tuple,
        "rationale_type": rationale_type,
    }


def _rationale_type_value(rationale: Mapping[str, Any]) -> str | None:
    rationale_type = rationale.get("rationale_type")
    if isinstance(rationale_type, str):
        return rationale_type
    return None


def _walk_key_values(
    value: Any,
    *,
    depth: int = 0,
) -> Iterable[tuple[str | None, Any, int]]:
    if isinstance(value, Mapping):
        for key, item in value.items():
            yield str(key), item, depth
            yield from _walk_key_values(item, depth=depth + 1)
    elif isinstance(value, (list, tuple, set, frozenset)):
        for item in value:
            yield None, item, depth
            yield from _walk_key_values(item, depth=depth + 1)


def _add_raw_or_secret_reasons(value: Mapping[str, Any], reasons: list[str]) -> None:
    for key, item, _depth in _walk_key_values(value):
        key_text = (key or "").lower()
        value_text = item.lower() if isinstance(item, str) else ""
        for marker in _RAW_TEXT_MARKERS:
            if marker in key_text or marker in value_text:
                _append_reason(reasons, "structured_rationale_raw_text_forbidden")
        for marker in _UNBOUNDED_DUMP_MARKERS:
            if marker in key_text or marker in value_text:
                _append_reason(
                    reasons,
                    "structured_rationale_unbounded_dump_forbidden",
                )
        for marker in _SECRET_MARKERS:
            if marker in key_text or marker in value_text:
                _append_reason(
                    reasons,
                    f"structured_rationale_secret_marker_forbidden:{marker}",
                )


def _add_unbounded_reasons(value: Any, reasons: list[str], *, depth: int = 0) -> None:
    if depth > _MAX_DEPTH:
        _append_reason(reasons, "structured_rationale_unbounded_dump_forbidden")
        return
    if isinstance(value, str):
        if len(value) > _MAX_STRING_LENGTH:
            _append_reason(reasons, "structured_rationale_unbounded_dump_forbidden")
        return
    if isinstance(value, Mapping):
        if len(value) > _MAX_COLLECTION_LENGTH:
            _append_reason(reasons, "structured_rationale_unbounded_dump_forbidden")
        for item in value.values():
            _add_unbounded_reasons(item, reasons, depth=depth + 1)
        return
    if isinstance(value, (list, tuple, set, frozenset)):
        if len(value) > _MAX_COLLECTION_LENGTH:
            _append_reason(reasons, "structured_rationale_unbounded_dump_forbidden")
        for item in value:
            _add_unbounded_reasons(item, reasons, depth=depth + 1)


def _add_common_validation_reasons(
    rationale: Mapping[str, Any],
    *,
    expected_type: str,
    required_fields: Iterable[str],
    explanation_fields: Iterable[str],
) -> list[str]:
    reasons: list[str] = []
    for field in (*_COMMON_REQUIRED_FIELDS, *tuple(required_fields)):
        if field not in rationale:
            _append_reason(
                reasons,
                f"structured_rationale_missing_required_field:{field}",
            )

    rationale_type = rationale.get("rationale_type")
    if rationale_type != expected_type:
        _append_reason(
            reasons,
            f"structured_rationale_unexpected_type:{rationale_type}",
        )
    if rationale.get("schema_version") != STRUCTURED_RATIONALE_SCHEMA_VERSION:
        _append_reason(reasons, "structured_rationale_schema_version_invalid")

    for field, reason in _COMMON_FORBIDDEN_CLAIMS.items():
        if bool(rationale.get(field)):
            _append_reason(reasons, reason)

    if rationale.get("root_review_required") is not True:
        _append_reason(reasons, "root_review_required_must_be_true")
    if rationale.get("root_final_authority_preserved") is not True:
        _append_reason(reasons, "root_final_authority_must_be_preserved")
    if rationale.get("Root remains final authority") is not True:
        _append_reason(reasons, "root_final_authority_must_be_preserved")

    for field in explanation_fields:
        if field == "root_review_required" or field not in rationale:
            continue
        value = rationale[field]
        if isinstance(value, str):
            _append_reason(reasons, "structured_rationale_raw_text_forbidden")
        elif not isinstance(value, (Mapping, list, tuple)):
            _append_reason(reasons, "structured_rationale_unbounded_dump_forbidden")

    _add_raw_or_secret_reasons(rationale, reasons)
    _add_unbounded_reasons(rationale, reasons)
    return reasons


def build_orchestrator_structured_rationale(
    *,
    observed_semantics: Any = None,
    route_selection_reason: Any = None,
    rejected_routes: Any = None,
    required_guards_reasoning: Any = None,
    selected_vector_reasoning: Any = None,
    uncertainty_notes: Any = None,
    authority_boundary: Any = None,
    root_review_required: bool = True,
) -> dict[str, Any]:
    rationale = {
        "rationale_type": ORCHESTRATOR_STRUCTURED_RATIONALE_TYPE,
        "schema_version": STRUCTURED_RATIONALE_SCHEMA_VERSION,
        "observed_semantics": _as_bounded_field(
            observed_semantics,
            (
                {
                    "summary": "bounded semantic observations require Root review",
                    "truth_claimed": False,
                },
            ),
        ),
        "route_selection_reason": _as_bounded_field(
            route_selection_reason,
            (
                {
                    "route": "bounded_review_route",
                    "reason": "route remains advisory until Root review",
                },
            ),
        ),
        "rejected_routes": _as_bounded_field(
            rejected_routes,
            (
                {
                    "route": "direct_action_route",
                    "reason": "direct action is outside bounded proposal authority",
                },
            ),
        ),
        "required_guards_reasoning": _as_bounded_field(
            required_guards_reasoning,
            (
                {
                    "guard": "root_review_required",
                    "reason": "Root remains final authority",
                },
            ),
        ),
        "selected_vector_reasoning": _as_bounded_field(
            selected_vector_reasoning,
            (
                {
                    "vector_scope": "allowed_context_vectors",
                    "reason": "selection is advisory only",
                },
            ),
        ),
        "uncertainty_notes": _as_bounded_field(
            uncertainty_notes,
            (
                {
                    "note": "unresolved facts require bounded review",
                },
            ),
        ),
        "authority_boundary": _as_bounded_field(
            authority_boundary,
            (
                {
                    "role": "orchestrator",
                    "is_root": False,
                    "creates_final_output": False,
                },
            ),
        ),
        "root_review_required": root_review_required,
        "orchestrator_is_root": False,
        "creates_action_commit_packet": False,
        "calls_connectors": False,
        **_default_claims(),
    }
    return rationale


def validate_orchestrator_structured_rationale(rationale: Any) -> dict[str, Any]:
    if not isinstance(rationale, Mapping):
        return _validation_result(
            ("structured_rationale_must_be_mapping",),
            None,
        )

    reasons = _add_common_validation_reasons(
        rationale,
        expected_type=ORCHESTRATOR_STRUCTURED_RATIONALE_TYPE,
        required_fields=(
            *ORCHESTRATOR_STRUCTURED_RATIONALE_REQUIRED_FIELDS,
            *ORCHESTRATOR_STRUCTURED_RATIONALE_ROLE_BOUNDARY_FIELDS,
        ),
        explanation_fields=ORCHESTRATOR_STRUCTURED_RATIONALE_REQUIRED_FIELDS,
    )
    if bool(rationale.get("orchestrator_is_root")):
        _append_reason(reasons, "orchestrator_is_not_root")
    if bool(rationale.get("creates_action_commit_packet")):
        _append_reason(reasons, "orchestrator_cannot_create_action_commit_packet")
    if bool(rationale.get("calls_connectors")):
        _append_reason(reasons, "orchestrator_cannot_call_connectors")

    return _validation_result(reasons, _rationale_type_value(rationale))


def build_architect_structured_rationale(
    *,
    plan_shape_reason: Any = None,
    node_selection_reasoning: Any = None,
    executor_constraint_reasoning: Any = None,
    forbidden_surface_review: Any = None,
    validator_coverage_reasoning: Any = None,
    return_to_root_path: Any = None,
    uncertainty_notes: Any = None,
    authority_boundary: Any = None,
    root_review_required: bool = True,
) -> dict[str, Any]:
    rationale = {
        "rationale_type": ARCHITECT_STRUCTURED_RATIONALE_TYPE,
        "schema_version": STRUCTURED_RATIONALE_SCHEMA_VERSION,
        "plan_shape_reason": _as_bounded_field(
            plan_shape_reason,
            (
                {
                    "shape": "bounded_semantic_work",
                    "reason": (
                        "bounded semantic proposal remains advisory until local "
                        "validation"
                    ),
                },
            ),
        ),
        "node_selection_reasoning": _as_bounded_field(
            node_selection_reasoning,
            (
                {
                    "node_scope": "bounded_semantic_work",
                    "reason": (
                        "semantic proposal does not assign execution nodes; "
                        "RuntimeExecutionTopology is materialized and owned by "
                        "local runtime"
                    ),
                },
            ),
        ),
        "executor_constraint_reasoning": _as_bounded_field(
            executor_constraint_reasoning,
            (
                {
                    "executor_scope": "bounded_semantic_work",
                    "reason": (
                        "semantic proposal does not assign executors; runtime "
                        "owns RuntimeExecutionTopology executor assignments"
                    ),
                },
            ),
        ),
        "forbidden_surface_review": _as_bounded_field(
            forbidden_surface_review,
            (
                {
                    "surface": "connector_or_action_or_final_output",
                    "status": "blocked",
                },
            ),
        ),
        "validator_coverage_reasoning": _as_bounded_field(
            validator_coverage_reasoning,
            (
                {
                    "validators": (
                        "semantic_work_contract",
                        "Post V&V",
                        "GT/LGT",
                        "Root final authority",
                    ),
                    "reason": "proposal must return upward through validators",
                },
            ),
        ),
        "return_to_root_path": _as_bounded_field(
            return_to_root_path,
            (
                {
                    "path": "proposal_to_validation_to_root",
                    "final_authority": "root_only",
                },
            ),
        ),
        "uncertainty_notes": _as_bounded_field(
            uncertainty_notes,
            (
                {
                    "note": "unresolved facts require Root review",
                },
            ),
        ),
        "authority_boundary": _as_bounded_field(
            authority_boundary,
            (
                {
                    "role": "architect",
                    "is_root": False,
                    "creates_final_output": False,
                },
            ),
        ),
        "root_review_required": root_review_required,
        "architect_is_root": False,
        "creates_action_commit_packet": False,
        "calls_connectors": False,
        **_default_claims(),
    }
    return rationale


def validate_architect_structured_rationale(rationale: Any) -> dict[str, Any]:
    if not isinstance(rationale, Mapping):
        return _validation_result(
            ("structured_rationale_must_be_mapping",),
            None,
        )

    reasons = _add_common_validation_reasons(
        rationale,
        expected_type=ARCHITECT_STRUCTURED_RATIONALE_TYPE,
        required_fields=(
            *ARCHITECT_STRUCTURED_RATIONALE_REQUIRED_FIELDS,
            *ARCHITECT_STRUCTURED_RATIONALE_ROLE_BOUNDARY_FIELDS,
        ),
        explanation_fields=ARCHITECT_STRUCTURED_RATIONALE_REQUIRED_FIELDS,
    )
    if bool(rationale.get("architect_is_root")):
        _append_reason(reasons, "architect_is_not_root")
    if bool(rationale.get("creates_action_commit_packet")):
        _append_reason(reasons, "architect_cannot_create_action_commit_packet")
    if bool(rationale.get("calls_connectors")):
        _append_reason(reasons, "architect_cannot_call_connectors")

    return _validation_result(reasons, _rationale_type_value(rationale))

from __future__ import annotations

from datetime import UTC, datetime


def utc_now_iso() -> str:
    return datetime.now(UTC).isoformat()


def make_time_envelope(
    session_anchor: str,
    ttl_seconds: int = 2_592_000,
    freshness_class: str = "normal",
) -> dict:
    now = utc_now_iso()
    return {
        "pt_created_at": now,
        "kt_asof": now,
        "et_observed_at": None,
        "ct_session_anchor": session_anchor,
        "ttl_seconds": ttl_seconds,
        "freshness_class": freshness_class,
        "valid_from": now,
        "valid_to": None,
    }


def make_temporal_query(
    max_age_seconds: int = 2_592_000,
    freshness_bias: str = "prefer_recent",
) -> dict:
    now = utc_now_iso()
    return {
        "as_of": now,
        "time_range": {
            "from": None,
            "to": now,
        },
        "freshness_bias": freshness_bias,
        "max_age_seconds": max_age_seconds,
        "freshness_required": "normal",
    }

"""Finite import-free integer Wasm profile, supervised in a disposable process.
The closed binary grammar is independent of Wasmtime's feature defaults. Wall supervision bounds this worker, not whole-host RSS or engine defects. """ from dataclasses import dataclass import base64 import hashlib import importlib.metadata import json import os from pathlib import Path import subprocess import sys import tempfile import time
ENGINE_VERSION = '48.0.0' PROFILE_VERSION = 'pure-i32-closed-v01' MAX_BYTES = 16384 MAX_FUEL = 100000 MAX_WALL = 30.0 MAX_OUTPUT = 65536 DISABLED_FEATURES = ('wasm_threads', 'wasm_tail_call', 'wasm_reference_types', 'wasm_simd', 'wasm_bulk_memory', 'wasm_multi_value', 'wasm_multi_memory', 'wasm_memory64', 'wasm_relaxed_simd', 'wasm_component_model', 'wasm_component_model_map', 'wasm_exceptions', 'wasm_function_references', 'wasm_gc', 'wasm_wide_arithmetic', 'wasm_custom_page_sizes', 'wasm_stack_switching')
@dataclass(frozen=True) class PureWorkerResultV01: status: str reason: str | None phase: str wasm: bytes trials: tuple[tuple[int, int, int], ...] engine_version: str profile_version: str configuration_sha256: str elapsed_seconds: float return_code: int process_reaped: bool stdout: bytes stderr: bytes measured_fuel: int
def _require(ok, reason): if not ok: raise ValueError(reason)
class _Reader: def __init__(self, data): self.data, self.pos = data, 0
def byte(self): _require(self.pos < len(self.data), 'profile_truncated') value = self.data[self.pos] self.pos += 1 return value
def take(self, n): _require(0 <= n <= len(self.data) - self.pos, 'profile_truncated') value = self.data[self.pos:self.pos + n] self.pos += n return value
def integer(self, signed=False): value = 0 for i in range(5): b = self.byte() value |= (b & 127) << (7 * i) if not b & 128: bits = 7 * (i + 1) if signed and b & 64: value -= 1 << bits _require(-(1 << 31) <= value < (1 << 31) if signed else 0 <= value < (1 << 32), 'profile_integer_range') return value raise ValueError('profile_integer_encoding')
def done(self): _require(self.pos == len(self.data), 'profile_trailing_data')
def validate_closed_pure_wasm_v01(wasm): _require(type(wasm) is bytes and 8 <= len(wasm) <= MAX_BYTES, 'profile_byte_limit') r = _Reader(wasm) _require(r.take(8) == b'\x00asm\x01\x00\x00\x00', 'profile_raw_wasm_required') sections = [] while r.pos < len(wasm): kind = r.byte() _require(kind in (1, 3, 7, 10) and (not sections or kind > sections[-1]), 'profile_section_forbidden:' + str(kind)) sections.append(kind) s = _Reader(r.take(r.integer())) if kind == 1: _require(s.integer() == 1 and s.byte() == 0x60 and s.integer() == 1 and s.byte() == 0x7f and s.integer() == 1 and s.byte() == 0x7f, 'profile_function_type') elif kind == 3: _require(s.integer() == 1 and s.integer() == 0, 'profile_function_count') elif kind == 7: _require(s.integer() == 1 and s.take(s.integer()) == b'transform' and s.byte() == 0 and s.integer() == 0, 'profile_exact_export') else: _require(s.integer() == 1, 'profile_body_count') body = _Reader(s.take(s.integer())) groups = body.integer() _require(groups <= 32, 'profile_local_groups') locals_count = 1 for _ in range(groups): locals_count += body.integer() _require(body.byte() == 0x7f and locals_count <= 64, 'profile_local_type_or_count') depth = 1 while depth: op = body.byte() if op in (0x02, 0x03, 0x04): _require(body.byte() in (0x40, 0x7f), 'profile_block_type') depth += 1 _require(depth <= 64, 'profile_nesting') elif op == 0x0b: depth -= 1 elif op in (0x0c, 0x0d): _require(body.integer() < depth, 'profile_branch_depth') elif op in (0x20, 0x21, 0x22): _require(body.integer() < locals_count, 'profile_local_index') elif op == 0x41: body.integer(signed=True) else: _require(op in (0x00, 0x01, 0x05, 0x0f, 0x1a, 0x1b) or 0x45 <= op <= 0x4f or 0x67 <= op <= 0x78, 'profile_opcode_forbidden:' + str(op)) body.done() s.done() _require(sections == [1, 3, 7, 10], 'profile_required_sections') return True
def pure_engine_configuration_v01(): return dict(engine=ENGINE_VERSION, profile=PROFILE_VERSION, disabled_features=list(DISABLED_FEATURES), consume_fuel=True, limits=dict(memory_size=0, table_elements=0, instances=1, tables=0, memories=0), max_fuel=MAX_FUEL, max_bytes=MAX_BYTES, max_wall_seconds=MAX_WALL, no_imports=True, no_start=True, fresh_store_per_call=True)
def _config_digest(): return hashlib.sha256(json.dumps(pure_engine_configuration_v01(), sort_keys=True, separators=(',', ':')).encode()).hexdigest()
def _emit(value): raw = json.dumps(value, sort_keys=True, separators=(',', ':')) _require(len(raw) < MAX_OUTPUT, 'worker_output_limit') print(raw, flush=True)
def _worker(request): _require(type(request) is dict and set(request)=={'source','format','inputs','fuel'}, 'worker_request_shape') _require(type(request['source']) is str and len(request['source']) <= 4*((MAX_BYTES+2)//3) and request['format'] in ('wat','wasm'), 'worker_request_source') _require(type(request['inputs']) is list and 0 < len(request['inputs']) <= 256 and all(type(v) is int and 0 <= v <= 255 for v in request['inputs']), 'worker_input_domain') _require(type(request['fuel']) is int and 0 < request['fuel'] <= MAX_FUEL, 'worker_resource_limit') import wasmtime _require(importlib.metadata.version('wasmtime') == ENGINE_VERSION, 'engine_pin_mismatch') _emit(dict(phase='conversion')) raw = base64.b64decode(request['source'], validate=True) _require(len(raw) <= MAX_BYTES, 'profile_byte_limit') wasm = bytes(wasmtime.wat2wasm(raw.decode('utf-8'))) if request['format'] == 'wat' else raw validate_closed_pure_wasm_v01(wasm) _emit(dict(phase='compile')) config = wasmtime.Config() for name in DISABLED_FEATURES: setattr(config, name, False) config.consume_fuel = True engine = wasmtime.Engine(config) module = wasmtime.Module(engine, wasm) _require(len(module.imports) == 0, 'worker_imports') _emit(dict(phase='trials')) trials = [] for value in request['inputs']: _require(type(value) is int and 0 <= value <= 255, 'worker_input_domain') with wasmtime.Store(engine) as store: store.set_limits(**pure_engine_configuration_v01()['limits']) store.set_fuel(request['fuel']) try: instance = wasmtime.Instance(store, module, []) output = instance.exports(store)['transform'](store, value) _require(type(output) is int and 0 <= output <= 255, 'worker_output_domain') except Exception: _emit(dict(phase='trial_refused', completed_trials=trials, measured_fuel=sum(t[2] for t in trials)+request['fuel']-store.get_fuel())) raise trials.append([value, output, request['fuel'] - store.get_fuel()]) _emit(dict(phase='complete', status='SUCCEEDED', wasm=base64.b64encode(wasm).decode(), trials=trials, configuration_sha256=_config_digest(), engine_version=ENGINE_VERSION))
def run_pure_wasm_worker_v01(source, *, source_format, inputs, fuel=MAX_FUEL, wall_seconds=MAX_WALL): _require(type(source) is bytes and 0 < len(source) <= MAX_BYTES, 'worker_source_limit') _require(source_format in ('wat', 'wasm'), 'worker_source_format') _require(type(inputs) is tuple and 0 < len(inputs) <= 256 and all(type(v) is int and 0 <= v <= 255 for v in inputs), 'worker_input_domain') _require(type(fuel) is int and 0 < fuel <= MAX_FUEL and type(wall_seconds) in (int, float) and 0 < wall_seconds <= MAX_WALL, 'worker_resource_limit') request = json.dumps(dict(source=base64.b64encode(source).decode(), format=source_format, inputs=inputs, fuel=fuel)).encode() start = time.monotonic() timed_out = output_limit = False with tempfile.TemporaryDirectory(prefix='radiolaria-pure-worker-') as directory: directory = Path(directory) (directory/'input').write_bytes(request) with (directory/'input').open('rb') as input_file, (directory/'stdout').open('wb') as out, (directory/'stderr').open('wb') as err: process = subprocess.Popen([sys.executable, '-B', '-m', __name__], stdin=input_file, stdout=out, stderr=err, env=os.environ.copy()) try: while process.poll() is None: timed_out = time.monotonic() - start >= wall_seconds output_limit = (directory/'stdout').stat().st_size + (directory/'stderr').stat().st_size > MAX_OUTPUT if timed_out or output_limit: process.kill() break time.sleep(min(0.01, wall_seconds)) process.wait() finally: if process.poll() is None: process.kill() process.wait() stdout = (directory/'stdout').read_bytes()[:MAX_OUTPUT] stderr = (directory/'stderr').read_bytes()[:MAX_OUTPUT] messages = [] for line in stdout.splitlines(): try: messages.append(json.loads(line)) except (ValueError, UnicodeError): pass last = messages[-1] if messages else {} phase = last.get('phase', 'startup') reason = ('worker_wall_timeout' if timed_out else 'worker_output_limit' if output_limit else last.get('reason', 'worker_process_failed') if process.returncode or last.get('status') != 'SUCCEEDED' else None) return PureWorkerResultV01('REFUSED' if reason else 'SUCCEEDED', reason, phase, base64.b64decode(last['wasm']) if reason is None else b'', tuple(tuple(t) for t in last['trials']) if reason is None else (), ENGINE_VERSION, PROFILE_VERSION, _config_digest(), time.monotonic() - start, process.returncode, process.poll() is not None, stdout, stderr, sum(t[2] for t in last['trials']) if reason is None else next((m['measured_fuel'] for m in reversed(messages) if 'measured_fuel' in m),0))
def main(): try: raw = sys.stdin.buffer.read(MAX_OUTPUT + 1) _require(len(raw) <= MAX_OUTPUT, 'worker_message_limit') _worker(json.loads(raw)) return 0 except Exception as exc: _emit(dict(status='REFUSED', reason=type(exc).__name__ + ':' + str(exc), phase='rejection')) return 1
if __name__ == '__main__': raise SystemExit(main())

"""One-Root current-state owner for admitted, offline action execution.

Trusted setup installs immutable packet inputs and a catalogue. Public dispatch
accepts IDs and a revision, never a caller-selected historical registry.
"""
from threading import RLock
from dataclasses import dataclass, replace, field
import hashlib
import inspect
from pathlib import Path
import sys
import types
from hedgehog import action_commit_packet_v02 as action
from hedgehog.kernel import effect_firewall_v01 as firewall
from hedgehog.kernel import transition_registry_v01 as transitions
from contextlib import contextmanager as _contextmanager
from contextvars import ContextVar as _ContextVar
from dataclasses import fields as _fields, is_dataclass as _is_dataclass
from threading import get_ident as _get_ident


@dataclass(frozen=True)
class TrustedWorkSourceSnapshotV01:
